SELECT 'moj-all-verified-judgments-review-002-chunk-092' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5745ce18-e511-56b7-8be1-1c7604731bcc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج وتعاطيها والشروع يف ترويجها -إقرار -حد املسكر -التعزير للتهمة القوية - تعزير بالسجن واجللد .","document_number":"33381189","case_number":"33468056","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافق على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/15","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج وتعاطيها والشروع يف ترويجها -إقرار -حد املسكر -التعزير للتهمة القوية - تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33381189:‬تاريخه‪1433/07/15:‬هـ‬\n                         ‫رقم الدعوى‪33468056:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3419394‬تاريخه‪1434/01/21:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصد الترويــج وتعاطيها‬\n      ‫والشــروع يف ترويجهــا‪ -‬إقــرار‪ -‬حــد املســكر‪ -‬التعزيــر للتهمــة القويــة ‪-‬‬\n                                                         ‫تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫املــواد (‪ )38‬و(‪ )53‬و(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                               ‫العقليــة‪.‬‬\n\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهمــا تتضمــن طلــب إثبــات إدانــة‬\n      ‫األول بحيــازة احلشــيش وحبــوب اإلمفيتامــن بقصــد الترويــج والتعاطــي‬\n      ‫والشــروع يف ترويــج احلبــوب وبيعهــا وتعاطيــه لهمــا ســابقا وإدانــة الثانــي‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي ‪ ،‬واحلكــم عليهمــا بعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر وعلــى األول أيض ـ ًا بالغرامــة واملصــادرة‬\n      ‫طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت االتفــاق مــع‬\n      ‫األول علــى شــراء حبــوب محظــورة وبعــد أن تقابــل مــع املشــتري وقبــل‬\n      ‫تســليمه الكميــة الحــظ الفرقــة فرمــى احلبــوب وهــرب لداخــل املنــزل‬\n      ‫فتــم اللحــاق بــه وعثــر معــه علــى اجلــوال الــذي مت التنســيق معــه مــن‬\n      ‫خاللــه ومبلــغ مالــي‪ ،‬وعثــر بغرفــة النــوم علــى كميــة أخــرى مــن احلبــوب‬\n\n‫‪123‬‬\n\f‫احملظــورة وقطعــة مــن احلشــيش ومبلــغ مالــي؛ وعنــد النــزول مــن املنــزل‬\n‫لوحــظ الثانــي يقــف عنــد بــاب غرفــة احلــارس وعنــد مشــاهدته للفرقــة‬\n‫هــرب لداخلهــا فتــم القبــض عليــه وعثــر يف املرحــاض علــى قطعــة مــن‬\n‫احلشــيش‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n‫لإلمفيتامــن واحلشــيش املخــدر‪ ،‬أقــر األول أمــام احملكمــة بجميــع مــا‬\n‫أســنده إليــه املدعــي العــام وأنكــر الثانــي جميــع التهــم املوجهــة لــه‪،‬‬\n‫للمدعــى عليــه الثانــي ســابقة مخــدرات‪ ،‬قضــت احملكمــة بإدانــة األول‬\n‫بجميــع مــا نســب إليــه وقــررت ســجنه ملــدة ثمــان ســنوات وجلــده خمســن‬\n‫جلــدة مكــررة علــى عشــرين مــرة وتغرميــه مبلغ خمســة آالف ريــال ومنعه‬\n‫مــن الســفر خــارج اململكــة ملــدة ثمــان ســنوات ومصــادرة املضبوطــات‬\n‫وجلــده ثمانــن جلــدة علنــا حــد املســكر كمــا قضــت بصــرف النظــر‬\n‫عــن طلــب املدعــي العــام احلكــم علــى الثانــي مبوجــب نظــام املخــدرات‬\n‫وقــررت ســجنه ملــدة ثالثــة أشــهر وجلــده خمســن جلــدة مكــررة علــى‬\n‫خمــس مــرات لقــاء شــبهة احليــازة‪ ،‬قنــع املدعــى عليهمــا باحلكم وعارض‬\n‫املدعــي العــام عليــه‪ -‬قــررت محكمــة االســتئناف املوافــق علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33468056‬‬\n‫وتاريــخ ‪1433/07/15‬ه ـ املقيــدة باحملكمة برقــم ‪ 331320550‬وتاريخ‬\n‫‪1433/07/14‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/08/07‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 :45‬وفيهــا حضــر املدعــي العــام ‪ ........‬ســعودي‬\n\n                                                                                   ‫‪124‬‬\n\f      ‫اجلنســية حامــل بطاقــة أحــوال رقــم (‪ )........‬واملكلــف بالعمــل لدينــا‬\n      ‫مبوجــب خطــاب ذو الرقــم (ه ـ م‪ )368/6/2‬وتاريــخ ‪1430/21/29‬ه ـ‬\n      ‫وقــرر دعــواه قائــا بصفتــي مدعيــا عامــا بدائــرة االدعاء العــام مبحافظة‬\n      ‫جــدة ادعــى علــى كل مــن ‪ )28( ........ )1‬عام ـاً‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )....‬املهنــة‪ /‬متســبب ‪ ،‬موقــوف بســجون‬\n      ‫محافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم (ه ـ م‪ )33045/5/2‬يف‬\n      ‫‪1432/5/16‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬ه ـ ‪ )32( ........ )2‬عامـاً‪ ،‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ، )...‬املهنــة‪ /‬متســبب ‪ ،‬موقــوف بســجون محافظــة جــدة‬\n      ‫مبوجب أمر متديد التوقيف رقم (هـ م‪ )33046/5/2‬يف ‪1432/5/16‬هـ‬\n      ‫اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس‬\n      ‫مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )4/5/1/79425‬وتاريــخ‬\n      ‫ـاء علــى اإلخباريــة‬‫‪1432/12/20‬ه ـ فإنــه بتاريــخ ‪1433/5/14‬ه ـ بنـ ً‬\n      ‫الــواردة ملكافحــة املخــدرات بجــدة عــن ترويــج األول للحبــوب احملظــورة‬\n      ‫عليــه مت االتصــال علــى جوالــه رقــم (‪ )...‬واالتفــاق معــه علــى شــراء كمية‬\n      ‫مــن احلبــوب احملظــورة ‪،‬وباالنتقــال ملنزلــه خــرج األول وتقابل مــع املتعاون‬\n      ‫والفــرد وقبــل تســليم الكميــة الحــظ الفرقــة فرمــى الكميــة وهــي‬\n      ‫(‪ )396‬ثالثمائــة وســتة وتســعون حبــة بيضــاء اللــون‪ ،‬وهــرب لداخــل‬\n      ‫املنــزل فتــم اللحــاق بــه والقبــض عليــه وعثــر معــه علــى جــوال يحمــل‬\n      ‫الرقــم املنــوه عنــه ومبلــغ (‪ )91‬واحــد وتســعني ريــا ًال ‪ ،‬وعثــر بغرفــة النــوم‬\n      ‫علــى أكيــاس بهــا (‪ )644‬ســتمائة وأربعــة وأربعــن حبــة بيضــاء اللــون‬\n      ‫وقطعــة ســوداء اللــون تــزن (‪ )130‬مائــة وثالثــن جرام ـ ًا وعثــر علــى‬\n      ‫بندقيــة (شــوزن) مــع ذخيــرة حيــة ومبلــغ (‪ )26700‬ســتة وعشــرين ألــف‬\n\n\n‫‪125‬‬\n\f‫وســبعمائة ريــال ؛ وعنــد النــزول مــن املنــزل لوحــظ الثانــي يقــف عنــد بــاب‬\n‫غرفــة احلــارس وعنــد مشــاهدته للفرقــة هــرب لداخلهــا فتــم القبــض‬\n‫عليــه واتضــح انبعــاث رائحــة احلشــيش املخــدر منهــا وعثــر يف املرحــاض‬\n‫علــى قطعــة ســوداء اللــون تــزن (‪ )19.5‬تســعة عشــر جرم ًا ونصــف اجلرام‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/1800‬ك ش م) لعــام‬\n‫‪1433‬ه ـ احتــواء عينتــي احلبــوب املضبوطــة علــى مــادة اإلمفيتامــن‬\n‫املؤثــرة عقلي ـ ًا وايجابيــة عينتــي القطعتــن املضبوطــة ملــادة احلشــيش‬\n‫املخــدر واملدرجــة بجــداول املخــدرات رقــم (‪ )2 ، 1‬الفئتــن (أ ‪ ،‬ب)‬\n‫امللحقــن بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وباســتجواب‬\n‫املدعــى عليــه األول اعتــرف أنــه اتصــل بــه شــخص يعرفــه وطلــب منــه‬\n‫شــدين مــن احلبــوب احملظــورة مببلــغ (‪ )3200‬ثالثــة آالف ومائتــي ريــال‬\n‫للشــد الواحــد وعنــد مقابلتــه شــاهد الفرقــة فهــرب ورمــى احلبــوب فتــم‬\n‫القبــض عليــه ‪ ،‬وأقــر بحيــازة احلبــوب احملظــورة للترويــج واحلشــيش‬\n‫املخــدر للتعاطــي التــي ضبطــت باملنــزل ‪ ،‬وأنــه يبيــع احلبــوب احملظــورة‬\n‫ويتعاطاهــا مــن الســابق وأنــه تعاطــى مــن احلشــيش املخــدر املضبــوط‬\n‫ولنوعــه ســابق ًا ‪ ،‬وأن جــزء مــن املبلــغ املضبــوط حصــل عليــه مــن بيــع‬\n‫احلبــوب احملظــورة ؛ كمــا أقــر بحيــازة كميــة احلشــيش املخــدر التــي‬\n‫ضبطــت يف غرفــة احلــارس بقصــد التعاطــي‪ .‬وباســتجواب املدعــى عليــه‬\n‫الثانــي أقــر بضبــط احلشــيش املخــدر مبرحــاض الغرفــة التــي كان بهــا‬\n‫وأنــه عائــد لــأول‪( .‬مت فــرز أوراق بشــأن الســاح والذخائــر احليــة التــي‬\n‫مت ضبطهــا لبعثهــا إلــى جهــة االختصــاص)‪ .‬وقــد انتهــى التحقيــق إلــى‬\n‫اتهــام األول بحيــازة (‪ )1040‬ألــف وأربعــن حبــة حتتــوي علــى مــادة‬\n‫اإلمفيتامــن املؤثــرة عقلي ـ ًا بقصــد الترويــج والشــروع يف ترويــج (‪)396‬‬\n\n\n                                                                                      ‫‪126‬‬\n\f      ‫ثالثمائــة وســتة وتســعني حبــة منهــا وبيعــه وتعاطيــه لنوعيهمــا ســابق ًا‬\n      ‫وحيــازة (‪ )130‬مائــة وثالثــن جرام ـ ًا مــن مــادة احلشــيش املخــدر بقصــد‬\n      ‫الترويــج والتعاطــي وتعاطيــه منهــا ولنوعهــا ســابق ًا ؛ واتهــام األول والثانــي‬\n      ‫بحيازتهما (‪ )19.5‬تســعة عشــر جرام ًا ونصف اجلرام من مادة احلشــيش‬\n      ‫املخــدر بقصــد التعاطــي ‪،‬لألدلــة والقرائــن املذكــورة بالئحــة الدعــوى‬\n      ‫وباالطــاع علــى صحيفــة احلالــة اجلنائيــة لــم يعثــر علــى ســوابق لــأول‬\n      ‫وعثــر للثانــي علــى ســابقة حيــازة املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا مــن األفعــال‬\n      ‫احملرمــة شــرع ًا واملجرمــة نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ واملعاقــب عليهــا اســتناد ًا للمــواد (‪-38‬‬\n      ‫‪ )59-41‬مــع مراعــاة مــا ورد باملــادة (‪ )62‬مــن ذات النظــام ‪ ،‬أطلــب‪/‬‬\n      ‫إثبات ما أســند إليهما واحلكم عليهما بالعقوبات األصلية والتكميلية‬\n      ‫التاليــة‪ )1 :‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إلــى األول مــع‬\n      ‫تشــديد العقوبــة عليــه اســتنادا للفقــرة (‪ )1‬والفقــرة (‪ )2‬احلالــة (ج) مــن‬\n      ‫املــادة (‪ )38‬مــن النظــام املشــار إليــه بالســجن لقــاء مــا أســند إلــى الثانــي‬\n      ‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n      ‫املشــار إليــه مصــادرة جهــاز اجلــوال العائــد لــأول مــن نــوع (‪ )........‬ذي‬\n      ‫الرقــم املصنعــي (‪ )........‬املســتخدم يف ارتــكاب اجلرميــة واملبلــغ املالــي‬\n      ‫املضبــوط معــه وقــدره (‪ )26791‬ســتة وعشــرون ألفـ ًا وســبعمائة وواحــد‬\n      ‫وتســعون ريــا ًال لترجــح حصولــه عليــه مــن بيــع احلبــوب احملظــورة اســتناد ًا‬\n      ‫للفقرتــن (‪ )2-1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة مــع إلغــاء اخلدمــة عــن شــريحة اجلــوال وعــدم صرفهــا‬\n\n\n‫‪127‬‬\n\f‫اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫(‪ )9798‬يف ‪1428/2/10-9‬هــ‪ .‬منعهمــا مــن الســفر خلــارج البــاد بعــد‬\n‫انتهــاء تنفيــذ عقوبتيهمــا وفق ـ ًا للفقــرة (‪ )1‬مــن النظــام املشــار اليــه‬\n‫هكــذا أدعــى وجــرى إحضــار املدعــى عليهمــا وبســؤال املدعــى عليــه‬\n‫ا كل مــا ذكــره املدعــي العــام‬      ‫األول ‪ ...... /‬عــن الدعــوى أجــاب قائ ـ ً‬\n‫ا فقــد قبــض علــى بعــد التنســيق معــي جوالــي نــوع‬    ‫صحيــح جملــة وتفصيـ ً‬\n‫‪ ........‬ذي الرقــم (‪ )...‬علــى قيامــي ببيــع احلبــوب احملظــورة وقبــل متــام‬\n‫عمليــة االســتالم والتســليم قبــض علــي وكل مــا ورد يف الدعــوى مــن‬\n‫احلشــيش املخــدر واحلبــوب احملتويــة علــى اإلمفيتامــن فهــي صحيحــة‬\n‫طبقـ ًا ملــا قــرره املدعــي العــام وتعــود لــي لوحــدي وليــس ألخــي عالقــة بهــا‬\n‫البتــة وكان بحوزتــي مبلــغ مالــي قــدره (‪ )26791‬ســتة وعشــرون ألــف‬\n‫وســبعمائة وواحــد وتســعون ريــا ًال عائــد لــي حتصلــت عليــه مــن بيــع‬\n‫املخــدرات ومــا ذكــره املدعــي العــام مــن أننــي تعاطيــت لنوعــه ســابقا‬\n‫فذلــك صحيــح أيضــا وبحمــد اهلل ال توجــد علـ ّـي أيــة ســوابق مســجلة وقــد‬\n‫أقدمــت علــى ذلــك وأنــا مســلم وأعلــم بــان ذلــك محــرم شــرع ًا ومجــرم‬\n‫نظام ـ ًا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى هــذا الفعــل وأتعهــد‬\n‫بعــدم العــودة لفعلــي هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي‪........‬‬\n‫ا كل مــا ذكــره املدعــي العــام ضــدي فغيــر‬        ‫عــن الدعــوى أجــاب قائ ـ ً‬\n‫ا فقــد قبــض علــى ولــم يكــن بحوزتــي شــيء مــن‬       ‫صحيــح جملــة وتفصيـ ً‬\n‫احملظــورات البتــة وكنــت متواجــد ًا مبنــزل والــدي محــل واقعــة القبــض‬\n‫ولــم اعلــم عــن وجــود هــذه احملظــورات البتــة وأنــا اســكن لوحــدي مــع‬\n‫زوجتــي هكــذا أجــاب وبســؤالي للمدعــي العــام عــن بينتــه علــى الدعــوى‬\n‫ا ليــس لــدي ســوى مــا يف املعاملــة واطلــب الرجــوع لهــا‬      ‫وأجــاب قائ ـ ً‬\n\n\n                                                                                         ‫‪128‬‬\n\f      ‫هكــذا أجــاب هــذا وقــد اطلعــت علــى أقــوال املدعــى عليــه الثانــي لفــة‬\n      ‫رقــم (‪ )23‬ومحــل الشــاهد مــا نصــه (س‪ /‬أنــت متهــم باالشــتراك يف‬\n      ‫الشــروع يف البيــع (‪ )396‬حبــة محظــورة وحيــازة (‪ )644‬حبــة مــن نوعهــا‬\n      ‫و(‪ )130‬جــرام مــن احلشــيش املخــدر وســاح شــون نــاري و(‪ )14‬طلقــة‬\n      ‫حيــة وحيــازة (‪ )5،19‬جــرام مــن احلشــيش املخــدر فمــا قولــك ؟ ج‪ /‬غيــر‬\n      ‫صحيــح) أ‪.‬ه ـ كمــا جــرى اطالعــي علــى التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪1800‬ك ش م ) املرفــق باملعاملــة لفــة رقــم ( ‪ )32‬ويتضمــن إيجابيــة‬\n      ‫احتــواء العينــة (ج‪،‬د) للحشــيش املخــدر والعينــة (أ‪،‬ب) لإلمفيتامــن‬\n      ‫املؤثــر عقليـ ًا كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليهما‬\n      ‫املرفقــة باملعاملــة باللفــة رقــم (‪ )34‬املتضمنــة عــدم وجــود أيــة ســوابق‬\n      ‫مســجلة علــى املدعــى عليــه األول ووجــود ســابقة واحــدة يف حيــازة‬\n      ‫املخــدرات علــى الثانــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا‬\n      ‫قــرره الطرفــان وملــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه‬\n      ‫بعاليــة فلمــا ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه األول ‪ /‬املذكــور‬\n      ‫بعاليــه مبــا نســب إليــه مــن حيازتــه (‪ )1040‬ألــف وأربعــن حبــة حتتــوي‬\n      ‫علــى اإلمفيتامــن املؤثــر عقلي ـ ًا بقصــد الترويــج والشــروع يف ترويــج‬\n      ‫(‪ )396‬ثالثمائــة وســتة وتســعني حبــة منهــا وبيعــه وتعاطيــه لهمــا ســابق ًا‬\n      ‫وحيازتــه (‪ )130‬مائــة وثالثــون جرام ـ ًا مــن احلشــيش املخــدر لقصــد‬\n      ‫الترويــج والتعاطــي وتعاطيــه منهــا لنوعهــا ســابق ًا وحيازتــه (‪)19،5‬‬\n      ‫لتســعة عشــر جرام ـ ًا ونصــف اجلــرام مــن احلشــيش املخــدر لقصــد‬\n      ‫التعاطــي وثبــت لــدي حتصــل املدعــى عليــه األول للمبلــغ املالــي الــذي‬\n      ‫بحوزتــه وقــدره (‪ )26791‬ريــال مــن الترويــج وقيامــه بترويــج املخــدرات‬\n      ‫ســابق ًا ولــم يثبــت لــدي ادانــة املدعــى عليــه الثانــي‪ /‬مبــا نســب إليــه مــن‬\n\n\n‫‪129‬‬\n\f‫االشــتراك يف حيازتــه (‪ )19,5‬لتســعة عشــر جرام ـ ًا ونصــف اجلــرام مــن‬\n‫احلشــيش املخــدر لقصــد التعاطــي مــع توجيــه الشــبهة إليــه يف ذلــك وعليه‬\n‫فقــد قــررت صــرف النظــر عــن طلــب املدعــي العــام احلكــم علــى املدعــى‬\n‫عليــه الثانــي‪ /‬مبوجــب نظــام مكافحــة املخــدرات ونظــر لكبــر‬\n‫الكميــة وتنوعهــا ولعظيــم جــرم مــا قــام بــه املدعــى عليــه األول وملــا يف‬\n‫ترويجهــا مــن اإلفســاد يف األرض ونشــر لــه أوســاط املجتمــع ونظــر ًا ملــا‬\n‫أظهــره مــن التوبــة والنــدم ولعــدم الســوابق املســجلة عليــه وملــا قــرره‬\n‫الفقهــاء مــن أن للحاكــم املعاقبــة علــى الشــبهة ولتوجــه الشــبهة إلــى‬\n‫املدعــى عليــه الثانــي ‪ /‬نظــرا لوجــود الســابقة عليــه ووجــوده يف محــل‬\n‫الواقعــة عنــد القبــض فلمــا ســبق فقــد حكمــت علــى املدعــى عليهمــا‬\n‫مبــا يلــي‪ :‬أوالً‪ :‬يســجن املدعــى عليــه األول‪ /‬ملــدة ثمــان ســنوات يحتســب‬\n‫موقوفــا يف هــذه القضيــة ويجلد خمســن جلــدة مكررة‬       ‫ً‬       ‫منهــا مــا أمضــاه‬\n‫عليــه عشــرين مــرة بينهــن مــدة ال تقــل عــن خمســة أيــام ويدفــع غرامــة‬\n‫ماليــة قدرهــا خمســة أالف ريــال وفقــا للمــادة (‪ )38‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ثانيـاً‪ :‬مينــع املدعــى عليه األول ‪ /‬من الســفر‬\n‫خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميتــه ملــدة ثمــان ســنوات وفقــا‬\n‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه‪ .‬ثالثـاً‪ :‬مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه األول‪/‬‬\n‫‪ ........‬وشــريحته املســتخدمني يف عمليــة الترويــج وعــدم صرف الشــريحة‬\n‫لــه مــرة أخــرى لســوء اســتخدامه لهــا ومصــادرة املبلــغ املالــي الــذي‬\n‫بحوزتــه لتحصلــه عليــه مــن الترويــج للمخــدرات وقــدره (‪ )26791‬ســتة‬\n‫وعشــرون الفـ ًا وســبعمائة وواحــد وتســعون ريــا ًال وفقـ ًا للمــادة (‪ )53‬مــن‬\n‫نظــام مكافحــة املخــدرات املشــار إليــه ووفق ـ ًا لتعميــم ســمو وزيــر‬\n\n\n                                                                                         ‫‪130‬‬\n\f      ‫الداخليــة ذي الرقــم (‪ )9798‬وتاريــخ ‪1428/10-9‬ه ـ رابعـاً‪ :‬إقامــة حــد‬\n      ‫املســكر علــى املدعــى عليــه األول‪ .......... /‬وذلــك بجلــده ثمانــن جلــدة‬\n      ‫دفعــة واحــدة أمــام مــأ مــن النــاس لقــاء تعاطيــه احلشــيش املخــدر مــن‬\n      ‫الســابق خامس ـاً‪ /‬يســجن املدعــى عليــه الثانــي‪ /‬ملــدة ثــاث أشــهر‬\n      ‫يحتســب مــا أمضــاه موقوف ـ ًا يف هــذه القضيــة ويجلــد خمســن جلــدة‬\n      ‫مكــررة عليــه خمــس مــرات بينهــن مــدة ال تقــل عــن خمســة أيــام لقــاء‬\n      ‫شــبهة احليــازة وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n      ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n      ‫باحلضــور يف يــوم األحــد املوافق‪1433/8/11‬ه ـ الســتالم نســخة مــن‬\n      ‫قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يومــا اعتبــار ًا‬\n      ‫مــن التاريــخ املشــار إليــه فــان مضــت املــدة ولــم يقــدم اعتراضــه عليــه‬\n      ‫خاللهــا فــان حقــه يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا كمــا‬\n      ‫قــرر املدعــى عليــه قناعتــه بــه وجــرى النطــق باحلكــم يف يــوم األربعــاء‬\n      ‫املوافــق ‪1433/7 /30‬ه ـ الســاعة ‪ 9:30‬وعلــى ذلــك جــرى التوقيــع وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬ويف يــوم األحــد‬\n      ‫ـاء علــى انتهــاء مــدة‬\n                            ‫‪1433/10/15‬ه ـ الســاعة ‪ 08 :45‬فتحــت اجللســة بنـ ً‬\n      ‫االعتــراض علــى احلكــم حيــث جــرى إفهــام املدعــي العــام باســتالمه‬\n      ‫نســخة احلكــم بتاريــخ ‪1433/8/11‬ه ـ وأنــه ســوف حتتســب مهلــة‬\n      ‫الثالثــن يوم ـ ًا لالعتــراض اعتبــار ًا مــن تاريخــه وحيــث انتهــت املــدة‬\n      ‫املقــررة نظام ـ ًا ولــم يتقــدم املدعــي العــام باالســتالم ولــم يتقــدم بالئحــة‬\n      ‫اعتراضيــة لــذا فقــد قــررت رفــع احلكــم حملكمــة االســتئناف حســب‬\n      ‫املتبــع وحتــى ال يخفــى جــرى إثباتــه واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                                                 ‫محمد ‪.‬‬\n\n\n‫‪131‬‬\n\f‫احلمد هلل وحده وبعد ففي يوم الثالثاء ‪1433/12/21‬هـ وعند الســاعة‬\n‫‪ 08 :00‬فتحــت اجللســة بنــاء علــى عــود املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة وبرفقهــا قــرار املالحظــة ذو الرقــم ‪33466484‬‬\n‫وتاريــخ ‪1433/11/27‬ه ـ الصــادر مــن أصحــاب الفضيلــة قضــاة الدائــر‬\n‫اجلزائيــة األولــى واملتضمــن بعــد املقدمــة مــا نصــه (وبدراســة القــرار‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫ملالحظــة أنــه عنــد عــرض احلكــم علــى الطرفــن ذكــر فضيلتــه أن‬\n‫املدعــي العــام قــرر عــدم القناعــة واملدعــى عليــه القناعــة فهــل الــذي قــرر‬\n‫القناعــة املدعــى عليهمــا االثنــان أم أحدهمــا وال بــد مــن إيضــاح ذلــك‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫قاضــي اســتئناف اخلتــم والتوقيــع قاضــي اســتئناف ‪ ........‬اخلتــم والتوقيــع‬\n‫رئيــس اســتئناف ‪ ........‬اخلتــم والتوقيــع أ‪ .‬ه ـ نصــه وملــا ذكــره أصحــاب‬\n‫الفضيلــة نفعنــي اهلل بعلمهــم فإننــي أجيبهــم أن الــذي قــرر القناعــة‬\n‫باحلكــم كال املدعــى عليهمــا األول والثانــي وقــد جــرى تعديــل ذلــك‬\n‫علــى القــرار وضبطــه يف هــذه اجللســة وقــررت إعــادة املعاملــة حملكمــة‬\n‫االســتئناف وكان ختام هذه اجللســة الســاعة ‪ 08 :20‬وصلى اهلل وســلم‬\n                                                              ‫علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن النبــي بعــده ‪ ،‬وبعــد ‪ - :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة إلينــا مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة املســاعد مبحافظــة جــدة برقــم‬\n‫‪ 2194960/33‬وتاريــخ ‪ 1434/1/13‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫رقــم ‪ 33381189‬و تاريــخ ‪ 1433/8/17‬ه ـ الصــادر مــن فضيلــة الشــيخ‬\n\n\n                                                                                       ‫‪132‬‬\n\f      ‫‪ .......‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى‬\n      ‫املدعــي العــام ضــد ‪ .....‬املتهــم بقضيــة مخــدرات احملكــوم فيــه مبــا دون‬\n      ‫باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪133‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":123,"source_page_end":133,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cbb8584d2e0392b62c113f9d188d2f165b3cdaef6da5ca6b835b9ff83681abe0","normalized_text_hash":"1648d63631aeceeac9e19076246997d44fd563813c8184327179eff0eaa8f13b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p123-33381189"},{"id":"d02f9681-52e8-5d23-93f7-5c7cc9d9493c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قات بقصد الترويج والتعاطي -قات -حيازة حبوب اإلمفيتامن بقصد التعاطي -التستر على مصدر ما ضبط -إعداد املدعى عليه منزله لتعاطي القات -األصل أن ما كان يف بيت املرء من حوزته -مشروعية التعزير بالتهمة -التعزير بالسجن واجللد والغرامة واإلبعاد -تشديد العقوبة .","document_number":"3412610","case_number":"33475424","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/14","year":"1434","subject":"مخدرات -حيازة قات بقصد الترويج والتعاطي -قات -حيازة حبوب اإلمفيتامن بقصد التعاطي -التستر على مصدر ما ضبط -إعداد املدعى عليه منزله لتعاطي القات -األصل أن ما كان يف بيت املرء من حوزته -مشروعية التعزير بالتهمة -التعزير بالسجن واجللد والغرامة واإلبعاد -تشديد العقوبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3412610 :‬تاريخه‪1434/1/14 :‬هـ‬\n                   ‫رقم الدعوى‪33475424:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34315075‬تاريخه‪1434/09/08:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة قــات بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬حيــازة‬\n‫حبــوب اإلمفيتامــن بقصــد التعاطــي‪ -‬التســتر علــى مصــدر مــا ضبــط‬\n‫‪ -‬إعــداد املدعــى عليــه منزلــه لتعاطــي القــات ‪ -‬األصــل أن مــا كان‬\n‫يف بيــت املــرء مــن حوزتــه ‪ -‬مشــروعية التعزيــر بالتهمــة ‪ -‬التعزيــر‬\n           ‫بالســجن واجللــد والغرامــة واإلبعــاد ‪ -‬تشــديد العقوبــة ‪.‬‬\n\n\n\n‫‪ -1‬مشــروعية التعزيــر بالتهمــة ملــا رواه أبــو داود والترمــذي أن النبــي‬\n                        ‫ا يف تهمــة ‪.‬‬‫صلــى اهلل عليــه وســلم حبــس رج ـ ً‬\n                      ‫‪ -2‬القرار الوزاري رقم (‪ )2057‬يف ‪1404/5/26‬هـ ‪.‬‬\n                      ‫‪ -3‬القرار الوزاري رقم(‪ )3818‬يف ‪ 1410/9/28‬هـ ‪.‬‬\n             ‫‪ -4‬برقية وزير الداخلية رقم (‪ )13476‬يف ‪ 1433/2/23‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا رجــل ســعودي وامــرأة أجنبيــة‬\n‫‪،‬باتهــام األول بتســليم قــات بقصــد الترويــج واالجتــار وإعــداد منزلــه‬\n‫مكانـ ًا للتعاطــي وتســتره علــى مصــدر مــا ضبــط واتهــام املــرأة بحيــازة‬\n‫حبــوب اإلمفيتامــن بقصــد التعاطــي‪ ،‬وطلــب إثبــات مــا أســند إليهمــا‬\n‫وتعزيــر املدعــى عليهــا ‪ ،‬وفــق األنظمــة املعمــول بها‪،‬وتعزيرهمــا لقــاء‬\n\n                                                                                 ‫‪134‬‬\n\f      ‫التســتر ولقــاء إعــداد الثانــي منزلــه للتعاطــي ‪،‬ورد املبلــغ املرقــم‪ ،‬وإبعــاد‬\n      ‫املــرأة األجنبيــة بعــد انتهــاء تنفيــذ عقوبــة ســجنها ‪،‬حيــث مت القبــض‬\n      ‫عليهمــا مــن قبــل فرقــة مكافحــة املخدرات بعــد ورود بالغ بقيام املدعى‬\n      ‫عليهمــا بترويــج القــات‪ ،‬وأن صاحــب املنــزل جعلــه وكــرا الســتقبال‬\n      ‫املتعاطــن لنبــات القــات فتــم تزويــد املصــدر باملبلــغ املرقــم برفقــة أحــد‬\n      ‫أفــراد املكافحــة وبعــد دخولهمــا املنــزل تفــاوض املصــدر مــع املدعــى‬\n      ‫عليهمــا علــى شــراء القــات بقيمــة مائــة وخمســن ريــال فاســتعدت‬\n      ‫املدعــى عليهــا بذلــك ثــم قــام املدعــى عليــه بتســليم القــات وعنــد مداهمــة‬\n      ‫املنــزل مــن قبــل الفرقــة الذ بالفــرار مجموعــة مــن الرجــال والنســاء ومت‬\n      ‫القبــض علــى املدعــى عليهمــا وبتفتيــش املــرأة عثــر بشــنطتها علــى حبوب‬\n      ‫محظــورة ولــم يتــم العثــور علــى املــرأة التــي اســتلمت املبلــغ وأثبــت التقريــر‬\n      ‫الكيميائــي إيجابيــة العينتــن املضبوطتــن لنبــات القــات احملظــور‬\n      ‫وحبــوب اإلمفيتامــن احملظــورة‪ ،‬وصــادق املدعــى عليــه علــى القبــض‬\n      ‫عليــه يف منزلــه وهــو يتعاطــى القــات وأنكــر حيــازة القــات للترويــج‬\n      ‫‪،‬صادقــت املدعــى عليهــا علــى القبــض عليهــا وهــي يف منــزل املدعــى‬\n      ‫عليــه وحيازتهــا للحبــوب وأنكــرت أنهــا حبــوب اإلمفيتامــن‪ ،‬بينــة‬\n      ‫املدعــي العــام بخصــوص تســليم القــات هــي شــهادة أحــد أعضــاء الفرقــة‬\n      ‫القابضــة مبشــاهدة التســليم دون اآلخــر‪ ،‬ومبــا أن األصــل مــا كان يف‬\n      ‫بيــت املــرء مــن حوزتــه‪ ،‬مت إثبــات إدانــة املدعــى عليــه بتعاطــي القــات‬\n      ‫وحيازتــه بقصــد التعاطــي والترويــج وجعــل منزلــه وكــر ًا لشــراء القــات‬\n      ‫وتعاطيــه وعــدم ثبــوت إدانتــه بتســليم القــات ‪،‬وتوجــه الشــبهة لتســليمه‬\n      ‫بشــهادة أحــد الشــهود‪ ،‬وعــدم إثبــات إدانــة املدعــى عليهــا بحيــازة حبــوب‬\n      ‫اإلمفيتامــن ‪،‬وتوجــه الشــبهة بإقرارهــا بحيــازة حبــوب أخرى‪،‬حكمــت‬\n\n\n‫‪135‬‬\n\f‫احملكمــة بتعزيــر املدعــى عليــه بالســجن ثالثــن شــهر ًا وجلــده ثالثمائــة‬\n‫وخمســن جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة أمــام‬\n‫النــاس‪ ،‬تغرميــه ألــف ريــال ‪ ،‬وتعزيــر املدعــى عليهــا بالســجن خمســة‬\n‫أشــهر وإبعادهــا عــن البــاد بعــد تنفيــذ احلكــم وصــرف النظــر عــن‬\n‫املطالبــة بــرد املبلــغ والتعزيــر للتســتر لعــدم وجــود موجبــه‪ ،‬وقنــع املدعــى‬\n‫عليهمــا واعتــرض املدعــي العــام بــدون الئحــة‪ ،‬ومت تصديــق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n‫‪ ....‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫بالرياض برقم ‪ 33475424‬وتاريخ ‪1433/07/20‬هـ املقيدة باحملكمة‬\n‫برقــم ‪ 331360332‬وتاريــخ ‪1433/07/20‬ه ـ ففــي يــوم االثنــن املوافــق‬\n‫‪1433/07/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 15‬وفيهــا قــدم املدعــي‬\n‫العام ‪ .....‬دعواه ضد ‪........ /1‬اجلنس‪ :‬أنثى اجلنســية‪ :‬الصومالية الديانة‪:‬‬\n‫مسلمة نــوع الهويــة‪ :‬بطاقــة بديلــة جهــة اإلصــدار‪ :‬الســجن‪ ،‬مــكان‬\n‫اإلقامــة‪ :‬الريــاض تاريــخ القبــض‪1433/6/11 :‬ه ـ حالــة املتهــم‪ :‬موقــوف‬\n‫تاريــخ القبــض‪1433/6/11 :‬ه ـ االتهــام‪ :‬حيــازة مؤثــرات عقليــة بقصــد‬\n‫التعاطــي أو االســتعمال الشــخصي ‪........../2‬اجلنــس‪ :‬ذكــر اجلنســية‪:‬‬\n‫ســعودي الســجل املدنــي رقــم الهويــة‪ ........ :‬احلالــة االجتماعيــة‪ :‬متــزوج‬\n‫مــكان اإلقامــة‪ :‬الريــاض جهــة اإليقــاف‪ :‬شــعبة ســجن امللــز بتاريــخ‬\n‫‪1433/6/11‬ه ـ قبــض علــى املتهمــن املذكوريــن مــن قبــل إحــدى فــرق‬\n‫شــعبة املكافحــة والبحــث والتحــري بعــد ورود إخباريــة عــن وجــود منزل‬\n\n                                                                                         ‫‪136‬‬\n\f      ‫يف حــي ‪ ....‬يتواجــد بــه رجــل وامــرأة ميتهنــان ترويــج القــات احملظــور وان‬\n      ‫صاحــب املنــزل جعلــه وكــر ًا الســتقبال مجموعــة مــن الرجــال والنســاء‬\n      ‫لتعاطــي القــات احملظــور عليــه مت اتخــاذ اإلجــراءات الالزمــة حيــث مت‬\n      ‫تزويــد املصــدر باملبلــغ املرقــم وقــدره (‪ )150‬مائة وخمســون ريا ًال وكلف‬\n      ‫احــد عناصــر الفرقــة ملرافقــة املصــدر ليكــون شــاهد ًا علــى عمليــة‬\n      ‫الترويــج بعدهــا توجــه املصــدر بعــد تفتيشــه بــكل دقــة ويرافقــه عنصــر‬\n      ‫املكافحــة املكلــف إلــى املنــزل وبعــد دخولهمــا تفــاوض املصــدر مــع‬\n      ‫املتهــم الثانــي واملــرأة محــل اإلخباريــة بحضــور عنصــر املكافحــة علــى‬\n      ‫شــراء حزمــة مــن القــات احملظــور بقيمــة (‪ )150‬ريــا ًال فاســتعدت املــرأة‬\n      ‫بذلــك بعدهــا قــام املتهــم الثانــي بتســليم املصــدر حزمــة يشــتبه أن تكون‬\n      ‫مــن نبــات القــات احملظــور بلــغ وزنهــا (‪ )110‬مائــة وعشــرة جرامــات وقــام‬\n      ‫املصــدر بتســليم املبلــغ املرقــم للمــرأة بعدهــا خــرج املصــدر وعنصــر‬\n      ‫املكافحــة وقــام عنصــر املكافحــة باالتصــال علــى قائــد الفرقــة وابلغــه‬\n      ‫بوجــود مجموعــة كبيــرة مــن الرجــال والنســاء داخــل املنــزل عندهــا مت‬\n      ‫االســتعانة بالدوريــات األمنيــة واصطحــاب املفتشــة النســائية وبعــد أخــذ‬\n      ‫األذن متــت مداهمــة املنــزل واثنــاء املداهمــة متكــن مجموعــة مــن الرجــال‬\n      ‫والنســاء مــن ارتــكاب الفــرار وذلــك عــن طريــق مخــارج مخصصــة لذلك‬\n      ‫وكذلــك عــن طريــق األســطح واجلــدران ومت القبــض علــى املتهــم الثانــي‬\n      ‫(محــل اإلخباريــة) ويف هــذه األثنــاء حــدث جتمهــر كبيــر جــد ًا خــارج‬\n      ‫املنــزل حيــث قامــوا بإطــاق صرخــات ورشــق رجــال األمــن باحلجــارة ممــا‬\n      ‫اســتدعاء إطــاق النــار طلقــات حتذيريــة يف الهــواء وبعــد الســيطرة علــى‬\n      ‫الوضــع مت القبــض علــى املتهمــة األولــى داخــل املنــزل وبتفتيــش حقيبتهــا‬\n      ‫عثــر بداخلهــا علــى عــدد (‪ )7‬بيضــاء اللــون يشــتبه ان تكــون مــن احلبــوب‬\n\n\n‫‪137‬‬\n\f‫احملظــور وبالبحــث عــن املــرأة التــي قامــت باســتالم املبلــغ املرقــم لــم يعثــر‬\n‫عليهــا ممــا يــدل علــى أنهــا الذت بالفــرار أثنــاء عمليــة املداهمــة وبتفتيــش‬\n‫املنــزل عثــر يف الصالــة بــه علــى (‪ )29‬تســعة وعشــرون حزمــة يشــتبه‬\n‫أن تكــون مــن نبــات القــات احملظــور بلــغ وزنهــا جميع ـ ًا (‪ )6.090‬ســتة‬\n‫كيلــوات وتســعون جرام ـاً‪ ،‬ولــم يعثــر علــى املبلــغ املرقــم ‪ -‬اإلجــراءات‬\n‫املتخــذة ‪ -1‬جــرى مخاطبــة مكافحــة املخــدرات بشــرق الريــاض إلحالــة‬\n‫مــا يتعلــق بإقامــة املتهمــة األولــى يف البــاد بطريقــة غيــر نظاميــة للجهــة‬\n        ‫املختصــة مبوجــب خطــاب الدائــرة رقــم ‪ .....‬بتاريــخ ‪1433/7/1‬هــ‪.‬‬\n‫‪ -2‬جــرى مخاطبــة الفرقــة القابضــة لإلفــادة عــن املتهمــة األولــى أن‬\n‫كان لهــا دور يف عمليــة الترويــج أو كميــة القــات املضبوطــة وحتديــد‬\n‫مــكان ضبطهــا مبوجــب خطــاب الدائــرة رقم‪.....‬بتاريــخ ‪1433/6/22‬هـ‬\n‫وخطــاب الدائــرة رقــم ‪1433/6/28.....‬ه ـ فوردنــا خطابهــم رقــم (‪).....‬‬\n‫بتاريــخ ‪1433/6/25‬ه ـ املتضمــن انــه لــم يتبــن للفرقــة أي دور للمتهمــة‬\n‫بعمليــة الترويــج أو كميــة القــات املضبــوط وانــه مت ضبطهــا مختبئــة‬\n                                    ‫حتــت الســرير بإحــدى غــرف النــوم باملنــزل ‪.‬‬\n‫‪-3‬وردت صحيفتــي ســوابق املتهمــن حيــث عثــر لألولــى علــى ســابقة‬\n                            ‫أعــداد وكــر للدعــارة مقرونــة بحيــازة املخــدرات‪.‬‬\n                                                                   ‫اإلجراءات املتخذة‪:‬‬\n‫‪ -1‬جــرى مخاطبــة مكافحــة املخــدرات بشــرق الريــاض إلحالــة مــا‬\n‫يتعلــق بإقامــة املتهمــة األولــى يف البــاد بطريقــة غيــر نظاميــة للجهــة‬\n    ‫املختصــة مبوجــب خطــاب الدائــرة رقــم ‪.....‬بتاريــخ ‪1433/7/1‬هــ‪.‬‬\n‫‪ -2‬جــرى مخاطبــة الفرقــة القابضــة لإلفــادة عــن املتهمــة األولى أن كان‬\n‫لهــا دور يف عمليــة الترويــج او كميــة القــات املضبوطــة وحتديــد مــكان‬\n\n\n                                                                                          ‫‪138‬‬\n\f      ‫ضبطهــا مبوجــب خطــاب الدائــرة رقــم‪ .....‬بتاريــخ ‪1433/6/22‬ه ـ‬\n      ‫وخطــاب الدائــرة رقــم ‪ .....‬بتاريــخ ‪ 1433/6/28‬ه ـ فوردنــا خطابهــم رقــم‬\n      ‫(‪ ).....‬بتاريــخ ‪1433/6/25‬ه ـ املتضمــن انــه لــم يتبــن للفرقــة أي دور‬\n      ‫للمتهمــة بعمليــة الترويــج أو كميــة القــات املضبــوط وانــه مت ضبطهــا‬\n                           ‫مختبئــة حتــت الســرير بإحــدى غــرف النــوم باملنــزل ‪.‬‬\n      ‫‪-3‬وردت صحيفتــي ســوابق املتهمــن حيــث عثــر لألولــى علــى ســابقة‬\n      ‫أعــداد وكــر للدعــارة مقرونــة بحيــازة املخــدرات‪ ،‬وعثــر للثانــي علــى‬\n      ‫ســبعة ســوابق اثنتــن منهــا ســرقة والثالثــة ســرقة كيابــل والرابعــة‬\n      ‫محاولــة ســكر واخلامســة شــرب املســكرات و اعتــداء و طعــن شــخص‬\n      ‫والسادســة ســرقة مســاكن والســابعة حيــازة قــات واســتعمال القــات‬\n      ‫ومخالفــة نظــام أمــن احلــدود وباســتجواب املتهــم الثانــي اقــر بتعاطيــه‬\n                                                      ‫القــات احملظــور مــن الســابق‪.‬‬\n      ‫وقــد اثبــت التقريــر الكيميائــي الشــرعي املرفق رقــم (‪ ).....‬لعام‪1433‬هـ‬\n      ‫إيجابيــة مســتخلص مــا مت ترويجــه ومــا مت ضبطــه للمــواد الفاعلــة يف‬\n      ‫نبــات القــات وهــو مــن املــواد املدرجــة باجلــدول (‪ )4‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة‪ ،‬واحتــواء احلبــوب املضبوطــة لإلمفيتامــن‬\n      ‫وهــو مــن املــواد املنبهــة املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وقــد أســفرت إجــراءات التحقيــق‬\n      ‫عــن توجيــه االتهــام للثانــي‪ ...../‬بتســليم مــا وزنــه (‪ )110‬مائــة وعشــرة‬\n      ‫جرامــات مــن نبــات القــات احملظــور بقصــد الترويــج واالجتــار وحيــازة‬\n      ‫مــا وزنــه (‪ )6.090‬ســتة كيلــوات وتســعون جرام ـ ًا مــن نبــات القــات‬\n      ‫احملظــور بقصــد الترويــج والتعاطــي وتعاطيــه للقــات احملظــور مــن‬\n\n\n‫‪139‬‬\n\f‫الســابق املعاقــب علــى ذلــك مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ واتهــام املتهمــة االولــى‪..... /‬بحيــازة (‪ )7‬ســبع حبــات مــن‬\n‫حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد التعاطــي املجــرم مبوجــب‬\n‫املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ واتهــام‬\n‫الثانــي بإعــداد منزلــه مكانـ ًا لتعاطــي القــات احملظــور وتســترهما علــى‬\n‫مصــدر مــا ضبــط املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن‬\n                                                                              ‫التالية ‪:‬‬\n‫ا علــى‬  ‫‪ -1‬مــا تضمنــه محضــر القبــض املنــوه عنــه املــدون تفصي ـ ً‬\n‫الصفحــات رقــم (‪ )11.12‬مــن ملــف إجــراءات االســتدالل املرفــق لفــة‬\n                                                                                  ‫(‪.)1‬‬\n                                     ‫‪ -2‬ما تضمنه خطاب الفرقة القابضة ‪.‬‬\n                                 ‫‪ -3‬ما تضمنه التقرير الكيميائي الشرعي‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكوريــن فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n          ‫ونظامـ ًا اطلــب إثبــات مــل اســند إليهمــا واحلكــم عليهمــا باالتــي ‪:‬‬\n‫‪-1‬بعقوبــة تعزيريــة بحــق املتهمــة األولــى وفق ـ ًا للفقــرة ( األولــى ) مــن‬\n‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا‬\n                                                                      ‫أســند إليهــا‪.‬‬\n    ‫‪-2‬بعقوبة تعزيرية بحق املتهم الثاني وفق ًا للقرار الوزاري املشار إليه‪.‬‬\n‫‪-3‬إلــزام املتهــم الثانــي بــرد املبلــغ املرقــم وقــدره (‪ )150‬مائــة وخمســون‬\n‫ري ــال اسـت ـن ــاد ًا لتـعـمـي ــم صـاح ــب الـسـمـ ــو الـملـك ــي النائــب الثانــي‬\n‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ‬\n                                                             ‫‪1428/10/23-22‬هـ‪.‬‬\n\n\n                                                                                          ‫‪140‬‬\n\f      ‫‪-4‬إبعــاد األولــى إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنها‬\n      ‫وعــدم الســماح لهــا بالعــودة إليهــا مــرة أخــرى وفقـ ًا للفقــرة (الثانيــة) مــن‬\n                ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫‪ -5‬بعقوبــة تعزيريــة بحــق الثانــي لقــاء إعــداد منزلــه مكان ـ ًا لتعاطــي‬\n          ‫القــات احملظــور وبحقهمــا لقــاء تســترهما علــى مصــدر مــا ضبــط‪.‬‬\n      ‫‪ -6‬تشــديد العقوبــة علــي املتهــم الثانــي لكثــرة ســوابقه اســتناد ًا لبرقيــة‬\n      ‫صاحــب الســمو امللكــي نائــب وزيــر الداخليــة رقــم (‪)93958/5/5/1‬‬\n                                                               ‫وتاريــخ ‪1429/8/23‬ه ـ ‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليهــا وهــي جتيــد اللغــة العربيــة أجابــت إن‬\n      ‫مــا ذكــره املدعــي العــام مــن القبــض علــي يف منــزل املدعــى عليه صحيح‬\n      ‫وســبب حضــوري ألجــل وضــع احلنــاء لنســاء يف املنــزل وكان معــي شــنطة‬\n      ‫صغيــرة فيهــا مبلــغ مالــي وحبــوب فيتامينــات ألننــي حامــل وليــس معــي‬\n      ‫إمفيتامــن وليــس لــي عالقــة بالقــات املوجــودة يف املنــزل والســابقة‬\n      ‫صحيحــة وأجــاب املدعــى عليــه قائــا إن مــا ذكــره املدعــي مــن القبــض‬\n      ‫علــي يف منزلــي صحيــح وكنــت أتعاطــى القــات املذكــور وعنــد دخــول‬\n      ‫الشــرطة هــرب الذيــن يف املنــزل ورمــوا بالقــات يف الصالــة وهــو الــذي‬\n      ‫مت ضبطــه وقــد اشــتروه مــن املدعــى عليهــا وزوج املدعــى عليــه أكبــر‬\n      ‫املروجــن للقــات وهــو ســجني يف ســجن ‪ ...‬وليــس لــي عالقــة بالقــات‬\n      ‫املوجــود يف الصالــة ولــم أســلم أحــدا قاتــا والســوابق التــي عليــه صحيحــة‬\n      ‫هكــذا أجــاب ولطلــب البينــة جــرى رفــع اجللســة وأجلــت ألقــرب موعــد‬\n      ‫وعليــه جــرى التوقيــع وأغلقــت اجللســة الســاعة ‪ 09 : 45‬وصلــى اهلل علــى‬\n             ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/07/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n‫‪141‬‬\n\f‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33475424‬وتاريــخ ‪1433/07/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331360332‬وتاريــخ ‪ 1433/07/20‬ه ـ ففــي يــوم‬\n‫االثنــن املوافق‪1433/08/12‬ه ـ افتتحــت اجللســة وفيهــا أحضــر املدعــي‬\n‫العــام بينتــه وهــو الشــاهد ‪.....‬حامــل الســجل املدنــي رقــم ‪.....‬وبســؤاله‬\n‫عمــا لديــه أجــاب إننــي أعمــل يف مكافحــة املخــدرات بالريــاض وعمــري‬\n‫ثمــان وعشــرون ســنة وأحمــل املؤهــل الثانوي وال تربطنــي عالقة باملدعى‬\n‫عليهــم وأشــهد أننــي كنــت ضمــن الفرقــة القابضــة علــى املدعــى عليهما‬\n‫وكانــا يف منــزل املدعــى عليــه ‪.....‬بحــي ‪.....‬واملنــزل فيــه رجــال كثيــر‬\n‫ونســاء وقــد متــت عمليــة االســتالم والتســليم حتــت مــرأى زميلــي ‪.....‬‬\n‫ولــم أشــاهدها وإمنــا كنــت ضمــن فرقــة القبــض بعــد عمليــة االســتالم‬\n‫والتســليم وقــد ســمعت املدعــى عليــه ‪.....‬يقــول إن املدعــى عليهــا ‪.....‬هــي‬\n‫التــي ســلمت القــات للمصــدر بينمــا ســمعت زميلــي ‪.....‬يقــول إنــه رأى هــو‬\n‫الــذي ســلم القــات للمصــدر وقــد رأيــت أثنــاء دخولــي املنــزل املذكــور‬\n‫تســع ًا وعشــرين حزمــة قــات وقــد هــرب مــن يف منــزل ولــم يقبــض إال‬\n‫علــى املدعــى عليهمــا هــذا مــا لــدي وبــه أشــهد وقــد عــدل مــن قبــل ‪.....‬‬\n‫وحلــن طلــب باقــي البينــة جــرى رفــع اجللســة وأجلــت ألقــرب موعــد وعليــه‬\n‫جــرى التوقيــع وأغلقــت اجللســة الســاعة احلاديــة عشــرة وعلــى ذلــك جــرى‬\n‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة بالريــاض‬\n‫ففــي يــوم االثنــن ‪ 1433/11/29‬ه ـ افتتحــت اجللســة التاســعة وفيهــا‬\n‫أحضــر املدعــي العــام بينتــه وهــو الشــاهد ‪.....‬حامــل الســجل املدنــي‬\n‫رقــم ‪ .....‬وبســؤاله عمــا لديــه أجــاب إننــي أعمــل يف مكافحــة املخــدرات‬\n\n\n                                                                                     ‫‪142‬‬\n\f      ‫بالريــاض وعمــري ســبع وعشــرون ســنة وأحمــل املؤهــل الثانــوي وال‬\n      ‫تربطنــي عالقــة باملدعــى عليهــم وأشــهد أننــي كنــت مرافق ـ ًا للمصــدر‬\n      ‫الــذي قــام بعمليــة الشــراء مــن املدعــى عليــه املدعــى عليــه الثانــي حيــث‬\n      ‫توقفنــا أمــام أحــد املنــازل بحــي ‪ .....‬وعندمــا دخلنــا املنــزل شــاهدنا‬\n      ‫بداخلــه رجــا ًال و نســاء كثيريــن واجتهــت أنــا واملصــدر للمدعــى عليــه‬\n      ‫‪ .....‬وبجانبــه إحــدى النســاء و أمامهــم كميــة مــن نبــات القــات احملظــور‬\n      ‫وطلــب املصــدر مــن املدعــى عليــه ‪ .....‬شــراء قــات مخــدر مببلــغ (‪)150‬‬\n      ‫مائــة و خمســن ريــا ًال فاســتعدت املــرأة التــي بجانــب املدعــى عليــه ‪.....‬‬\n      ‫بعدهــا قــام املدعــى عليــه بتســليم املصــدر علــى مــرأى منــي حزمــة يشــتبه‬\n      ‫أن تكــون مــن نبــات القــات املخــدر بلــغ وزنهــا (‪ )110‬جــرام و قــام‬\n      ‫املصــدر بتســليم املــرأة املبلــغ احلكومــي املرقــم و بعــد مداهمــة املنــزل‬\n      ‫لــم أمتكــن مــن معرفــة املــرأة التــي قامــت باســتالم املبلــغ و ذلــك بســبب‬\n      ‫وجــود عــدد كبيــر مــن النســاء مــن ذوي البشــرة الســمراء هــذا مــا لــدي‬\n      ‫و بــه أشــهد و عــدل مــن قبــل ‪.....‬يحمــل ســجل مدنــي رقــم ‪.....‬و ‪.....‬حامــل‬\n      ‫الســجل املدنــي رقــم ( ‪ ).....‬و كذلــك فــإن املزكــي ‪.....‬عـ ّـدل الشــاهد‬\n      ‫‪.....‬و إلحضــار املدعــى عليهمــا جــرى رفــع اجللســة وأجلــت ألقــرب موعــد‬\n      ‫وعليــه جــرى التوقيــع وأغلقــت اجللســة الســاعة التاســعة وعلــى ذلــك جــرى‬\n             ‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33475424‬وتاريــخ ‪1433/07/20‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331360332‬وتاريــخ ‪1433/07/20‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافق‪1434/01/07‬ه ـ افتتحــت اجللســة العاشــرة وفيهــا‬\n\n\n‫‪143‬‬\n\f‫حضــر املدعــى عليهمــا وبتــاوة شــهادة الشــاهد ‪.....‬وعرضــه علــى‬\n‫املدعــى عليهمــا أجابــا إن شــهادتهما غيــر صحيحــة والشــاهد ال نعرفــه‬\n‫هــذا وقــد جــرى حتديــد عــدة جلســات إلحضــار البينــة ولــم يحضــر‬\n‫املدعــي العــام إال شــاهدين ومــا هــو مــدون يف أوراق املعاملــة وبســؤال‬\n‫املدعــى عليهمــا عــن ســوابقهما أقــرا بهــا هــذا وقــد جــرى االطــاع علــى‬\n‫أقــوال املدعــى عليــه ‪.....‬لفــة ( ‪ ) 20‬املتضمــن قولــه أنــه طلــب املدعــى‬\n‫عليهــا يف منزلــه لشــراء نبــات القــات ودخــل معــه مجموعــة مــن الرجــال‬\n‫والنســاء ليشــتروا منهــا وأنــه اســتلم منهــا حزمــة قــات وكانــت املدعــى‬\n‫عليهــا تبيــع القــات علــى املجموعــة وأثنــاء ذلــك متــت املداهمــة والقبــض‬\n‫عليــه وعلــى املدعــى عليهــا ‪.....‬وأنــه وجــد يف منزلــه عــدد ‪ 29‬حزمــة قــات‬\n‫وزنهــا ســتة كيلــوات وتســعون جرامـ ًا وأنهــا للمدعــى عليهــا ‪.....‬وبعرضــه‬\n‫عليــه صــادق عليــه كمــا ألفيــت قــول املدعــى عليهــا ص ‪ 1‬لفــة ( ‪21‬‬\n‫) املتضمــن أن ســبب حضورهــا ملنــزل املدعــى عليــه عزميــة دعتهــا إليــه‬\n‫إحــدى صديقاتهــا واســمها ‪.....‬ثــم جــرى ســؤالها مــا ســبب حضــورك‬\n‫ملنــزل املدعــى عليــه ‪.....‬فقالــت ذهبــت أنــا مــع اثنتــن مــن صديقاتــي‬\n‫ألجــل عمــل حنــاء لنســاء يف منــزل املدعــى عليــه ‪.....‬فتــم القبــض علــي‬\n‫وهــرب اآلخــرون وكان املنــزل مليئـ ًا بالرجــال والنســاء فجــرى ســؤالها‬\n‫مــا اســم صديقتــك التــي دعتــك إلــى احلضــور فقالــت ‪.....‬وبعــرض قولهــا‬\n‫املذكــور يف محضــر التحقيــق قالــت الصحيــح مــا ذكــرت يف مجلــس‬\n‫احلكــم ثــم جــرى ســؤالها مــاذا كنــت حتملــن يف شــنطتك فقالــت‬\n‫فلــوس وحبــوب فيتامينــات ألنــي حامــل فجــرى ســؤالها أنــك ذكــرت يف‬\n‫أقوالــك ص ‪ 1‬لفــة ( ‪ ) 21‬أنــه لــم يكــن معــك شــنطة نهائي ـ ًا فقالــت ال‬\n‫كانــت معــي شــنطة صغيــرة هكــذا أجابــت فجــرى ســؤالها هــل لديــك‬\n\n\n                                                                                    ‫‪144‬‬\n\f      ‫ســابقة فقالــت ســابقة واحــدة وهــي أخالقية حوكمت فيها بســجن ســتة‬\n      ‫أشــهر هكــذا أجابــت هــذا و قــد جــرى االطــاع علــى محضــر القبــض‬\n      ‫فألفيتــه كمــا ذكــر الدعــوى كمــا جــرى االطــاع علــى التقريــر‬\n      ‫الكيميائــي ‪.....‬عــام ‪1433‬ه ـ الصــادر مــن مركــز الســموم بالريــاض‬\n      ‫و املتضمــن إيجابيــة إحــدى العينتــن ملــادة االمفيتامــن و الثانيــة ملــادة‬\n      ‫القــات ا‪.‬ه ـ بتصــرف ثــم جــرى ســؤال املدعــى عليــه ‪.....‬هــل لديــك بينــة‬\n      ‫علــى أن املدعــى عليــه هــي صاحبــة القــات فقــال ال فبنــاء علــى مــا ســلف‬\n      ‫مــن الدعــوى و اإلجابــة وإلقــرار املدعــى عليــه ‪.....‬بتعاطيــه القــات و وجــود‬\n      ‫القويــة بتســليم‬\n                    ‫ّ‬      ‫تســع و عشــرين حزمــة قــات يف منزلــه و لقيــام القرينــة‬\n      ‫املدعــى عليــه ‪.....‬القــات ذي الــوزن مائــة و عشــرة جرامــات وهــي مــا جــاء‬\n      ‫يف شــهادة الشــاهد املعــدل ‪.....‬و لقيــام القرينــة علــى حيــازة املدعــى عليهــا‬\n      ‫‪.....‬ســبع حبــات امفيتامــن وهــي إقرارهــا بوجــود حبــات يف شــنطتها و‬\n      ‫وجــود ســابقة مخــدرات و تناقضهــا يف ذكــر الشــنطة مــن عدمــه وســبب‬\n      ‫دعــوة احلضــور واســم الداعيــة و إلقــرار املدعــى عليــه ‪.....‬بوجــود رجــال‬\n      ‫و نســاء يف منزلــه حضــروا ليشــتروا القــات وألن األصــل أن مــا كان‬\n      ‫يف بيــت املــرء مــن حوزتــه و لعــدم وجــود بينــه لــدى املدعــى عليــه علــى‬\n      ‫اتهامــه املدعــى عليهــا بحيــازة القــات و ملــا جــاء يف برقيــة ســمو وزيــر‬\n      ‫الداخليــة رقــم ‪ 13476‬يف ‪1433/02/23‬ه ـ و القــرار الــوزاري رقــم‬\n      ‫‪ 3818‬يف ‪1410/09/28‬ه ـ ورقــم ‪ 2057‬يف ‪1404/05/26‬ه ـ ورقــم‬\n      ‫‪1374/02/11‬ه ـ وملشــروعية التعزيــر بالتهمــة كمــا حبــس النبــي صلــى‬\n      ‫ا يف تهمــة رواه أبــو داوود و الترمــذي و قــال حســن‬      ‫اهلل عليــه و ســلم رجـ ً‬\n      ‫أخالقيــة علــى‬\n                 ‫ّ‬        ‫صحيــح ولوجــود ســوابق علــى املدعــى عليــه ‪.....‬و ســابقة‬\n      ‫املدعــى عليهــا ‪.....‬مقرونــة بحيــازة مخــدرات فقــد ثبــت لدي إدانــة املدعى‬\n\n\n‫‪145‬‬\n\f‫عليــه ‪.....‬بتعاطــي القــات و حيازتــه كميــة منــه وزنهــا ســتة كيلــو جــرام‬\n‫و تســعون جرامـ ًا بقصــد التعاطــي والترويــج وجعلــه منزلــه وكــر ًا لشــراء‬\n‫القــات وتعاطيــه ولــم يثبــت لــدي إدانتــه بتســليم قــات وزنــه مائــة وعشــرة‬\n‫جرامــات وإمنــا قامــت الشــبهة القويــة علــى ذلــك و لــم يثبــت لــدي إدانــة‬\n‫املدعــى عليــه ‪ .....‬بحيــازة ســبع حبــات امفيتامــن وإمنــا قامــت الشــبهة‬\n‫علــى ذلــك وحكمــت عليهــا مبــا يلــي ‪ /1 :‬ســجن املدعــى عليــه ‪.....‬‬\n‫ســنتني وجلــده أمــام النــاس مائتــن وخمســن جلــدة مفرقــة علــى خمــس‬\n‫دفعــات كل دفعــة خمســون جلــدة و بــن كل دفعتــن عشــرة أيــام وذلــك‬\n‫شــامل لعقوبــة اإلدانــة بحيــازة القــات وتعاطيــه وإعــداد املنــزل لتعاطــي‬\n‫القــات وشــرائه والتهمــة بالتســليم املذكــور ‪ /2‬ســجن املدعــى عليهــا‬\n‫‪ .....‬خمســة أشــهر وإبعادهــا عــن البــاد بعــد تنفيــذ احلكــم و الســجن‬\n‫القضيــة‪ /3 .‬صــرف النظــر‬\n                         ‫ّ‬       ‫احملكــوم بــه يبــدأ مــن تاريــخ اإليقــاف بهــذه‬\n‫عــن املطالبــة بــرد املبلــغ والتســتر لعــدم وجــود موجبــه وبعــرض احلكــم‬\n‫علــى املدعــى عليــه واملدعــى عليهــا واملدعــي العــام قــرر املدعــى عليــه‬\n‫القناعــة وقــررت املدعــى عليهــا القناعــة وقــرر املدعــي العــام االعتــراض‬\n‫مكتفي ـ ًا بالئحــة الدعــوى عــن الالئحــة االعتراضيــة و كان النطــق‬\n‫باحلكــم يف ‪1434/01/07‬ه ـ و أغلقــت اجللســة الســاعة العاشــرة‬\n   ‫والنصــف و صلــى اهلل و ســلم علــى نبينــا محمــد و علــى آلــه وصحبــه‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم األربعــاء ‪1434/07/12‬ه ـ افتتحــت اجللســة الثامنــة‬\n‫وفيهــا حضــر املدعــى عليــه وقــد وردتنــا املعاملة من محكمة االســتئناف‬\n‫بقــرار املالحظــة رقــم ‪ 34215624‬يف ‪1434/05/19‬ه ـ واملتضمــن بعــد‬\n‫املقدمــة أنــه « بدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n\n\n                                                                                       ‫‪146‬‬\n\f      ‫باإلجمــاع لوحــظ باألكثريــة مــا يلــي‪ / 1 :‬أثبــت فضيلتــه حيــازة املدعــى‬\n      ‫عليــه ‪ .....‬لكميــة القــات بالقــرار و بالدعــوى و حكــم عليــه بالســجن‬\n      ‫واجللــد و لــم جنــد أن فضيلتــه حكــم عليــه بغرامــة ماليــة و ال بــد مــن ذلك‬\n      ‫حســب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ‪ /2‬مــا حكــم بــه‬\n      ‫فضيلتــه مــن ســجن املدعــى عليــه ‪ .....‬قليــل جــد ًا لكبــر كميــة القــات‬\n      ‫املضبوطــة عليهــا مبنزلــه و إلعــداد منزلــه و كــر ًا للفســاد و لســوابقه‬\n      ‫التــي لــم تردعــه فــا بــد مــن عقوبــة زاجــرة لــه و رادعــة لغيــره فعلــى‬\n      ‫فضيلتــه مالحظــة مــا ذكــر و إجــراء مــا يلــزم نحوهــا و إحلــاق ملخــص‬\n      ‫مــا يجريــه يف الضبــط إلــى القــرار و مــن ثــم إعــادة املعاملــة إلكمــال‬\n      ‫الزمهــا حســب» وجوابــا علــى مــا الحظــه أصحــاب الفضيلــة يف املالحظــة‬\n      ‫األولــى فقــد حكمــت علــى املدعــى عليــه بغرامــة ماليــة قدرهــا (‪)1000‬‬\n      ‫الســابق‬‫ألــف ريــال و علــى املالحظــة الثانيــة فقــد رجعــت عــن حكمــي ّ‬\n      ‫املتعلــق بســجن املدعــى عليــه ‪.....‬و جلــده ليكــون ســجنه ثالثــن شــهر ًا‬\n      ‫يبــدأ مــن تاريــخ اإليقــاف و جلــده ثالثمائــة و خمســن جلــدة مفرقــة عــل‬\n      ‫ســبع دفعــات كل دفعــة خمســون جلــدة أمــام النــاس و بــن كل دفعتــن‬\n      ‫عشــرة أيــام وبعرضــه عليهــا قــرر املدعــى عليــه القناعــة و املدعــي العــام‬\n      ‫االعتــراض مكتفيـ ًا بالئحــة الدعــوى و انتهــت اجللســة الســاعة الثامنــة‬\n      ‫والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪ 1434/07/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪341319911‬‬\n      ‫وتاريــخ ‪1434/8/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n\n\n‫‪147‬‬\n\f‫باحملكمــة الشــيخ ‪ /‬املســجل برقــم ‪ 3412610‬وتاريــخ ‪1434/1/14‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪..... -2 ).....(..... -1‬‬\n‫( صوماليــة اجلنســية) التهامهمــا بقضيــة ترويــج القــات علــى النحــو‬\n‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‬\n‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n‫ـاء‬\n ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n‫علــى قرارنــا رقــم ‪ 34215624‬وتاريــخ ‪1434/5/19‬ه ـ تقــرر الدائــرة‬\n‫باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬و اهلل املوفــق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪148‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":134,"source_page_end":148,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"537798e4eb3d773e964624f665d31b653752023518551497c58a41f64f0bc901","normalized_text_hash":"d612006210c399c412ec0bf6a2f1c74f9024eb21702e41ecbb839a050be090ac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p134-3412610"},{"id":"c18855f6-7799-53ec-8032-82fb2970ec1f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة مادة الكراك -حيازة احلشيش املخدر -ترويج احلشيش املخدر -الشروع يف بيع احلشيش املخدر -عدم ثبوت إدانة -تعزير ألجل الشبهة -التعزير بالسجن واجللد -1قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة ) -2قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث ) -3نهي النبي صلى اهلل عليه وسلم عن كل مسكر ومفتر الئحة الدعوى العامة ضد املدعى عليه بحيازة مادة الكراك","document_number":"34176897","case_number":"33481973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"مخدرات -حيازة مادة الكراك -حيازة احلشيش املخدر -ترويج احلشيش املخدر -الشروع يف بيع احلشيش املخدر -عدم ثبوت إدانة -تعزير ألجل الشبهة -التعزير بالسجن واجللد -1قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة ) -2قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث ) -3نهي النبي صلى اهلل عليه وسلم عن كل مسكر ومفتر الئحة الدعوى العامة ضد املدعى عليه بحيازة مادة الكراك","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34176897 :‬تاريخه ‪1434/4/2:‬هـ‬\n                         ‫رقم الدعوى ‪33481973:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34257032‬تاريخه‪1434/07/02:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة مــادة الكــراك‪ -‬حيــازة احلشــيش املخــدر‪ -‬ترويــج‬\n      ‫احلشــيش املخــدر‪ -‬الشــروع يف بيــع احلشــيش املخــدر‪ -‬عــدم ثبــوت‬\n                 ‫إدانــة‪ -‬تعزيــر ألجــل الشــبهة‪ -‬التعزيــر بالســجن واجللــد‬\n\n\n\n\n                         ‫‪ -1‬قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة )‬\n              ‫‪ -2‬قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث )‬\n                 ‫‪ -3‬نهي النبي صلى اهلل عليه وسلم عن كل مسكر ومفتر‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بحيــازة مــادة الكــراك‬\n      ‫وحيــازة احلشــيش املخــدر بقصــد الترويــج والشــروع يف بيعهــا‪ ،‬وطلــب‬\n      ‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالســجن واجللــد‬\n      ‫والغرامــة ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة وإلغــاء اخلدمــة‬\n      ‫عــن الشــريحة وعــدم صرفهــا مــرة أخــرى وإبعــاد املدعــى عليــه خــارج‬\n      ‫البــاد بعــد تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة‪ ،‬مت القبــض علــى‬\n      ‫ـاء علــى إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج‬\n                                                                    ‫املدعــى عليــه بنـ ً‬\n      ‫مــادة الكــراك ويتواجــد علــى هاتــف جوالــه ومت االتفــاق معــه مــن‬\n      ‫قبــل املصــدر الســري علــى شــراء كميــة مــن مــادة الكــراك وشــوهد‬\n\n‫‪149‬‬\n\f‫املدعــى عليــه وهــو قــادم ثــم غيــر مســاره إلــى أن وصــل للمصــدر ثــم‬\n‫مت القبــض عليــه وتتبــع مســاره فوجــد يف املــكان الــذي وضــع يــده يف‬\n‫جيبــه علــى كيــس بــه قطعتــن‪ ،‬صــدر التقريــر الكيميائــي إيجابيــة‬\n‫احدهمــا ملــادة الكوكايــن املخــدر والثانيــة ملــادة احلشــيش املخــدر‪،‬‬\n‫إنــكار املدعــى عليــه‪ ،‬إحضــار الفرقــة القابضــة‪ ،‬توجيــه التهمــة ضــد‬\n‫املدعــى عليه‪،‬تعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬تصديــق احلكــم‬\n                                                ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .................‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة يف محافظة جدة‪/‬املســاعد برقم ‪33481973‬‬\n‫وتاريخ ‪ 1433/07/22‬هـ املقيدة باحملكمة برقم ‪ 331378007‬وتاريخ‬\n‫‪ 1433/07/21‬ه ـ ففــي يــوم الســبت املوافــق‪ 1433/07/26‬ه ـ افتتحت‬\n‫اجللسة الساعة ‪ 08 : 15‬وفيها حضر املدعي العام سعودي ‪..............‬‬\n‫املكلــف باالدعــاء العــام مبوجــب خطــاب هيئــة التحقيــق واالدعــاء العــام‬\n‫رقــم ‪ 15832‬وتاريــخ ‪1433/3/6‬ه ـ وأدعــى قائــا بصفتــي مدعيــا‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظــة جــدة ادعــي علــى ‪)45( ..............‬‬\n‫عامـ ًا تشــادي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )..............‬وتاريــخ‬\n‫‪1433/6/17‬ه ـ صــادرة مــن مكافحــة املخــدرات مبحافظــة جــدة املهنــة‬\n‫‪ /‬عاطــل موقــوف بســجن محافظــة جــدة مبوجــب أمــر متديــد التوقيــف‬\n‫رقم (هـ م‪ )42298/5/2‬وتاريخ ‪1433/6/22‬هـ استناد ًا للقرار الوزاري‬\n‫رقــم (‪ )1900‬املقبــوض عليــه بتاريــخ ‪1433/6/17‬ه ـ مــن قبــل مكافحــة‬\n\n                                                                                        ‫‪150‬‬\n\f      ‫رجــال الضبــط اجلنائــي مبكافحــة املخــدرات مبحافظــة جــدة بنــاء علــى‬\n      ‫إخباريــة أحــد املصــادر الســرية عــن ترويــج املدعــى عليــه ملــادة الكــراك‬\n      ‫ويتواجــد علــى هاتفــه احملمــول رقــم (‪ )..............‬وباتفــاق املصــدر معــه‬\n      ‫علــى شــراء كميــة مــن الكــراك مببلــغ (‪ )200‬مائتــن ريــال شــوهد‬\n      ‫املدعــى عليــه قادمـ ًا مــن داخــل أحــد األزقــة ومت وضعــه حتــت املراقبــة ثــم‬\n      ‫غيــر مســاره باجتــاه آخــر بــن مركبــات (الدينــا) كانــت متوقفــة داخــل‬\n      ‫احلــي وشــوهد وهــو يضــع يــده بجيبــه ثــم ذهــب للمصــدر ومت القبــض‬\n      ‫عليــه وعثــر معــه علــى الهاتــف احملمــول الــذي مت التنســيق مــن خاللــه‬\n      ‫وبالرجــوع خلــط ســيره وحتديــد ًا يف املــكان الــذي شــوهد يضــع يــده‬\n      ‫يف جيبــه وجــدت قطعتــان األولــى قطعــة بيضــاء اللــون شــبه صلبــة بلــغ‬\n      ‫وزنهــا (‪ )0.4‬أربعــة أعشــار اجلــرام بداخــل كيــس والثانيــة قطعــة بيضــاء‬\n      ‫اللــون شــبه صلبــة بلــغ وزنهــا (‪ )0.3‬ثالثــة أعشــار اجلــرام بداخــل كيــس‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/2219‬ك ش م) لعــام‬\n      ‫‪1433‬ه ـ احتــواء العينــة (أ)مــن الكمييــة املضبوطــة واملرســلة للتحليــل‬\n      ‫علــى مــادة الكوكائــن املخــدر املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ)‬\n      ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحتــواء العينــة‬\n      ‫(ب) علــى مــادة احلشــيش املخــدر واحتواؤهــا علــى املــادة الفعالــة لــه‬\n      ‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وقــد انتهــى التحقيــق الــى توجيــه االتهــام الــى‬\n      ‫املدعــى عليــه بحيــازة (‪ )0.4‬أربعــة أعشــار اجلــرام مــن مــادة الكــراك‬\n      ‫وحيازة(‪)0,3‬ثالثــة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر بقصــد‬\n      ‫الترويــج والشــروع يف بيعهــا اســتناد ًا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لألدلــة والقرائــن‬\n\n\n‫‪151‬‬\n\f‫التاليــة مــا ورد يف شــهادة الشــهود مبحضــر الضبــط املنــوه عنــه واملرفــق‬\n‫لفــة رقــم (‪ )1‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق‬\n‫لفــة (‪ )22‬اإلخباريــة الــواردة عنــه وحملــه وإحضــاره للكميــة املخــدرة‬\n‫باملوقــع ومقابلتــه للمصــدر وضبــط اجلــوال املســتخدم يف التنســيق يف ظــل‬\n‫عــدم وجــود مصــدر دخــل ثابــت لــه كلهــا قرائــن تؤكــد مــا أســند إليــه‬\n‫وباالطــاع علــى ســوابقه عثــر علــى ســابقة (حيــازة مخــدرات) وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا مــن‬\n‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومعاقــب عليــه وفقــا للمــادة (‪)59 ، 38‬‬\n‫مــن ذات النظــام مــع مراعــاة مــا وردة باملــادة(‪ )62‬لــذا أطلــب إثبــات مــا‬\n‫أســند إليــه ومعاقبتــه بالعقوبــات األصليــة والتكميليــة التاليــة بالســجن‬\n‫واجللــد والغرامــة اســتنادا للمــادة(‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة املشــار إليــه مــع تشــديد العقوبــة عليهاســتنادا‬\n‫للفقــرة(‪/2‬ج) مــن ذات املــادة مصــادرة جهــاز الهاتــف احملمــول مــن نــوع‬\n‫(‪ ).....‬ذي الرقــم املصنعــي (‪ )..............‬املســتخدم يف ارتــكاب اجلرميــة‬\n‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه وإلغــاء اخلدمــة عــن الشــريحة وعــدم صرفهــا لســوء‬\n‫اســتخدامها اســتناد ًا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n‫رقــم (‪ )9798‬يف ‪9‬ــ‪1428/2/10‬ه ـ إبعــاده خلــارج اململكــة بعــد االنتهــاء‬\n‫مــن تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا اســتناد ًا للفقــرة (‪)2‬‬\n‫مــن املــادة (‪ )56‬مــن نظــام املخــدرات املشــار إليــه وبعــرض مــاورد بدعــوى‬\n‫املدعــي العــام علــى املدعــى عليــه احلاضــر يف املجلــس الشــرعي أجــاب‬\n\n\n                                                                                          ‫‪152‬‬\n\f      ‫قائــا مــاورد يف دعــوى املدعــي العــام توجيــه االتهــام لــي بحيــازة (‪)0.4‬‬\n      ‫أربعــة أعشــار اجلــرام مــن مــادة الكــراك وحيازة(‪)0,3‬ثالثــة أعشــار‬\n      ‫اجلــرام مــن مــادة احلشــيش املخــدر بقصــد الترويــج والشــروع يف بيعهــا‬\n      ‫فغيــر صحيــح جملــة وتفصيــا هــذا جوابــي علــى الدعــوى عليــه فقــد‬\n      ‫جــرى ســؤال املدعــي العــام هــل لديــه بينــه علــى مــا ذكــر قــال نعــم لــدي‬\n      ‫بينــه علــى مــا ذكــرت ومســتعد بإحضارهــم وعليــه فقــد رفعــت اجللســة‬\n      ‫لتكليــف املدعــي العــام بإحضــار بينتــه وجــرى قفلهــا يف متــام الســاعة‬\n      ‫الثامنــة والنصــف صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/07/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/01/25‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة احلاديــة عشــر والربــع صباحــا وفيهــا حضــر‬\n      ‫املدعــي العــام وأحضــر للشــهادة وأدائهــا كال مــن ‪ ..............‬ســعودي‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ..............‬والــذي يعمــل برتبــه عريــف يف‬\n      ‫إدارة مكافحــة املخــدرات مبحافظــة جــدة ‪ ..............‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ..............‬والــذي يعمــل برتبــه رقيــب يف‬\n      ‫إدارة مكافحــة املخــدرات مبحافظــة جــدة وبســؤالهما عمــا لديهمــا مــن‬\n      ‫شــهادة بعــد إطالعهمــا علــى محضــر القبــض شــهد كل واحــد منهمــا‬\n      ‫علــى انفــراد قائــا نشــهد بــاهلل العظيــم بــأن جميــع مــاورد يف محضــر‬\n      ‫القبــض صحيــح جملــة وتفصيــا واملتضمــن انــه بتاريــخ ‪1433/6/17‬ه ـ‬\n      ‫مت القبــض علــى املدعــى عليــه مــن قبلنــا نحــن وباقــي أفــراد الفرقــة‬\n      ‫القابضــة بنــاء علــى إخباريــة أحــد املصــادر الســرية عــن ترويــج املدعــى‬\n      ‫عليــه ملــادة الكــراك ويتواجــد علــى هاتفــه احملمــول رقــم (‪)..............‬‬\n      ‫وباتفــاق املصــدر معــه علــى مســمع منــا علــى شــراء كميــة مــن الكــراك‬\n\n\n‫‪153‬‬\n\f‫مببلــغ (‪ )200‬مائتــن ريــال مت انتقالنــا والوصــول للموقــع املتفــق عليــه‬\n‫وبــه متركــز املصــدر ومتركــزت عناصــر الفرقــة يف أنحــاء متفرقــة منــه‬\n‫ويف هــذه األثنــاء شــوهد املدعــى عليــه قادم ـ ًا مــن داخــل أحــد األزقــة‬\n‫ومت وضعــه حتــت املراقبــة ثــم غيــر مســاره باجتــاه آخــر بــن مركبــات‬\n‫(‪ )........‬كانــت متوقفــة داخــل احلــي وشــوهد وهــو يضــع يــده بجيبــه ثــم‬\n‫ذهــب للمصــدر ومت القبــض عليــه وعثــر معــه علــى الهاتــف احملمــول‬\n‫الــذي مت التنســيق مــن خاللــه وبالرجــوع خلــط ســيره وحتديــد ًا يف املكان‬\n‫الــذي شــوهد يضــع يــده يف جيبــه وجــدت قطعتــان األولــى قطعــة بيضــاء‬\n‫اللــون شــبه صلبــة بلــغ وزنهــا (‪ )0.4‬أربعــة أعشــار اجلــرام بداخــل كيــس‬\n‫والثانيــة قطعــة بيضــاء اللــون شــبه صلبــة بلــغ وزنهــا (‪ )0.3‬ثالثــة أعشــار‬\n‫اجلــرام بداخــل كيــس هــذا مالدينــا مــن شــهادة واهلل خيــر الشــاهدين‬\n‫هــذا ثــم جــرى رفــع اجللســة لعــرض الشــهود وشــهادتهم علــى املدعــى‬\n‫عليهــم وجــرى قفلهــا يف متــام الســاعة احلاديــة عشــر والنصــف صباحــا‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                 ‫حــرر يف ‪ 1434/01/25‬ه ـ‬\n‫احلمد هلل وحده وبعد ففي يوم السبت املوافق‪1434/02/09‬هـ افتتحت‬\n‫اجللســة الســاعة التاســعة والربــع صباحــا وفيهــا حضــر الطرفــان وبعــرض‬\n‫الشــهود وشــهادتهم علــى املدعــى عليــه احلاضــر يف املجلــس الشــرعي‬\n‫أنكــر مــاورد فيهــا جملــة وتفصيــا وقــال الشــهادة غيــر صحيحــة وأمــا‬\n‫الشــهود فــا أعرفهــم وال أريــد البحــث عــن حالهــم عليــه فقــد جــرى‬\n‫طلــب مزكــن للشــهود وجــرى قفلهــا يف متــام الســاعة التاســعة والنصــف‬\n‫صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                           ‫وســلم حــرر يف ‪ 1434/02/09‬ه ـ‬\n\n\n                                                                                     ‫‪154‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافق‪1434/02/12‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الثامنــة والربــع صباحــا حضــر املدعــي العــام‬\n      ‫وأحضــر للتزكيــة كال مــن ‪ ..............‬ســعودي مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..............‬والــذي يعمــل برتبــه عريــف يف مكافحــة املخــدرات بجــدة‬\n      ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬والذي‬\n      ‫يعمــل برتبــه جنــدي يف مكافحــة املخــدرات مبحافظــة جــده وبســؤالهما‬\n      ‫عمــا لديهمــا مــن تزكيــة شــهد كل وأحــد منهمــا علــى انفــراد قائــا‬\n      ‫نشــهد بــاهلل العظيــم أن الشــهود املذكوريــن يف هــذه القضيــة معروفــن‬\n      ‫باألمانــة والعدالــه والثقــه نحســبهم كذلــك واهلل حســيبهم هــذا ثــم‬\n      ‫جــرى رفــع اجللســة ليــوم الســبت املوافــق ‪1434/2/16‬ه ـ ألحضــار‬\n      ‫الســجني وجــرى قفلهــا يف متــام الســاعة الثامنــة والنصــف صباحــا وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                               ‫يف ‪ 1434/02/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الثامنــة وخمــس وربعــون دقيقــة صباحــا‬\n      ‫وفيهــا حضــر الطرفــان فبنــاء علــى ماتقــدم مــن الدعــوى واالجابــه‬\n      ‫وشــهادة الشــهود املعدلــن طبقــا لألصــول الشــرعية وحيــث أن الشــريعة‬\n      ‫االســاميه جــاءت بحفــظ الضروريــات اخلمــس الديــن والنفــس والعقــل‬\n      ‫واملــال والعــرض وهــذه آالفــه مذهبــه للديــن ومهلكــه للنفــس ومفســده‬\n      ‫للعقــل مضيعــة للمــال والعــرض ولقولــه تعالــى { وال تلقــوا بأيديكــم‬\n      ‫إلــى التهلكــة } وقولــه تعالــى {ويحــل لهــم الطيبــات ويحــرم عليهــم‬\n      ‫اخلبائــث } ولنهيــه صلــى اهلل عليــه وســلم عــن كل مســكر ومفتــر وملــا‬\n      ‫يف ذلــك الضــرر علــى املدعــى عليــة وعلــى املجتمــع بأســره ومــا تســببه‬\n\n\n‫‪155‬‬\n\f‫مــن انحــال وتدميــر وانتشــار للفســاد والرذيلــه وملــا يف فعــل املدعــى‬\n‫عليــه مــن عصيــان هلل ولرســوله ولولــي األمــر وحيــث إن التعزيــر مشــروع‬\n‫يف كل معصيــة ال حــد فيهــا وال كفــاره وحيــث أن مــا قــدم املدعــي‬\n‫العــام ال يكفــي اليثبــات إدانــة املدعــى عليــه وإمنــا يقــوي الشــبهه يف حقــه‬\n‫مبــا أســند إليــه وحكمــت عليــه لقــاء ذلــك مبــا يلــي أو ًال ســجنه ملــدة‬\n‫خمــس ســنوات حتســب منهــا مــده إيقافــه علــى ذمــة هــذه القضيــة وجلــده‬\n‫أربعمائــة ســوط علــى دفعــات كل دفعــة خمســن ســوط بــن كل دفعــة‬\n‫والتــي تليهــا مــدة ال تقــل عــن خمســة أيــام ثاني ـ ًا إبعــاده عــن البــاد بعــد‬\n‫انتهــاء تنفيــذ محكوميتــه وعــدم الســماح لــه بالعـ ــودة إليهــا ومصــادرة‬\n‫الهاتــف اجلــوال املضبــوط بحوزتــه وإلغــاء شــريحته وعــدم صرفهــا لــه‬\n‫مــرة أخــرى وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر‬\n‫املدعــي العــام عــدم القناعــة وطلــب االســتئناف فأجبتــه لطلبــه وســيجري‬\n‫اتخــاذ الــازم حســب التعليمــات جــرى النطــق باحلكــم يف متــام الســاعة‬\n‫التاســعة صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم حــرر يف ‪ 1434/03/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/7/16‬ه ـ الســاعة‬\n‫التاســعة فتحــت اجللســة لــدي انــا ‪ ..............‬القاضــي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــده والقائــم بعمــل القاضــي ‪ ..............‬مبوجــب خطــاب‬\n‫التكليــف رقــم ‪341712792‬يف ‪1434/7/16‬ه ـ وجــرى االطــاع علــى‬\n‫أوراق املعاملــة وكانــت قــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة وبرفقهــا قرارهــا رقــم ‪34257032‬يف ‪1434/7/2‬ه ـ‬\n‫باملصادقــة علــى احلكــم ونــص احلاجــة منــه (وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل‬\n\n\n                                                                                          ‫‪156‬‬\n\f      ‫املوفــق )وموقــع ومختــم مــن أصحــاب الفضيلــة أعضــاء الدائــرة اجلزائيــة‬\n      ‫الســابعة وهــم كال مــن الشــيخ ‪ ..............‬والشــيخ ‪ ..............‬لــي وجهــة‬\n      ‫نظــر والشــيخ ‪ ..............‬فجــرى تدوينــه حفظــا للواقــع وجــرى قفلهــا يف‬\n      ‫متــام الســاعة التاســعة والنصــف وصلــى اهلل علــى نبينــا محمــد والــه‬\n                                                                        ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":149,"source_page_end":157,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"76c40dc3f0d85d46af71cee0c79d5ea8f600b2bf2e9e1d572243b86bcf278628","normalized_text_hash":"124c1c770ae9b6301a34a1cdc9ab8a7a18ccb483e3ec1fa7c5426b005ba06a41","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p149-34176897"},{"id":"846852d3-9e7e-5e7e-9d40-b45b56324ed2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -عدم قبول الرجوع عن اإلقرار -إدانة -تعزير بالسجن واملنع من السفر.","document_number":"33482733","case_number":"33507446","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -عدم قبول الرجوع عن اإلقرار -إدانة -تعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33482733:‬تاريخه‪1433/12/29:‬هـ‬\n                   ‫رقم الدعوى‪33507446:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3448164‬تاريخه‪1434/02/26:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي‪ -‬عــدم قبــول‬\n‫الرجــوع عــن اإلقــرار‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n‫‪ -1‬حقــوق اهلل تعالــى التــي ال تــدرأ بالشــبهة ال يقبــل فيهــا الرجــوع عــن‬\n                                        ‫اإلقــرار بــا خــاف‪( .‬املغنــي ‪.)5/95‬‬\n   ‫‪ -2‬املواد (‪ )41‬و (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة حبــوب اإلمفيتامــن بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة‬\n‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى حبــوب‬\n‫يحتمــل أن تكــون محظــورة‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n‫إيجابيــة العينــة املرســلة ملــادة اإلمفيتامــن‪ ،‬اعتــرف أمــام جهــة التحقيــق‬\n‫بحيازتــه للحبــوب احملظــورة بقصــد التعاطــي‪ ،‬أنكــر أمــام احملكمــة‬\n‫مــا أســنده إليــه املدعــي العــام‪ ،‬مــن املقــرر شــرع ًا أن حقــوق اهلل تعالــى‬\n‫التــي ال تــدرأ بالشــبهة ال يقبــل فيهــا الرجــوع عــن اإلقــرار بــا خــاف‪،‬‬\n‫قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه وقــررت ســجنه‬\n\n                                                                                      ‫‪158‬‬\n\f      ‫ملــدة ســتة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض‬\n      ‫املدعــى عليــه واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمة االســتئناف‬\n                                                         ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل املكلــف برقــم ‪ 33507446‬وتاريــخ ‪ 1433/08/05‬ه ـ‬      ‫ّ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331470739‬وتاريــخ ‪ 1433/08/05‬ه ـ ففــي‬\n      ‫يــوم األربعــاء املوافــق‪ 1433/12/29‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫احلاديــة عشــرة وفيهــا حضــر املدعــي العــام وادعــى علــى احلاضــر معــه‬\n      ‫ســعودي بالســجل رقــم (‪ )........‬بالئحــة دعــوى هــذا نصهــا (بأنــه بتاريــخ‬\n      ‫‪1433/6/29‬ه ـ مت اســتيقاف املدعــى عليــه مــن قبــل نقطــة تفتيــش تابعــة‬\n      ‫للقــوة اخلاصــة بأمــن الطــرق علــى طريــق (‪ ).....‬مركــز ‪ .....‬وبقيادتــه‬\n      ‫ســيارة نــوع (‪ ).....‬وعنــد طلــب أوراقــه الثبوتيــة لوحــظ عليــه االرتبــاك‬\n      ‫والتلعثــم بالــكالم وبعــد تفتيــش املركبــة عثــر علــى (‪ )2.5‬حبتــن‬\n      ‫ونصــف احلبــة مــن احملتمــل أن تكــون مــن احلبــوب احملظــورة وجــدت‬\n      ‫حتــت ديكــور القيــر مــن جهــة الراكــب فتــم القبــض عليــه‪ .‬وقــد أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n      ‫الســموم بالقصيــم رقــم (‪ )812‬لعــام ‪1433‬ه ـ إيجابيــة احلبــوب املضبوطــة‬\n      ‫ملــادة اإلمفيتامــن املنبهــة احملظــورة‪ .‬وباســتجوابه أقــر بصحــة واقعــة‬\n      ‫القبــض وحيازتــه ملــا ضبــط بقصــد التعاطــي وأنــه أخذهــا مــن شــخص‬\n      ‫علــى طريــق القصيــم عنــد إحــدى احملطــات‪ .‬وقــد أســفر التحقيــق معــه‬\n\n‫‪159‬‬\n\f‫عــن اتهامــه بحيــازة (‪ )2.5‬حبتــن ونصــف احلبــة مــن حبــوب اإلمفيتامــن‬\n‫املنبهــة واحملظــورة بقصــد التعاطــي وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ )1‬مــا جــاء مبحضــر االســتجواب واملــدون واملرفــق لفــة رقــم (‪.)14.13‬‬\n‫‪ )2‬مــا تضمنــه محضــر القبــض والتفتيــش املــدون علــى الصفحــة رقــم‬\n‫(‪ )9.8‬بتقريــر األحــوال األمنيــة املوحــد املرفــق لفــة رقــم (‪ ) 3.)1‬مــا جــاء‬\n‫يف التقريــر الكيمائــي الشــرعي املشــار إليــه املرفــق لفــة رقــم (‪.)20‬‬\n‫وبالبحــث يف ســجله اجلنائــي اتضــح عــدم وجــود ســوابق مســجلة عليــه‬\n‫حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا ونظام ـ ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا‬\n‫يلــي‪ -1 :‬الســجن ‪ -2‬املنــع مــن الســفر وفق ـ ًا للمادتــن (‪ )56-41‬مــن‬\n‫نظام مكافحة املخدرات واملؤثرات العقلية‪،،،.‬وبالل ــه التوفي ــق‪ ).‬أ‪.‬هـ‪.‬‬\n‫هكــذا ادعــى وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب‬\n‫بقولــه‪ :‬غيــر صحيــح جملــة وتفصيــا‪ .‬ثــم ســألت املدعــي العــام هــل لديــك‬\n‫زيــادة بينــة غيــر مــا قدمــت ؟ قــال‪ :‬ال ســوى مــا وجــد بــأوراق املعاملــة‪.‬‬\n‫ثــم جــرى االطــاع فيهــا علــى اعتــراف املدعــى عليــه حتقيقــا لــدى هيئــة‬\n‫التحقيــق واالدعــاء العــام املــدون علــى لفــة رقــم ( ‪ )14،13‬املتضمــن‬\n‫اعتــراف املدعــى عليــه بحيازتــه للمؤثــرات العقليــة بقصــد التعاطــي‬\n‫واالســتعمال الشــخصي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬أنــي‬\n‫اعترفــت حيــث قــال لــي احملقــق ال تخــرج حتــى تعتــرف فاعترفــت ويف‬\n‫احلقيقــة هــي ليســت لــي‪ .‬ثــم ســألت املدعــى عليــه أيــن وجــدت احلبــوب ؟‬\n‫فأجــاب بقولــه‪ :‬وجــدت يف الســيارة التــي كنــت أقودهــا وهــي ليســت لــي‬\n‫وهــي ألحــد أقاربــي أخذتهــا منــه إلحضــار قطعــة غيــار لســيارتي‪ .‬هكذا‬\n‫أجــاب‪ .‬ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة ومــن ضمنهــا‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫التقريــر الكيميائــي الشــرعي رقــم (‪ )812‬لعــام ‪1433‬ه ـ املتضمــن‬\n      ‫إيجابيــة احلبــوب املضبوطــة ملــادة اإلمفيتامــن املنبهــة احملظــورة‪ .‬املــدون‬\n      ‫علــى لفــه رقــم (‪ )20‬ثــم جــرى االطــاع الســجل اجلنائــي الصــادر بحــق‬\n      ‫املدعــى عليــه املتضمــن عــدم وجــود ســوابق مســجلة بحقــه حتــى تاريخــه‬\n      ‫ـاء علــى مــا ســلف مــن الدعــوى‬  ‫كمــا هــو مــدون علــى لفــه رقــم (‪ .)25‬فبنـ ً‬\n      ‫واإلجابــة وإلقــرار املدعــى عليــه حتقيقــا بحيازتــه حلبتــن ونصــف مــن‬\n      ‫احلبــوب احملظــورة وحيــث ذهــب الفقهــاء إلــى أن حقــوق اهلل تعالــى التــي‬\n      ‫ال تــدرأ بالشــبهة ال يقبــل فيهــا الرجــوع عــن اإلقــرار بــا خــاف والتعزيــر‬\n      ‫مــن احلقــوق التــي ال تــدرأ بالشــبهة بــل يثبــت معهــا فــا يقبــل فيــه الرجــوع‬\n      ‫عــن اإلقــرار‪ (.‬ينظــر‪ :‬املغنــي ( ‪ ، )95/5‬حاشــية رد احملتــار ( ‪) )60/4‬‬\n      ‫وحيــث أقــر املدعــى عليــه لــدى هيئــة التحقيــق واالدعــاء العــام بطوعــه‬\n      ‫ـاء علــى مــا تقــدم من التقرير الكيميائي الشــرعي وملا جاء‬           ‫واختيــاره وبنـ ً‬\n      ‫ـدي إدانــة املدعــى عليــه مبــا اســند إليــه وهــو‬\n                                                        ‫يف أوراق املعاملــة فقــد ثبــت لـ ّ‬\n      ‫حيــازة حبتــن ونصــف احلبــه مــن حبــوب اإلمفيتامــن املنبهــة واحملظــورة‬\n      ‫ـاء علــى املــادة رقــم (‪ )56،41‬مــن نظــام مكافحــة‬       ‫لقصــد التعاطــي وبنـ َ‬\n      ‫املخــدرات واملؤثــرات العقليــة قــررت تعزيــره علــى ذلــك مبــا يلي‪ :‬أ)ســجنه‬\n      ‫ـداء مــن تاريــخ توقيفــه بهــذه القضيــة‪ .‬ب) منعــه مــن‬ ‫ملــدة ســتة أشــهر ابتـ ً‬\n      ‫الســفر ملــدة ســنتني خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميــة‬\n      ‫ســجنه‪ .‬هــذا مــا ظهــر لــي وبــه حكمــت‪ .‬وبعرضــه علــى املدعــي العــام‬\n      ‫لــم يقنــع بــه وطلــب متييــزه بــدون الئحــة اعتراضيــة وبعرضــه علــى املدعــى‬\n      ‫عليــه لــم يقنــع بــه وطلــب متييــزه بالئحــة اعتراضيــة فجرى تســليمه نســخة‬\n      ‫مــن القــرار الشــرعي إلبــداء معارضتــه عليــه يف مــدة أقصاهــا ثالثــون‬\n      ‫يومــا مــن هــذا اليــوم األربعــاء املوافــق ‪1433/12/29‬ه ـ وأفهمتــه أنــه إن‬\n\n\n‫‪161‬‬\n\f‫تأخــر عــن ذلــك ســقط حقــه يف االعتــراض وســترفع املعاملــة حملكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة ففهــم ذلــك ‪ ،‬وعليــه جــرى التوقيــع‬\n‫مت قفــل اجللســة يف متــام الســاعة احلاديــة عشــرة والنصــف مــن هــذا اليــوم‬\n‫األربعــاء املوافــق ‪1433/12/29‬ه ـ واهلل املوفــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا‬\n‫اليــوم الثالثــاء ‪1434/2/12‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر‬\n‫وحيــث أن املدعــى عليــه لــم يتقــدم بالئحتــه االعتراضيــة حتــى اآلن لــذا‬\n‫فقــد ســقط حقــه يف االعتــراض وقــررت التهميــش علــى الضبــط والقرار‬\n‫وقــررت بعــث املعاملــة حملكمــة االســتئناف إلجــراء الزمهــا وقفلــت‬\n‫اجللســة الســاعة احلاديــة عشــرة وعشــر دقائــق واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/2/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األربعــاء املوافــق ‪1434/2/20‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الواحــدة وحيــث إن املدعــى عليــه قــد‬\n‫تقــدم بالئحتــه االعتراضيــة واملكونــة مــن ورقــة واحــدة واملقيــدة يف‬\n‫هــذه احملكمــة برقــم ‪ 34214084‬يف ‪1434/1/25‬ه ـ وباالطــاع عليــه‬\n‫لــم أجــد مــا يؤثــر علــى مــا حكمــت بــه ولــم يتــم االنتبــاه إلــى ذلــك إال‬\n‫عنــد تصديــر املعاملــة فعليــه قــد رجعــت عمــا قررتــه مــن ســقوط حــق‬\n‫املدعــى عليــه باالعتــراض وقــررت رفــع كامــل أوراق املعاملــة حملكمــة‬\n‫االســتئناف إلجــراء الزمهــا واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                    ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/20‬هــ‪.‬‬\n‫احلمــد اهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫املختصــة بتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n\n\n                                                                                       ‫‪162‬‬\n\f      ‫مبنطقــة حائــل برقــم ‪ 332124240‬يف تاريــخ ‪1434/02/23‬ه ـ واملقيــد‬\n      ‫لدينــا برقــم ‪ 34459218‬يف تاريــخ ‪1434/02/24‬ه ـ املرفــق بهــا القــرار‬\n      ‫الشــرعي الصــادر مــن صاحــب الفضيلــة الشــيخ‪ ..../‬القاضــي باحملكمة‬\n      ‫اجلزائيــة مبنطقــة حائــل برقــم ‪ 33482733‬يف تاريــخ ‪1433/12/29‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ...../‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪ .....‬بشــأن حيــازة مخــدرات وقــد تضمــن القــرار حكــم صاحــب‬\n      ‫الفضيلــة وفقــه اهلل علــى املدعــى عليــه علــى النحــو املفصــل يف القــرار‬\n      ‫املرفــق‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة والالئحــة‬\n      ‫االعتراضية‪،‬جــرت املصادقــة علــى ماحكــم بــه فضيلتــه بالقــرار‬\n      ‫املشــار إليــه‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                     ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪163‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":158,"source_page_end":163,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa1993fbabbf593d1ec40b364cda6e2b9114f882e010534ea8cf7181d989c030","normalized_text_hash":"a12f00a613dcd9edc5aecac16248e310c5652be076d9eab65df4e0fcda3eee47","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p158-33482733"},{"id":"3c1280cb-43a0-51bf-a27d-5d8ae61a513c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -رجوع عن اإلقرار بالتعاطي -درء احلدود بالشبهات -تعزير للتهمة القوية -عدم ثبوت إدانة بالتستر -نزول عن احلد األدنى للعقوبة -التعزير .","document_number":"34260118","case_number":"33513449","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/07","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -رجوع عن اإلقرار بالتعاطي -درء احلدود بالشبهات -تعزير للتهمة القوية -عدم ثبوت إدانة بالتستر -نزول عن احلد األدنى للعقوبة -التعزير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34260118:‬تاريخه‪1433/08/07 :‬هـ‬\n                   ‫رقم الدعوى ‪33513449:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34282927‬تاريخه‪1434/07/30:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه وتســتر علــى‬\n ‫مصــدره‪ -‬رجــوع عــن اإلقــرار بالتعاطــي‪ -‬درء احلــدود بالشــبهات‪ -‬تعزيــر‬\n ‫للتهمــة القويــة‪ -‬عــدم ثبــوت إدانــة بالتســتر‪ -‬نــزول عــن احلــد األدنــى‬\n                                                        ‫للعقوبــة ‪ -‬التعزيــر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬جاء يف املغني (‪« :)95/5‬وال يقبل رجوع املقر عن إقراره‪ ..‬إلخ»‪.‬‬\n ‫‪ -2‬املــادة (‪ )41‬و (‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيازتــه احلشــيش املخــدر بقصد‬\n ‫التعاطــي وتعاطيــه لــه وتســتره علــى مصــدر مــا ضبــط معــه‪ ،‬واحلكــم‬\n ‫عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة‬\n ‫املخــدرات واملؤثــرات العقليــة وعقوبــة تعزيريــة علــى التســتر حيــث إنــه مت‬\n ‫تفتيــش ســيارة املدعــى عليــه بعــد االشــتباه بــه فعثــر فيهــا علــى حشــيش‬\n ‫مخــدر وأثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫ملــادة احلشــيش املخــدر‪ -‬كمــا اعتــرف حتقيق ـ ًا باســتعمال احلشــيش‬\n ‫املخــدر‪ ،‬أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام مــن احليــازة‬\n\n                                                                                         ‫‪164‬‬\n\f      ‫ورجــع عــن اعترافــه باســتعمال احلشــيش املخــدر كمــا أنكــر التســتر‬\n      ‫علــى مصــدر مــا ضبــط معــه‪ ،‬وملــا كان مــن املقــرر شــرع ًا أن الرجــوع‬\n      ‫عــن اإلقــرار شــبهة يــدرأ بهــا احلــد حيــث إن املدعــى عليــه أبــدى التوبــة‬\n      ‫والنــدم وال يوجــد لــه ســوابق والكميــة احملــازة قليلــة فقضــت احملكمــة‬\n      ‫بإدانــة املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد االســتعمال‪ ،‬كمــا‬\n      ‫قضــت بــدرء حــد املســكر عنــه وعــدم ثبــوت تســتره علــى مصــدر املخــدر‬\n      ‫وقــررت ســجنه ملــدة ثالثــة أشــهر ومنعــه مــن الســفر خــارج اململكــة‬\n      ‫ملــدة ســنتني وجلــده ســبعني جلــدة علــى دفعتــن متســاويتني لقــاء إقــراره‬\n      ‫حتقيق ـ ًا باســتعمال احلشــيش املخدر‪،‬وقنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض املدعــي العــام عليــه وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                         ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر‬\n      ‫برقــم ‪ 33513449‬وتاريــخ ‪1433/08/07‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 331494414‬وتاريــخ ‪1433/08/07‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n      ‫‪1434/07/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 :00‬وفيهــا قــدم املدعــي‬\n      ‫العــام ‪ ........‬الئحــة دعــوى عامــه ضد‪........‬ســعودي اجلنســية مبوجــب‬\n      ‫ا فيهــا حيــث انه باالطــاع على محضر‬       ‫الســجل املدنــي رقــم (‪ )........‬قائـ ً‬\n      ‫القبــض املعــد بتاريــخ ‪1433/6/14‬ه ـ مــن قبــل دوريــات أمــن الطــرق‬\n      ‫بطريــق الدمــام الريــاض الســريع تبــن انــه مت القبــض علــى املدعــى عليــه‬\n\n‫‪165‬‬\n\f‫بعــد اســتيقافهم ظهــرت عليــه عالمــات االرتبــاك الشــديد‪ ،‬وبتفتيــش‬\n‫ســيارته ضبطــت قطعــة تــزن (‪ )4‬أربعــة جرامــات يشــتبه ان تكــون مــن‬\n‫احلشــيش املخــدر ‪ ،‬وســيجارة تــزن (‪ )0,6‬جاهــزة لالســتخدام يشــتبه ان‬\n‫تكــون مــن احلشــيش املخــدر وقــد اثبــت القريــر الكيمــاوي الشــرعي‬\n‫رقــم (‪ )........‬ايجابيــة القطعــة املضبوطــة ملــادة احلشــيش املخــدر املــدرج‬\n‫يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة ‪ ،‬وايجابيــة الســيجارة امللفوفــة يدويــا غيــر مدخنــة وبــدون فلتــر‬\n‫ملــادة احلشــيش املخــدر املــدرج يف اجلــدول (‪ )1‬فئــة (أ) مــن ذات النظــام‬\n‫وباســتجواب املدعــى عليــه‪ /‬اعتــرف بشــراء مــا مت ضبطــه بحوزتــه‬\n‫مببلــغ (‪ )100‬ريــال مــن شــخص ال يعرفــه لقصــد االســتعمال الشــخصي‬\n‫وانتهــى التحقيــق إلــى توجيــه االتهــام ل‪........‬بحيــازة قطعــة تــزن (‪)4‬‬\n‫جرامــات مــن احلشــيش املخــدر وســيجارة ملفوفــة يدويــا تــزن (‪)0,6‬‬\n‫ســتة أعشــار اجلــرام مــن احلشــيش املخــدر لقصــد االســتعمال الشــخصي‬\n‫وتعاطيــه لنوعــه وتســتره علــى مصــدر املخــدرات وذلــك لألدلــة والقرائــن‬\n‫التالية‪-1:‬اعترافــه مبــا أشــير إليــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن‬\n‫دفتــر االســتدالل املرفــق لفــة رقــم (‪ ، )5‬والصفحــة رقــم (‪ )1‬مــن دفتــر‬\n‫التحقيــق املرفقــة لفــة رمــق (‪ -2 )12‬محضــر القبــض املرفــق لفــة رقــم‬\n‫(‪ -3 )26‬التقريــر الكيمــاوي الشــرعي املرفــق لفــة رقــم (‪ )26‬وبالبحــث‬\n‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائية مســجلة وحيث‬\n‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب اآلتــي‪ :‬أو ًال إثبــات إدانتــه مبــا‬\n‫أســند إليــه وفق ـ ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واحلكــم عليــه مبــا يلــي‪ -1:‬العقوبــة الــواردة يف الفقــرة رقــم‬\n\n\n                                                                                         ‫‪166‬‬\n\f      ‫(‪ )1‬مــن املــادة (‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر خــارج اململكــة‬\n      ‫بعــد تنفيــذ محكوميتــه اســتنادا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن ذات‬\n      ‫النظــام ثانيـ ًا احلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره لتســتره‬\n      ‫علــى مصــدر املخــدرات هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى‬\n      ‫أجــاب بقولــه مــا جــاء يف الدعــوى مــن حيازتــي قطعــة حشــيش مخــدر‬\n      ‫وســيجارة ملفوفــة حتتــوي علــى احلشــيش املخــدر بقصــد االســتعمال هــذا‬\n      ‫صحيــح ومــا جــاء يف الدعــوى مــن تســتري علــى مصــدر احلشــيش املخــدر‬\n      ‫واســتعمالي احلشــيش املخــدر فهــذا غيــر صحيــح وقــد مت القبــض علــي‬\n      ‫يف تاريــخ ‪1433/6/14‬ه ـ مــن قبــل أمــن الطــرق علــى طريــق الريــاض‬\n      ‫الدمــام عندمــا كنــت أقــود ســيارتي نــوع بــي أم وقــد وجــد رجــال األمــن‬\n      ‫داخــل ســيارتي قطعــة حشــيش مخــدر تــزن أربعــة جرامات (‪ )4‬وســيجارة‬\n      ‫ملفوفــة حتتــوي علــى احلشــيش املخــدر تــزن ســتة مــن العشــرة مــن اجلــرام‬\n      ‫(‪ )0.6‬وهمــا تعــودان لــي بقصــد االســتعمال وقــد اشــتريتهما مــن شــخص‬\n      ‫باكســتاني داخــل محطــة قبــل نقطــة التفتيــش التــي قبــض علــي فيهــا‬\n      ‫بعشــر دقائــق تقريبـ ًا وقــد أفــدت رجــال األمــن بذلــك عنــد القبــض علــي‬\n      ‫وعرضــت عليهــم أن أذهــب معهــم إلــى نفــس احملطــة حتــى أرشــدهم‬\n      ‫علــى ذلــك الشــخص لكنهــم رفضــوا ولــم يســبق لــي أن اســتعملت‬\n      ‫احلشــيش املخــدر وأنــا نــادم علــى فعلــي تائــب إلــى اهلل تعالــى هكــذا‬\n      ‫أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال بينتــي مــا ذكــرت‬\n      ‫فجــرى الرجــوع إلــى الصفحــة رقم(‪)2‬مــن ملــف التحقيــق املرفــق لفــه‬\n      ‫رقــم(‪ )5‬وتضمنــت ضبــط إفــادة املدعــى عليــه ويف ســؤال لــه منــذ متــى‬\n      ‫تســتعمل احلشــيش املخــدر فأجــاب بقولــه منــذ ســتة أشــهر تقريب ـ ًا ويف‬\n      ‫ســؤال آخــر متــى آخــر مــرة اســتعملت احلشــيش املخــدر فأجــاب بقولــه‬\n\n\n‫‪167‬‬\n\f‫منــذ شــهر تقريب ـ ًا ويف ســؤال ثالــث مــن أيــن حتصــل علــى احلشــيش‬\n‫املخــدر فأجــاب بقولــه مــن أشــخاص أجانــب مــن اجلنســية الباكســتانية‬\n‫علــى طريــق الدمــام وبعــرض هــذه اإلفــادات علــى املدعــى عليــه قــال‬\n‫أمــا اســتعمالي احلشــيش املخــدر فغيــر صحيــح وقــد أخبــرت احملقــق يف‬\n‫مكافحــة املخــدرات بأنــي ال اســتعمل احلشــيش املخــدر فأخبرنــي بعــدم‬\n‫خروجــي مــن الســجن حتــى اعتــرف بذلــك فوافقــت علــى االقــرار مبــا‬\n‫يريــده وأقريــت باســتخدام احلشــيش املخــدر منــذ ســتة أشــهر وأن آخــر‬\n‫مــرة اســتخدمت فيهــا احلشــيش املخــدر كانــت قبــل شــهر وكان ذلــك‬\n‫بطوعــي واختيــاري لكــن بعــد أن أخبرنــي احملقــق بأنــي لــن أخــرج مــن‬\n‫التوقيــف حتــى اعتــرف بذلــك وإال فــإن احلقيقــة هــي أنــي لــم اســتعمل‬\n‫احلشــيش املخــدر يف الســابق نهائي ـ ًا وأمــا بخصــوص مصــدر احلشــيش‬\n‫املخــدر فقــد أخبرتهــم بــأن احلشــيش املخــدر اشــتريته مــن شــخص‬\n‫باكســتاني داخــل محطــة علــى طريــق الريــاض الدمــام قبــل نقطــة‬\n‫التفتيــش بعشــر دقائــق تقريبـ ًا وعرضــت عليهــم أن أذهــب معهــم لنفــس‬\n‫احملطــة كــي أرشــدهم علــى البائــع لكنهــم رفضــوا هكــذا قــرر بعــد‬\n‫ذلــك جــرى الرجــوع إلــى الصفحــة رقــم (‪)1‬مــن ملــف التحقيــق املرفــق‬\n‫لفــه (‪)13‬وتضمنــت ضبــط إفــادة املدعــى عليــه مــن قبــل احملقــق يف‬\n‫هيئــة التحقيــق واالدعــاء العــام وقــد أنكــر املدعــى عليــه اســتعماله مــن‬\n‫الكميــة املضبوطــة ويف ســؤال لــه مــا هــي املعلومــات املتوفــرة لديــك عــن‬\n‫مصــدر احلشــيش فأجــاب املدعــى عليــه بقولــه ال تتوفــر لــدي معلومــات‬\n‫وأول مــرة اشــتري منــه كمــا أفــاد بأنــه باكســتاني اجلنســية وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قــال نعــم لــم يســبق لــي أن اســتعملت احلشــيش‬\n‫املخــدر وأمــا الشــخص الــذي اشــتري منــه فهــو باكســتاني اجلنســية وأما‬\n\n\n                                                                                   ‫‪168‬‬\n\f      ‫جوابــي بأنــه ال تتوفــر لــدي معلومــات بعــد أن ســألني احملقــق عــن مصــدر‬\n      ‫احلشــيش فأنــا أقصــد بأنــه ال يوجــد لــدي معلومــات عمــن يقومــون ببيــع‬\n      ‫احلشــيش املخــدر وأنــا ال زلــت مســتعد للداللــة علــى احملطــة التــي قابلــت‬\n      ‫فيهــا الباكســتاني واشــتريت منــه احلشــيش املخــدر والداللــة علــى‬\n      ‫الشــخص نفســه يف حــال تواجــده هكــذا قــرر بعــد ذلــك جــرى الرجــوع‬\n      ‫إلــى الصفحــة األولــى مــن ملــف التحقيــق املرفــق لفــه رقــم (‪ )5‬وتضمنــت‬\n      ‫محضــر التحريــز وجــاء فيــه وزن املضبوطــات وهــو كمــا ذكــر املدعــي‬\n      ‫العــام يف دعــواه كمــا جــرى الرجــوع إلــى اللفــة رقــم (‪ )27‬وتضمنــت‬\n      ‫التقريــر الكيمــاوي الشــرعي وهــو كمــا ذكــر املدعــي العــام يف دعــواه‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬    ‫فبنـ ً‬\n      ‫بحيازتــه قطعــة احلشــيش املخــدر وســيجارة احلشــيش املخــدر بقصــد‬\n      ‫االســتعمال وحيــث أنكــر املدعــى عليــه اســتعمال احلشــيش املخــدر وملــا‬\n      ‫جــاء يف افادتــه حتقيق ـ ًا باســتعمال احلشــيش املخــدر وحيــث قــرر بأنــه‬\n      ‫أفــاد بتلــك اإلفــادة بطوعــه واختيــاره وحيــث إن رجــوع املدعــى عليــه عــن‬\n      ‫هــذا االقــرار شــبهة يــدرأ بهــا احلــد قــال ابــن قدامــه رحمــه اهلل تعالــى يف‬\n      ‫املغنــي (‪(()95/5‬وال يقبــل رجــوع املقــر عــن اقــراره إال فيمــا كان حــد ًا‬\n      ‫هلل تعالــى يــدرأ بالشــبهات ويحتــاط إلســقاطه))وحيث أنكــر املدعــى‬\n      ‫عليــه تســتره علــى مصــدر احلشــيش املخــدر املضبــوط بحوزتــه وال يوجــد‬\n      ‫يف إفادتــه حتقيقـ ًا مــا يثبــت رفضــه عــن اإلفصــاح عــن مصــدر احلشــيش‬\n      ‫املخــدر بــل إنــه قــد ذكــر جنســية البائــع واملــكان الــذي اشــترى فيــه‬\n      ‫املضبوطــات وأبــدى اســتعداده للداللــة علــى املــكان واإلرشــاد علــى‬\n      ‫البائــع يف حــال تواجــده يف نفــس املــكان وحيــث أبــدى املدعــى عليــه‬\n      ‫ندمــه وتوبتــه وال ســوابق لــه والكميــة املضبوطــة بحوزتــه قليلــة وملــا جــاء‬\n\n\n‫‪169‬‬\n\f‫يف املــواد احلاديــة واألربعــن والسادســة واخلمســن والســتني مــن نظــام‬\n‫مكافحــة املخــدرات لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي حيــازة‬\n‫املدعــى عليــه قطعــة حشــيش مخــدر تــزن (‪)4‬أربــع جرامــات وســيجارة‬\n‫حتتــوي علــى احلشــيش املخــدر تزن(‪)0.6‬ســتة مــن العشــرة مــن اجلــرام‬\n‫بقصــد االســتعمال وقــررت تعزيــره لقــاء ذلــك بســجنه مــدة ثالثــة أشــهر‬\n‫اعتبــار ًا مــن تاريــخ إيقافــه ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني‬\n‫بعــد تنفيــذ عقوبــة الســجن عليــه ثاني ـ ًا درء حــد املســكر عــن املدعــى‬\n‫عليــه وتعزيــره بجلــده ســبعني جلــده علــى دفعتــن متســاويتني بينهمــا مــدة‬\n‫ال تقــل عــن عشــرة أيــام لقــاء اقــراره حتقيقـ ًا باســتعمال احلشــيش املخــدر‬\n‫ثالث ـ ًا عــدم ثبــوت دعــوى املدعــي العــام مــن تســتر املدعــى عليــه علــى‬\n‫مصــدر املخــدرات وبعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي‬\n‫العــام مكتفي ـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة‬\n                         ‫احلاديــة عشــر وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 331494414‬وتاريــخ ‪1434/07/09‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34/1684164‬وتاريــخ ‪1434/7/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .....‬املســجل برقــم ‪34260118‬‬\n‫وتاريــخ ‪1434/07/04‬ه ـ اخلــاص بدعــوى ‪ /‬املدعــي العام ضد ‪ /‬املدعى‬\n‫عليــه يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/07/29‬ه ـ‬\n                                                                                        ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":164,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"37fd0c864d15f9817443ca6aa6768e46dde7da31d8152b22ef647325326adc96","normalized_text_hash":"e7f83f58fc2c48662c7ffb7ec1d328e8e7d6bb7b7bbaf539a9dbe3f4e01f6e59","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p164-34260118"},{"id":"b9afc9c5-a16c-53df-939b-9134dcf7b852","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -تستر على مصدره -حد املسكر -هروب من رجال األمن -إقرار -إدانة -عقوبة بحدها األعلى -التعزير باجللد والسجن واملنع من السفر -تغليط العقوبة لوجود سوابق.","document_number":"33399240","case_number":"33535027","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/19","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -تستر على مصدره -حد املسكر -هروب من رجال األمن -إقرار -إدانة -عقوبة بحدها األعلى -التعزير باجللد والسجن واملنع من السفر -تغليط العقوبة لوجود سوابق.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33399240:‬تاريخه‪1434/08/19:‬هـ‬\n                         ‫رقم الدعوى‪33535027:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3420097‬تاريخه‪1434/01/24:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬تســتر علــى‬\n      ‫مصــدره ‪ -‬حــد املســكر ‪ -‬هــروب مــن رجــال األمــن‪ -‬إقــرار‪ -‬إدانــة‪ -‬عقوبــة‬\n      ‫بحدهــا األعلــى ‪ -‬التعزيــر باجللــد والســجن واملنــع مــن الســفر‪ -‬تغليط‬\n                                                          ‫العقوبــة لوجــود ســوابق‪.‬‬\n\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي وهربــه مــن الفرقــة القابضــة وتســتره علــى مصــدر مــا‬\n      ‫ضبــط معــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبق ـ ًا‬\n      ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبعقوبــة تعزيريــة بحقــه‬\n      ‫لقــاء باقــي التهــم وتشــديد العقوبــة عليــه لكثــرة ســوابقه وحيــث إنــه‬\n      ‫قــد مت اســتيقاف الســيارة التــي يقودهــا بالقــوة بعــد هربــه مــن دوريــات‬\n      ‫األمــن فقــام بالهــروب علــى قدميــه حتــى مت ضبطــه‪ ،‬وبتفتيــش الســيارة‬\n      ‫عثــر فيهــا علــى قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر وأثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش‬\n\n‫‪171‬‬\n\f‫املخــدر‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‬\n‫كمــا أقــر بتعاطــي احلشــيش املخــدر‪ ،‬فقضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مــا نســب إليــه وقــررت ســجنه ملــدة ســنتني ومنعــه مــن‬\n‫الســفر خــارج اململكــة ملــدة ســنتني وجلــده ثمانــن جلــدة دفعــة واحــدة‬\n‫حــد املســكر علن ـ ًا وجلــده مائــة وعشــرين جلــدة مفرقــة لباقــي التهــم‪،‬‬\n‫عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪ ،‬وقــررت محكمــة‬\n                          ‫االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33535027‬وتاريــخ ‪1433/08/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم وتاريــخ ‪1433/08/19‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n‫‪1433/08/27‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 :30‬وفيهــا حضــر املدعي‬\n‫العــام وقــدم الئحــة دعــوى عامه نصهــا كالتالي أدعي على ‪ : .....‬اجلنس‪:‬‬\n‫ذكــر اجلنســية‪ :‬ســعودي الديانــة‪ :‬مســلم اللغــة‪ :‬العربيــة تاريــخ امليــاد‪:‬‬\n‫‪1399/12/01‬ه ـ مــكان امليــاد‪ ........ :‬العمــر وقــت اجلرميــة‪ 34 :‬نــوع‬\n‫الهوية‪ :‬السجل املدني رقــم الهويــة‪ :‬تاريــخ اإلصــدار‪1408/05/19 :‬ه ـ‬\n‫جهــة اإلصــدار‪ :‬أحــوال جــازان املهنــة‪ :‬احلالــة االجتماعيــة‪ :‬أعــزب مــكان‬\n‫اإلقامــة‪ :‬الريــاض ‪ -‬حــي ‪ ........‬الشــارع‪........ :‬رقــم املنــزل‪ ........:‬هاتــف‬\n‫املنــزل‪ ........ :‬الهاتــف احملمــول‪ ........ :‬جهــة اإليقــاف‪ :‬شــعبة ســجن امللــز‬\n‫تاريخ القبض‪1433/7/29 :‬هـ حالة املتهم‪ :‬موقوف تاريــخ اإلفــراج‪:‬‬\n‫ال يوجــد االتهــام‪ :‬حيــازة مــواد مخــدرة بقصــد التعاطــي أو االســتعمال‬\n\n                                                                                        ‫‪172‬‬\n\f      ‫الســوابق‪ :‬رقــم احلكــم‪ 8/227 :‬تاريخــه‪1426/06/17 :‬ه ـ مصــدره‪:‬‬\n      ‫م الريــاض اجلرميــة‪ :‬حيــازة واســتعمال مخــدرات ‪ -‬ترويــج املخــدرات‪.‬‬\n      ‫العقوبــة‪75 :‬جلــده ‪ +‬ســجن ‪ 5‬أشــهر ‪ +‬غرامــه ألــف ريــال ومنعــه مــن‬\n      ‫السفر سنتني رقم احلكم‪ 6/28 :‬تاريخه ‪1430/01/15 :‬هـ مص ــدره‪:‬‬\n      ‫احملكمــة اجلزئيــة مبكــة اجلرميــة‪ :‬حيــازة واســتعمال مخــدرات‪ .‬العقوبــة‪:‬‬\n      ‫جلــده ‪ 80‬جلــدة وســجنه ملــدة ‪ 5‬اشــهر مــن توقيفــه ومنعــه مــن الســفر‬\n      ‫ملــدة ســنتني رقــم احلكــم‪/391 :‬د‪/‬ج‪ 9/‬تاريخــه‪1430/06/15 :‬ه ـ‬\n      ‫مصــدره‪ :‬الدائــرة اجلزائيــة التاســعة مبكــة اجلرميــة‪ :‬تزويــر وثائــق‬\n      ‫رســمية‪ .‬العقوبــة‪ :‬ســجنه ســنة مــن توقيفــه وتغرميــه ‪ 1000‬ريــال‪.‬‬\n      ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده حيث أنه بتاريخ‬\n      ‫‪1433/7/29‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق دوريــات‬\n      ‫األمــن مبدينــة الريــاض أثنــاء قيامهــا بعملهــا بحــي ‪........‬حيــث شــاهدت‬\n      ‫ســيارة مــن نــوع ( ‪ )....‬حتمــل لوحــة رقــم (‪ )....‬بهــا صدمــة يف مقدمــة‬\n      ‫الســيارة وعنــد محاولــة اســتيقافه قــام بالهــرب وســار بالســيارة بســرعة‬\n      ‫جنونيــة فجــرى متابعتــه حتــى مت اســتيقاف الســيارة بالقــوة فقــام بالهــرب‬\n      ‫علــى قدميــه حتــى مت ضبطــه والســيطرة عليــه وبتفتيــش الســيارة عثــر يف‬\n      ‫املقعــد األمامــي األميــن علــى قطعــة تــزن (‪ )9,5‬تســعة جرامــات وخمســة‬\n      ‫أعشــار اجلــرام يشــتبه بهــا أن تكــون مــن احلشــيش املخــدر‪ .‬وبســماع‬\n      ‫أقوالــه أقــر بحيازتــه ملــا ضبــط بقصــد التعاطــي ولــم يــدل مبعلومــات عــن‬\n      ‫مصــدر مــا ضبــط‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n      ‫املرفــق رقــم ‪........‬لعــام ‪1433‬ه ـ إيجابيــة عينــة القطعــة املضبوطــة ملــادة‬\n      ‫احلشــيش وهــو مــن املــواد احملظــورة املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ)‬\n\n\n‫‪173‬‬\n\f‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وقــد اســفرت‬\n‫اجــراءات التحقيــق عــن توجيــه االتهــام الــى ‪ ........‬بحيــازة قطعــة مــن‬\n‫احلشــيش املخــدر تــزن (‪ )9,5‬تســعة جرامــات وخمســة أعشــار اجلــرام‬\n‫بقصــد التعاطــي املجــرم علــى ذلــك مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وهربــه مــن الفرقــة القابضة وتســتره على‬\n‫مصــدر مــا ضبــط املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪-1 :‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنوه عنه‬\n‫ا علــى الصفحــة رقــم ( ‪ ) 2‬مــن ملــف إجــراءات االســتدالل‬        ‫املــدون تفصيـ ً‬\n‫املرفــق لفــة رقــم ( ‪ -2 .) 5‬مــا تضمنــه محضــر القبــض املنــوه عنــه املرفــق‬\n‫لفــة رقــم ( ‪ -3 .) 1‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه‬\n‫عنــه املرفــق لفــة رقــم ( ‪ .) 11‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n‫إليــه ‪ ،‬واحلكــم عليــه باآلتــي‪ -1 :‬بعقوبــة تعزيريــة بحقــه وفق ـ ًا للفقــرة‬\n‫(األولــى) مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة لقــاء مــا ُأســند إليــه ‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة‬\n‫بعــد انتهــاء تنفيــذ عقوبــة ســجنه وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪)56‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -3 .‬بعقوبــة تعزيريــة‬\n‫بحقــه لقــاء هربــه مــن الفرقــة القابضــة و تســتره علــى مصــدر مــا ضبــط‪.‬‬\n‫‪4‬ـ تشــديد العقوبــة عليــه لقــاء كثــرة ســوابقه اســتناد ًا لبرقيــة صاحــب‬\n‫الســمو امللكــي نائــب وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ‬\n‫‪1429/8/23‬ه ـ هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه عمــا جــاء يف‬\n‫دعــوى املدعــي العــام أجــاب بقولــه‪ :‬مــا ذكــره املدعــي العــام صحيــح‬\n\n\n                                                                                        ‫‪174‬‬\n\f      ‫فقــد عثــر بالســيارة نــوع ‪ ....‬التــي كنــت أقودهــا علــى قطعــة حشــيش‬\n      ‫تــزن تســعة جرامــات وخمســة أعشــار اجلــرام عائــده لــي بقصــد التعاطــي‬\n      ‫وقــد تعاطيــت احلشــيش قبــل يومــن مــن القبــض علــي وعنــد طلــب الفرقــة‬\n      ‫القابضــة منــه الوقــوف لــم اقــف ومت اســتيقاف الســيارة التــي أقودهــا‬\n      ‫ثــم هربــت علــى قدمــي وقبــض علــي ويوجــد علــي ثــاث ســوابق منهــا‬\n      ‫ســابقتي اســتعمال حشــيش ونــادم وتائــب وســوف أتــزوج قريبــا هكــذا‬\n      ‫أجــاب فســالته عــن مصــدر مــا ضبــط معــه وقــال إننــي اشــتريتها مــن‬\n      ‫شــخص يف حــي العــود غيــر ســعودي ال اعــرف اســمه وباالطــاع علــى‬\n      ‫املعاملــة وجــدت باللفــة (‪ )11‬صــورة تقريــر صــوره مصدقــه طبــق األصــل‬\n      ‫للتقريــر الكيميائــي رقــم ‪/44/2/8026‬ك يف ‪1433/8/5‬ه ـ مضمونــه‬\n      ‫بالتحليــل الكيميائــي ثبــت لدينــا مــا يلــي‪ :‬املرســل عبــاره عــن قطعــه‬\n      ‫ســمراء تــزن نصــف اجلــرام ثبــت إيجابيهــا ملــادة احلشــيش‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه املدعــي‬\n      ‫العــام يف دعــواه وملــا تضمنــه التقريــر الكيميائــي املنــوه عنــه أعــاه وملــا‬\n      ‫جــاء يف الئحــة الدعــوى واعتــراف املدعــى عليــه بوجــود ثــاث ســوابق‬\n      ‫بحقــه منهــا اثنتــان يف حيــازة واســتعمال مخــدرات وحيــث لــم تردعــه‬\n      ‫العقوبــات الســابقة لــذا حكمــت علــى املدعــى عليــه مبــا يلــي‪ :‬ثبــت لــدي‬\n      ‫ادانــة املدعــى عليــه بحيــازة قطعــة حشــيش تــزن (‪ )9.5‬تســعة جرامــات‬\n      ‫وخمســة اعشــار اجلــرام بقصــد التعاطــي ويعــزر لذلــك بســجنه ســنتني‬\n      ‫اعتبــارا مــن تاريــخ توقيفــه وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن‬\n      ‫نظــام مكافحــة املخــدرات ومنعــه مــن الســفر الــى خــارج اململكــة‬\n      ‫ملــدة ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة ســجنه اعــاه وفقــا للفقــرة‬\n      ‫االولــى مــن املــادة (‪ )56‬مــن ذات النظــام كمــا ثبــت لــدي ادانتــه بتعاطــي‬\n\n\n‫‪175‬‬\n\f‫احلشــيش ويحــد بجلــده ثمانــن جلــده دفعــة واحــده حــد املســكر علنــا‬\n‫وثبــت لــدي ادانتــه بهروبــه مــن الفرقــة القابضــة وتســتره علــى مصــدر‬\n‫مــا ضبــط بحوزتــه ويعــزر بجلــده مائــه وعشــرين جلــده مفرقــه علــى‬\n‫ثــاث دفعــات متســاوية بــن الدفعــة واالخــرى عشــرة ايــام تنفــذ الدفعــة‬\n‫االولــى مــن هــذا اجللــد بعــد عشــرة ايــام مــن تنفيــذ حــد املســكر وبتــاوة‬\n‫احلكــم لــم يقنــع بــه املدعــى عليــه وســوف يتــم طلبــه يــوم االربعــاء املوافــق‬\n‫‪1433/9/6‬ه ـ لتســليمه نســخة احلكــم مــن اجــل تقــدمي الئحــة اعتــراض‬\n‫عليــه وقــرر املدعــي العــام اعتراضــه وانــه يكتفــي بالئحــة الدعــوى عــن‬\n‫الئحــة االعتــراض وعليــه حصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫حــرر يف ‪1433/8/27‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مرفقــا بهــا قــرار احملكمــة ومضمونــه املصادقــة علــى احلكــم‬\n‫باالكثريــة ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه اجمعــن ‪.‬‬\n\n\n\n\n                                                                                          ‫‪176‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":171,"source_page_end":176,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f9318a75fb1b6a2c8d580f246c606ec0f71e02f29143e279e5c3301b08b9504d","normalized_text_hash":"fa50952678c43c20879c7c49f895c5b54b0b0ec3a4c195606cce43cc5c25e391","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p171-33399240"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5745ce18-e511-56b7-8be1-1c7604731bcc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج وتعاطيها والشروع يف ترويجها -إقرار -حد املسكر -التعزير للتهمة القوية - تعزير بالسجن واجللد .","document_number":"33381189","case_number":"33468056","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافق على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/15","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج وتعاطيها والشروع يف ترويجها -إقرار -حد املسكر -التعزير للتهمة القوية - تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33381189:‬تاريخه‪1433/07/15:‬هـ‬\n                         ‫رقم الدعوى‪33468056:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3419394‬تاريخه‪1434/01/21:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصد الترويــج وتعاطيها‬\n      ‫والشــروع يف ترويجهــا‪ -‬إقــرار‪ -‬حــد املســكر‪ -‬التعزيــر للتهمــة القويــة ‪-‬‬\n                                                         ‫تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫املــواد (‪ )38‬و(‪ )53‬و(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                               ‫العقليــة‪.‬‬\n\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهمــا تتضمــن طلــب إثبــات إدانــة‬\n      ‫األول بحيــازة احلشــيش وحبــوب اإلمفيتامــن بقصــد الترويــج والتعاطــي‬\n      ‫والشــروع يف ترويــج احلبــوب وبيعهــا وتعاطيــه لهمــا ســابقا وإدانــة الثانــي‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي ‪ ،‬واحلكــم عليهمــا بعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر وعلــى األول أيض ـ ًا بالغرامــة واملصــادرة‬\n      ‫طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت االتفــاق مــع‬\n      ‫األول علــى شــراء حبــوب محظــورة وبعــد أن تقابــل مــع املشــتري وقبــل‬\n      ‫تســليمه الكميــة الحــظ الفرقــة فرمــى احلبــوب وهــرب لداخــل املنــزل‬\n      ‫فتــم اللحــاق بــه وعثــر معــه علــى اجلــوال الــذي مت التنســيق معــه مــن‬\n      ‫خاللــه ومبلــغ مالــي‪ ،‬وعثــر بغرفــة النــوم علــى كميــة أخــرى مــن احلبــوب‬\n\n‫‪123‬‬\n\f‫احملظــورة وقطعــة مــن احلشــيش ومبلــغ مالــي؛ وعنــد النــزول مــن املنــزل‬\n‫لوحــظ الثانــي يقــف عنــد بــاب غرفــة احلــارس وعنــد مشــاهدته للفرقــة‬\n‫هــرب لداخلهــا فتــم القبــض عليــه وعثــر يف املرحــاض علــى قطعــة مــن‬\n‫احلشــيش‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n‫لإلمفيتامــن واحلشــيش املخــدر‪ ،‬أقــر األول أمــام احملكمــة بجميــع مــا‬\n‫أســنده إليــه املدعــي العــام وأنكــر الثانــي جميــع التهــم املوجهــة لــه‪،‬‬\n‫للمدعــى عليــه الثانــي ســابقة مخــدرات‪ ،‬قضــت احملكمــة بإدانــة األول‬\n‫بجميــع مــا نســب إليــه وقــررت ســجنه ملــدة ثمــان ســنوات وجلــده خمســن‬\n‫جلــدة مكــررة علــى عشــرين مــرة وتغرميــه مبلغ خمســة آالف ريــال ومنعه‬\n‫مــن الســفر خــارج اململكــة ملــدة ثمــان ســنوات ومصــادرة املضبوطــات‬\n‫وجلــده ثمانــن جلــدة علنــا حــد املســكر كمــا قضــت بصــرف النظــر‬\n‫عــن طلــب املدعــي العــام احلكــم علــى الثانــي مبوجــب نظــام املخــدرات‬\n‫وقــررت ســجنه ملــدة ثالثــة أشــهر وجلــده خمســن جلــدة مكــررة علــى‬\n‫خمــس مــرات لقــاء شــبهة احليــازة‪ ،‬قنــع املدعــى عليهمــا باحلكم وعارض‬\n‫املدعــي العــام عليــه‪ -‬قــررت محكمــة االســتئناف املوافــق علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33468056‬‬\n‫وتاريــخ ‪1433/07/15‬ه ـ املقيــدة باحملكمة برقــم ‪ 331320550‬وتاريخ‬\n‫‪1433/07/14‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/08/07‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 :45‬وفيهــا حضــر املدعــي العــام ‪ ........‬ســعودي‬\n\n                                                                                   ‫‪124‬‬\n\f      ‫اجلنســية حامــل بطاقــة أحــوال رقــم (‪ )........‬واملكلــف بالعمــل لدينــا‬\n      ‫مبوجــب خطــاب ذو الرقــم (ه ـ م‪ )368/6/2‬وتاريــخ ‪1430/21/29‬ه ـ‬\n      ‫وقــرر دعــواه قائــا بصفتــي مدعيــا عامــا بدائــرة االدعاء العــام مبحافظة‬\n      ‫جــدة ادعــى علــى كل مــن ‪ )28( ........ )1‬عام ـاً‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )....‬املهنــة‪ /‬متســبب ‪ ،‬موقــوف بســجون‬\n      ‫محافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم (ه ـ م‪ )33045/5/2‬يف‬\n      ‫‪1432/5/16‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬ه ـ ‪ )32( ........ )2‬عامـاً‪ ،‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ، )...‬املهنــة‪ /‬متســبب ‪ ،‬موقــوف بســجون محافظــة جــدة‬\n      ‫مبوجب أمر متديد التوقيف رقم (هـ م‪ )33046/5/2‬يف ‪1432/5/16‬هـ‬\n      ‫اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس‬\n      ‫مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )4/5/1/79425‬وتاريــخ‬\n      ‫ـاء علــى اإلخباريــة‬‫‪1432/12/20‬ه ـ فإنــه بتاريــخ ‪1433/5/14‬ه ـ بنـ ً‬\n      ‫الــواردة ملكافحــة املخــدرات بجــدة عــن ترويــج األول للحبــوب احملظــورة‬\n      ‫عليــه مت االتصــال علــى جوالــه رقــم (‪ )...‬واالتفــاق معــه علــى شــراء كمية‬\n      ‫مــن احلبــوب احملظــورة ‪،‬وباالنتقــال ملنزلــه خــرج األول وتقابل مــع املتعاون‬\n      ‫والفــرد وقبــل تســليم الكميــة الحــظ الفرقــة فرمــى الكميــة وهــي‬\n      ‫(‪ )396‬ثالثمائــة وســتة وتســعون حبــة بيضــاء اللــون‪ ،‬وهــرب لداخــل‬\n      ‫املنــزل فتــم اللحــاق بــه والقبــض عليــه وعثــر معــه علــى جــوال يحمــل‬\n      ‫الرقــم املنــوه عنــه ومبلــغ (‪ )91‬واحــد وتســعني ريــا ًال ‪ ،‬وعثــر بغرفــة النــوم‬\n      ‫علــى أكيــاس بهــا (‪ )644‬ســتمائة وأربعــة وأربعــن حبــة بيضــاء اللــون‬\n      ‫وقطعــة ســوداء اللــون تــزن (‪ )130‬مائــة وثالثــن جرام ـ ًا وعثــر علــى‬\n      ‫بندقيــة (شــوزن) مــع ذخيــرة حيــة ومبلــغ (‪ )26700‬ســتة وعشــرين ألــف‬\n\n\n‫‪125‬‬\n\f‫وســبعمائة ريــال ؛ وعنــد النــزول مــن املنــزل لوحــظ الثانــي يقــف عنــد بــاب‬\n‫غرفــة احلــارس وعنــد مشــاهدته للفرقــة هــرب لداخلهــا فتــم القبــض‬\n‫عليــه واتضــح انبعــاث رائحــة احلشــيش املخــدر منهــا وعثــر يف املرحــاض‬\n‫علــى قطعــة ســوداء اللــون تــزن (‪ )19.5‬تســعة عشــر جرم ًا ونصــف اجلرام‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/1800‬ك ش م) لعــام‬\n‫‪1433‬ه ـ احتــواء عينتــي احلبــوب املضبوطــة علــى مــادة اإلمفيتامــن‬\n‫املؤثــرة عقلي ـ ًا وايجابيــة عينتــي القطعتــن املضبوطــة ملــادة احلشــيش‬\n‫املخــدر واملدرجــة بجــداول املخــدرات رقــم (‪ )2 ، 1‬الفئتــن (أ ‪ ،‬ب)‬\n‫امللحقــن بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وباســتجواب‬\n‫املدعــى عليــه األول اعتــرف أنــه اتصــل بــه شــخص يعرفــه وطلــب منــه‬\n‫شــدين مــن احلبــوب احملظــورة مببلــغ (‪ )3200‬ثالثــة آالف ومائتــي ريــال‬\n‫للشــد الواحــد وعنــد مقابلتــه شــاهد الفرقــة فهــرب ورمــى احلبــوب فتــم‬\n‫القبــض عليــه ‪ ،‬وأقــر بحيــازة احلبــوب احملظــورة للترويــج واحلشــيش‬\n‫املخــدر للتعاطــي التــي ضبطــت باملنــزل ‪ ،‬وأنــه يبيــع احلبــوب احملظــورة‬\n‫ويتعاطاهــا مــن الســابق وأنــه تعاطــى مــن احلشــيش املخــدر املضبــوط‬\n‫ولنوعــه ســابق ًا ‪ ،‬وأن جــزء مــن املبلــغ املضبــوط حصــل عليــه مــن بيــع‬\n‫احلبــوب احملظــورة ؛ كمــا أقــر بحيــازة كميــة احلشــيش املخــدر التــي‬\n‫ضبطــت يف غرفــة احلــارس بقصــد التعاطــي‪ .‬وباســتجواب املدعــى عليــه‬\n‫الثانــي أقــر بضبــط احلشــيش املخــدر مبرحــاض الغرفــة التــي كان بهــا‬\n‫وأنــه عائــد لــأول‪( .‬مت فــرز أوراق بشــأن الســاح والذخائــر احليــة التــي‬\n‫مت ضبطهــا لبعثهــا إلــى جهــة االختصــاص)‪ .‬وقــد انتهــى التحقيــق إلــى‬\n‫اتهــام األول بحيــازة (‪ )1040‬ألــف وأربعــن حبــة حتتــوي علــى مــادة‬\n‫اإلمفيتامــن املؤثــرة عقلي ـ ًا بقصــد الترويــج والشــروع يف ترويــج (‪)396‬‬\n\n\n                                                                                      ‫‪126‬‬\n\f      ‫ثالثمائــة وســتة وتســعني حبــة منهــا وبيعــه وتعاطيــه لنوعيهمــا ســابق ًا‬\n      ‫وحيــازة (‪ )130‬مائــة وثالثــن جرام ـ ًا مــن مــادة احلشــيش املخــدر بقصــد‬\n      ‫الترويــج والتعاطــي وتعاطيــه منهــا ولنوعهــا ســابق ًا ؛ واتهــام األول والثانــي‬\n      ‫بحيازتهما (‪ )19.5‬تســعة عشــر جرام ًا ونصف اجلرام من مادة احلشــيش‬\n      ‫املخــدر بقصــد التعاطــي ‪،‬لألدلــة والقرائــن املذكــورة بالئحــة الدعــوى‬\n      ‫وباالطــاع علــى صحيفــة احلالــة اجلنائيــة لــم يعثــر علــى ســوابق لــأول‬\n      ‫وعثــر للثانــي علــى ســابقة حيــازة املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا مــن األفعــال‬\n      ‫احملرمــة شــرع ًا واملجرمــة نظام ـ ًا طبق ـ ًا للمــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ واملعاقــب عليهــا اســتناد ًا للمــواد (‪-38‬‬\n      ‫‪ )59-41‬مــع مراعــاة مــا ورد باملــادة (‪ )62‬مــن ذات النظــام ‪ ،‬أطلــب‪/‬‬\n      ‫إثبات ما أســند إليهما واحلكم عليهما بالعقوبات األصلية والتكميلية‬\n      ‫التاليــة‪ )1 :‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إلــى األول مــع‬\n      ‫تشــديد العقوبــة عليــه اســتنادا للفقــرة (‪ )1‬والفقــرة (‪ )2‬احلالــة (ج) مــن‬\n      ‫املــادة (‪ )38‬مــن النظــام املشــار إليــه بالســجن لقــاء مــا أســند إلــى الثانــي‬\n      ‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n      ‫املشــار إليــه مصــادرة جهــاز اجلــوال العائــد لــأول مــن نــوع (‪ )........‬ذي‬\n      ‫الرقــم املصنعــي (‪ )........‬املســتخدم يف ارتــكاب اجلرميــة واملبلــغ املالــي‬\n      ‫املضبــوط معــه وقــدره (‪ )26791‬ســتة وعشــرون ألفـ ًا وســبعمائة وواحــد‬\n      ‫وتســعون ريــا ًال لترجــح حصولــه عليــه مــن بيــع احلبــوب احملظــورة اســتناد ًا‬\n      ‫للفقرتــن (‪ )2-1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة مــع إلغــاء اخلدمــة عــن شــريحة اجلــوال وعــدم صرفهــا‬\n\n\n‫‪127‬‬\n\f‫اســتناد ًا إلــى تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n‫(‪ )9798‬يف ‪1428/2/10-9‬هــ‪ .‬منعهمــا مــن الســفر خلــارج البــاد بعــد‬\n‫انتهــاء تنفيــذ عقوبتيهمــا وفق ـ ًا للفقــرة (‪ )1‬مــن النظــام املشــار اليــه‬\n‫هكــذا أدعــى وجــرى إحضــار املدعــى عليهمــا وبســؤال املدعــى عليــه‬\n‫ا كل مــا ذكــره املدعــي العــام‬      ‫األول ‪ ...... /‬عــن الدعــوى أجــاب قائ ـ ً‬\n‫ا فقــد قبــض علــى بعــد التنســيق معــي جوالــي نــوع‬    ‫صحيــح جملــة وتفصيـ ً‬\n‫‪ ........‬ذي الرقــم (‪ )...‬علــى قيامــي ببيــع احلبــوب احملظــورة وقبــل متــام‬\n‫عمليــة االســتالم والتســليم قبــض علــي وكل مــا ورد يف الدعــوى مــن‬\n‫احلشــيش املخــدر واحلبــوب احملتويــة علــى اإلمفيتامــن فهــي صحيحــة‬\n‫طبقـ ًا ملــا قــرره املدعــي العــام وتعــود لــي لوحــدي وليــس ألخــي عالقــة بهــا‬\n‫البتــة وكان بحوزتــي مبلــغ مالــي قــدره (‪ )26791‬ســتة وعشــرون ألــف‬\n‫وســبعمائة وواحــد وتســعون ريــا ًال عائــد لــي حتصلــت عليــه مــن بيــع‬\n‫املخــدرات ومــا ذكــره املدعــي العــام مــن أننــي تعاطيــت لنوعــه ســابقا‬\n‫فذلــك صحيــح أيضــا وبحمــد اهلل ال توجــد علـ ّـي أيــة ســوابق مســجلة وقــد‬\n‫أقدمــت علــى ذلــك وأنــا مســلم وأعلــم بــان ذلــك محــرم شــرع ًا ومجــرم‬\n‫نظام ـ ًا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى هــذا الفعــل وأتعهــد‬\n‫بعــدم العــودة لفعلــي هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي‪........‬‬\n‫ا كل مــا ذكــره املدعــي العــام ضــدي فغيــر‬        ‫عــن الدعــوى أجــاب قائ ـ ً‬\n‫ا فقــد قبــض علــى ولــم يكــن بحوزتــي شــيء مــن‬       ‫صحيــح جملــة وتفصيـ ً‬\n‫احملظــورات البتــة وكنــت متواجــد ًا مبنــزل والــدي محــل واقعــة القبــض‬\n‫ولــم اعلــم عــن وجــود هــذه احملظــورات البتــة وأنــا اســكن لوحــدي مــع‬\n‫زوجتــي هكــذا أجــاب وبســؤالي للمدعــي العــام عــن بينتــه علــى الدعــوى‬\n‫ا ليــس لــدي ســوى مــا يف املعاملــة واطلــب الرجــوع لهــا‬      ‫وأجــاب قائ ـ ً‬\n\n\n                                                                                         ‫‪128‬‬\n\f      ‫هكــذا أجــاب هــذا وقــد اطلعــت علــى أقــوال املدعــى عليــه الثانــي لفــة‬\n      ‫رقــم (‪ )23‬ومحــل الشــاهد مــا نصــه (س‪ /‬أنــت متهــم باالشــتراك يف‬\n      ‫الشــروع يف البيــع (‪ )396‬حبــة محظــورة وحيــازة (‪ )644‬حبــة مــن نوعهــا‬\n      ‫و(‪ )130‬جــرام مــن احلشــيش املخــدر وســاح شــون نــاري و(‪ )14‬طلقــة‬\n      ‫حيــة وحيــازة (‪ )5،19‬جــرام مــن احلشــيش املخــدر فمــا قولــك ؟ ج‪ /‬غيــر‬\n      ‫صحيــح) أ‪.‬ه ـ كمــا جــرى اطالعــي علــى التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪1800‬ك ش م ) املرفــق باملعاملــة لفــة رقــم ( ‪ )32‬ويتضمــن إيجابيــة‬\n      ‫احتــواء العينــة (ج‪،‬د) للحشــيش املخــدر والعينــة (أ‪،‬ب) لإلمفيتامــن‬\n      ‫املؤثــر عقليـ ًا كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليهما‬\n      ‫املرفقــة باملعاملــة باللفــة رقــم (‪ )34‬املتضمنــة عــدم وجــود أيــة ســوابق‬\n      ‫مســجلة علــى املدعــى عليــه األول ووجــود ســابقة واحــدة يف حيــازة‬\n      ‫املخــدرات علــى الثانــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا‬\n      ‫قــرره الطرفــان وملــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه‬\n      ‫بعاليــة فلمــا ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه األول ‪ /‬املذكــور‬\n      ‫بعاليــه مبــا نســب إليــه مــن حيازتــه (‪ )1040‬ألــف وأربعــن حبــة حتتــوي‬\n      ‫علــى اإلمفيتامــن املؤثــر عقلي ـ ًا بقصــد الترويــج والشــروع يف ترويــج‬\n      ‫(‪ )396‬ثالثمائــة وســتة وتســعني حبــة منهــا وبيعــه وتعاطيــه لهمــا ســابق ًا‬\n      ‫وحيازتــه (‪ )130‬مائــة وثالثــون جرام ـ ًا مــن احلشــيش املخــدر لقصــد‬\n      ‫الترويــج والتعاطــي وتعاطيــه منهــا لنوعهــا ســابق ًا وحيازتــه (‪)19،5‬‬\n      ‫لتســعة عشــر جرام ـ ًا ونصــف اجلــرام مــن احلشــيش املخــدر لقصــد‬\n      ‫التعاطــي وثبــت لــدي حتصــل املدعــى عليــه األول للمبلــغ املالــي الــذي‬\n      ‫بحوزتــه وقــدره (‪ )26791‬ريــال مــن الترويــج وقيامــه بترويــج املخــدرات‬\n      ‫ســابق ًا ولــم يثبــت لــدي ادانــة املدعــى عليــه الثانــي‪ /‬مبــا نســب إليــه مــن‬\n\n\n‫‪129‬‬\n\f‫االشــتراك يف حيازتــه (‪ )19,5‬لتســعة عشــر جرام ـ ًا ونصــف اجلــرام مــن‬\n‫احلشــيش املخــدر لقصــد التعاطــي مــع توجيــه الشــبهة إليــه يف ذلــك وعليه‬\n‫فقــد قــررت صــرف النظــر عــن طلــب املدعــي العــام احلكــم علــى املدعــى‬\n‫عليــه الثانــي‪ /‬مبوجــب نظــام مكافحــة املخــدرات ونظــر لكبــر‬\n‫الكميــة وتنوعهــا ولعظيــم جــرم مــا قــام بــه املدعــى عليــه األول وملــا يف‬\n‫ترويجهــا مــن اإلفســاد يف األرض ونشــر لــه أوســاط املجتمــع ونظــر ًا ملــا‬\n‫أظهــره مــن التوبــة والنــدم ولعــدم الســوابق املســجلة عليــه وملــا قــرره‬\n‫الفقهــاء مــن أن للحاكــم املعاقبــة علــى الشــبهة ولتوجــه الشــبهة إلــى‬\n‫املدعــى عليــه الثانــي ‪ /‬نظــرا لوجــود الســابقة عليــه ووجــوده يف محــل‬\n‫الواقعــة عنــد القبــض فلمــا ســبق فقــد حكمــت علــى املدعــى عليهمــا‬\n‫مبــا يلــي‪ :‬أوالً‪ :‬يســجن املدعــى عليــه األول‪ /‬ملــدة ثمــان ســنوات يحتســب‬\n‫موقوفــا يف هــذه القضيــة ويجلد خمســن جلــدة مكررة‬       ‫ً‬       ‫منهــا مــا أمضــاه‬\n‫عليــه عشــرين مــرة بينهــن مــدة ال تقــل عــن خمســة أيــام ويدفــع غرامــة‬\n‫ماليــة قدرهــا خمســة أالف ريــال وفقــا للمــادة (‪ )38‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ثانيـاً‪ :‬مينــع املدعــى عليه األول ‪ /‬من الســفر‬\n‫خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميتــه ملــدة ثمــان ســنوات وفقــا‬\n‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه‪ .‬ثالثـاً‪ :‬مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه األول‪/‬‬\n‫‪ ........‬وشــريحته املســتخدمني يف عمليــة الترويــج وعــدم صرف الشــريحة‬\n‫لــه مــرة أخــرى لســوء اســتخدامه لهــا ومصــادرة املبلــغ املالــي الــذي‬\n‫بحوزتــه لتحصلــه عليــه مــن الترويــج للمخــدرات وقــدره (‪ )26791‬ســتة‬\n‫وعشــرون الفـ ًا وســبعمائة وواحــد وتســعون ريــا ًال وفقـ ًا للمــادة (‪ )53‬مــن‬\n‫نظــام مكافحــة املخــدرات املشــار إليــه ووفق ـ ًا لتعميــم ســمو وزيــر‬\n\n\n                                                                                         ‫‪130‬‬\n\f      ‫الداخليــة ذي الرقــم (‪ )9798‬وتاريــخ ‪1428/10-9‬ه ـ رابعـاً‪ :‬إقامــة حــد‬\n      ‫املســكر علــى املدعــى عليــه األول‪ .......... /‬وذلــك بجلــده ثمانــن جلــدة‬\n      ‫دفعــة واحــدة أمــام مــأ مــن النــاس لقــاء تعاطيــه احلشــيش املخــدر مــن‬\n      ‫الســابق خامس ـاً‪ /‬يســجن املدعــى عليــه الثانــي‪ /‬ملــدة ثــاث أشــهر‬\n      ‫يحتســب مــا أمضــاه موقوف ـ ًا يف هــذه القضيــة ويجلــد خمســن جلــدة‬\n      ‫مكــررة عليــه خمــس مــرات بينهــن مــدة ال تقــل عــن خمســة أيــام لقــاء‬\n      ‫شــبهة احليــازة وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n      ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n      ‫باحلضــور يف يــوم األحــد املوافق‪1433/8/11‬ه ـ الســتالم نســخة مــن‬\n      ‫قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يومــا اعتبــار ًا‬\n      ‫مــن التاريــخ املشــار إليــه فــان مضــت املــدة ولــم يقــدم اعتراضــه عليــه‬\n      ‫خاللهــا فــان حقــه يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا كمــا‬\n      ‫قــرر املدعــى عليــه قناعتــه بــه وجــرى النطــق باحلكــم يف يــوم األربعــاء‬\n      ‫املوافــق ‪1433/7 /30‬ه ـ الســاعة ‪ 9:30‬وعلــى ذلــك جــرى التوقيــع وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬ويف يــوم األحــد‬\n      ‫ـاء علــى انتهــاء مــدة‬\n                            ‫‪1433/10/15‬ه ـ الســاعة ‪ 08 :45‬فتحــت اجللســة بنـ ً‬\n      ‫االعتــراض علــى احلكــم حيــث جــرى إفهــام املدعــي العــام باســتالمه‬\n      ‫نســخة احلكــم بتاريــخ ‪1433/8/11‬ه ـ وأنــه ســوف حتتســب مهلــة‬\n      ‫الثالثــن يوم ـ ًا لالعتــراض اعتبــار ًا مــن تاريخــه وحيــث انتهــت املــدة‬\n      ‫املقــررة نظام ـ ًا ولــم يتقــدم املدعــي العــام باالســتالم ولــم يتقــدم بالئحــة‬\n      ‫اعتراضيــة لــذا فقــد قــررت رفــع احلكــم حملكمــة االســتئناف حســب‬\n      ‫املتبــع وحتــى ال يخفــى جــرى إثباتــه واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                                                 ‫محمد ‪.‬‬\n\n\n‫‪131‬‬\n\f‫احلمد هلل وحده وبعد ففي يوم الثالثاء ‪1433/12/21‬هـ وعند الســاعة‬\n‫‪ 08 :00‬فتحــت اجللســة بنــاء علــى عــود املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة وبرفقهــا قــرار املالحظــة ذو الرقــم ‪33466484‬‬\n‫وتاريــخ ‪1433/11/27‬ه ـ الصــادر مــن أصحــاب الفضيلــة قضــاة الدائــر‬\n‫اجلزائيــة األولــى واملتضمــن بعــد املقدمــة مــا نصــه (وبدراســة القــرار‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫ملالحظــة أنــه عنــد عــرض احلكــم علــى الطرفــن ذكــر فضيلتــه أن‬\n‫املدعــي العــام قــرر عــدم القناعــة واملدعــى عليــه القناعــة فهــل الــذي قــرر‬\n‫القناعــة املدعــى عليهمــا االثنــان أم أحدهمــا وال بــد مــن إيضــاح ذلــك‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫قاضــي اســتئناف اخلتــم والتوقيــع قاضــي اســتئناف ‪ ........‬اخلتــم والتوقيــع‬\n‫رئيــس اســتئناف ‪ ........‬اخلتــم والتوقيــع أ‪ .‬ه ـ نصــه وملــا ذكــره أصحــاب‬\n‫الفضيلــة نفعنــي اهلل بعلمهــم فإننــي أجيبهــم أن الــذي قــرر القناعــة‬\n‫باحلكــم كال املدعــى عليهمــا األول والثانــي وقــد جــرى تعديــل ذلــك‬\n‫علــى القــرار وضبطــه يف هــذه اجللســة وقــررت إعــادة املعاملــة حملكمــة‬\n‫االســتئناف وكان ختام هذه اجللســة الســاعة ‪ 08 :20‬وصلى اهلل وســلم‬\n                                                              ‫علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن النبــي بعــده ‪ ،‬وبعــد ‪ - :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة إلينــا مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة املســاعد مبحافظــة جــدة برقــم‬\n‫‪ 2194960/33‬وتاريــخ ‪ 1434/1/13‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫رقــم ‪ 33381189‬و تاريــخ ‪ 1433/8/17‬ه ـ الصــادر مــن فضيلــة الشــيخ‬\n\n\n                                                                                       ‫‪132‬‬\n\f      ‫‪ .......‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى‬\n      ‫املدعــي العــام ضــد ‪ .....‬املتهــم بقضيــة مخــدرات احملكــوم فيــه مبــا دون‬\n      ‫باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪133‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":123,"source_page_end":133,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cbb8584d2e0392b62c113f9d188d2f165b3cdaef6da5ca6b835b9ff83681abe0","normalized_text_hash":"1648d63631aeceeac9e19076246997d44fd563813c8184327179eff0eaa8f13b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p123-33381189"},{"id":"d02f9681-52e8-5d23-93f7-5c7cc9d9493c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قات بقصد الترويج والتعاطي -قات -حيازة حبوب اإلمفيتامن بقصد التعاطي -التستر على مصدر ما ضبط -إعداد املدعى عليه منزله لتعاطي القات -األصل أن ما كان يف بيت املرء من حوزته -مشروعية التعزير بالتهمة -التعزير بالسجن واجللد والغرامة واإلبعاد -تشديد العقوبة .","document_number":"3412610","case_number":"33475424","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/14","year":"1434","subject":"مخدرات -حيازة قات بقصد الترويج والتعاطي -قات -حيازة حبوب اإلمفيتامن بقصد التعاطي -التستر على مصدر ما ضبط -إعداد املدعى عليه منزله لتعاطي القات -األصل أن ما كان يف بيت املرء من حوزته -مشروعية التعزير بالتهمة -التعزير بالسجن واجللد والغرامة واإلبعاد -تشديد العقوبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3412610 :‬تاريخه‪1434/1/14 :‬هـ‬\n                   ‫رقم الدعوى‪33475424:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34315075‬تاريخه‪1434/09/08:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة قــات بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬حيــازة‬\n‫حبــوب اإلمفيتامــن بقصــد التعاطــي‪ -‬التســتر علــى مصــدر مــا ضبــط‬\n‫‪ -‬إعــداد املدعــى عليــه منزلــه لتعاطــي القــات ‪ -‬األصــل أن مــا كان‬\n‫يف بيــت املــرء مــن حوزتــه ‪ -‬مشــروعية التعزيــر بالتهمــة ‪ -‬التعزيــر‬\n           ‫بالســجن واجللــد والغرامــة واإلبعــاد ‪ -‬تشــديد العقوبــة ‪.‬‬\n\n\n\n‫‪ -1‬مشــروعية التعزيــر بالتهمــة ملــا رواه أبــو داود والترمــذي أن النبــي‬\n                        ‫ا يف تهمــة ‪.‬‬‫صلــى اهلل عليــه وســلم حبــس رج ـ ً‬\n                      ‫‪ -2‬القرار الوزاري رقم (‪ )2057‬يف ‪1404/5/26‬هـ ‪.‬‬\n                      ‫‪ -3‬القرار الوزاري رقم(‪ )3818‬يف ‪ 1410/9/28‬هـ ‪.‬‬\n             ‫‪ -4‬برقية وزير الداخلية رقم (‪ )13476‬يف ‪ 1433/2/23‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا رجــل ســعودي وامــرأة أجنبيــة‬\n‫‪،‬باتهــام األول بتســليم قــات بقصــد الترويــج واالجتــار وإعــداد منزلــه‬\n‫مكانـ ًا للتعاطــي وتســتره علــى مصــدر مــا ضبــط واتهــام املــرأة بحيــازة‬\n‫حبــوب اإلمفيتامــن بقصــد التعاطــي‪ ،‬وطلــب إثبــات مــا أســند إليهمــا‬\n‫وتعزيــر املدعــى عليهــا ‪ ،‬وفــق األنظمــة املعمــول بها‪،‬وتعزيرهمــا لقــاء‬\n\n                                                                                 ‫‪134‬‬\n\f      ‫التســتر ولقــاء إعــداد الثانــي منزلــه للتعاطــي ‪،‬ورد املبلــغ املرقــم‪ ،‬وإبعــاد‬\n      ‫املــرأة األجنبيــة بعــد انتهــاء تنفيــذ عقوبــة ســجنها ‪،‬حيــث مت القبــض‬\n      ‫عليهمــا مــن قبــل فرقــة مكافحــة املخدرات بعــد ورود بالغ بقيام املدعى‬\n      ‫عليهمــا بترويــج القــات‪ ،‬وأن صاحــب املنــزل جعلــه وكــرا الســتقبال‬\n      ‫املتعاطــن لنبــات القــات فتــم تزويــد املصــدر باملبلــغ املرقــم برفقــة أحــد‬\n      ‫أفــراد املكافحــة وبعــد دخولهمــا املنــزل تفــاوض املصــدر مــع املدعــى‬\n      ‫عليهمــا علــى شــراء القــات بقيمــة مائــة وخمســن ريــال فاســتعدت‬\n      ‫املدعــى عليهــا بذلــك ثــم قــام املدعــى عليــه بتســليم القــات وعنــد مداهمــة‬\n      ‫املنــزل مــن قبــل الفرقــة الذ بالفــرار مجموعــة مــن الرجــال والنســاء ومت‬\n      ‫القبــض علــى املدعــى عليهمــا وبتفتيــش املــرأة عثــر بشــنطتها علــى حبوب‬\n      ‫محظــورة ولــم يتــم العثــور علــى املــرأة التــي اســتلمت املبلــغ وأثبــت التقريــر‬\n      ‫الكيميائــي إيجابيــة العينتــن املضبوطتــن لنبــات القــات احملظــور‬\n      ‫وحبــوب اإلمفيتامــن احملظــورة‪ ،‬وصــادق املدعــى عليــه علــى القبــض‬\n      ‫عليــه يف منزلــه وهــو يتعاطــى القــات وأنكــر حيــازة القــات للترويــج‬\n      ‫‪،‬صادقــت املدعــى عليهــا علــى القبــض عليهــا وهــي يف منــزل املدعــى‬\n      ‫عليــه وحيازتهــا للحبــوب وأنكــرت أنهــا حبــوب اإلمفيتامــن‪ ،‬بينــة‬\n      ‫املدعــي العــام بخصــوص تســليم القــات هــي شــهادة أحــد أعضــاء الفرقــة‬\n      ‫القابضــة مبشــاهدة التســليم دون اآلخــر‪ ،‬ومبــا أن األصــل مــا كان يف‬\n      ‫بيــت املــرء مــن حوزتــه‪ ،‬مت إثبــات إدانــة املدعــى عليــه بتعاطــي القــات‬\n      ‫وحيازتــه بقصــد التعاطــي والترويــج وجعــل منزلــه وكــر ًا لشــراء القــات‬\n      ‫وتعاطيــه وعــدم ثبــوت إدانتــه بتســليم القــات ‪،‬وتوجــه الشــبهة لتســليمه‬\n      ‫بشــهادة أحــد الشــهود‪ ،‬وعــدم إثبــات إدانــة املدعــى عليهــا بحيــازة حبــوب‬\n      ‫اإلمفيتامــن ‪،‬وتوجــه الشــبهة بإقرارهــا بحيــازة حبــوب أخرى‪،‬حكمــت‬\n\n\n‫‪135‬‬\n\f‫احملكمــة بتعزيــر املدعــى عليــه بالســجن ثالثــن شــهر ًا وجلــده ثالثمائــة‬\n‫وخمســن جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة أمــام‬\n‫النــاس‪ ،‬تغرميــه ألــف ريــال ‪ ،‬وتعزيــر املدعــى عليهــا بالســجن خمســة‬\n‫أشــهر وإبعادهــا عــن البــاد بعــد تنفيــذ احلكــم وصــرف النظــر عــن‬\n‫املطالبــة بــرد املبلــغ والتعزيــر للتســتر لعــدم وجــود موجبــه‪ ،‬وقنــع املدعــى‬\n‫عليهمــا واعتــرض املدعــي العــام بــدون الئحــة‪ ،‬ومت تصديــق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض‬\n‫‪ ....‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n‫بالرياض برقم ‪ 33475424‬وتاريخ ‪1433/07/20‬هـ املقيدة باحملكمة‬\n‫برقــم ‪ 331360332‬وتاريــخ ‪1433/07/20‬ه ـ ففــي يــوم االثنــن املوافــق‬\n‫‪1433/07/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 15‬وفيهــا قــدم املدعــي‬\n‫العام ‪ .....‬دعواه ضد ‪........ /1‬اجلنس‪ :‬أنثى اجلنســية‪ :‬الصومالية الديانة‪:‬‬\n‫مسلمة نــوع الهويــة‪ :‬بطاقــة بديلــة جهــة اإلصــدار‪ :‬الســجن‪ ،‬مــكان‬\n‫اإلقامــة‪ :‬الريــاض تاريــخ القبــض‪1433/6/11 :‬ه ـ حالــة املتهــم‪ :‬موقــوف‬\n‫تاريــخ القبــض‪1433/6/11 :‬ه ـ االتهــام‪ :‬حيــازة مؤثــرات عقليــة بقصــد‬\n‫التعاطــي أو االســتعمال الشــخصي ‪........../2‬اجلنــس‪ :‬ذكــر اجلنســية‪:‬‬\n‫ســعودي الســجل املدنــي رقــم الهويــة‪ ........ :‬احلالــة االجتماعيــة‪ :‬متــزوج‬\n‫مــكان اإلقامــة‪ :‬الريــاض جهــة اإليقــاف‪ :‬شــعبة ســجن امللــز بتاريــخ‬\n‫‪1433/6/11‬ه ـ قبــض علــى املتهمــن املذكوريــن مــن قبــل إحــدى فــرق‬\n‫شــعبة املكافحــة والبحــث والتحــري بعــد ورود إخباريــة عــن وجــود منزل‬\n\n                                                                                         ‫‪136‬‬\n\f      ‫يف حــي ‪ ....‬يتواجــد بــه رجــل وامــرأة ميتهنــان ترويــج القــات احملظــور وان‬\n      ‫صاحــب املنــزل جعلــه وكــر ًا الســتقبال مجموعــة مــن الرجــال والنســاء‬\n      ‫لتعاطــي القــات احملظــور عليــه مت اتخــاذ اإلجــراءات الالزمــة حيــث مت‬\n      ‫تزويــد املصــدر باملبلــغ املرقــم وقــدره (‪ )150‬مائة وخمســون ريا ًال وكلف‬\n      ‫احــد عناصــر الفرقــة ملرافقــة املصــدر ليكــون شــاهد ًا علــى عمليــة‬\n      ‫الترويــج بعدهــا توجــه املصــدر بعــد تفتيشــه بــكل دقــة ويرافقــه عنصــر‬\n      ‫املكافحــة املكلــف إلــى املنــزل وبعــد دخولهمــا تفــاوض املصــدر مــع‬\n      ‫املتهــم الثانــي واملــرأة محــل اإلخباريــة بحضــور عنصــر املكافحــة علــى‬\n      ‫شــراء حزمــة مــن القــات احملظــور بقيمــة (‪ )150‬ريــا ًال فاســتعدت املــرأة‬\n      ‫بذلــك بعدهــا قــام املتهــم الثانــي بتســليم املصــدر حزمــة يشــتبه أن تكون‬\n      ‫مــن نبــات القــات احملظــور بلــغ وزنهــا (‪ )110‬مائــة وعشــرة جرامــات وقــام‬\n      ‫املصــدر بتســليم املبلــغ املرقــم للمــرأة بعدهــا خــرج املصــدر وعنصــر‬\n      ‫املكافحــة وقــام عنصــر املكافحــة باالتصــال علــى قائــد الفرقــة وابلغــه‬\n      ‫بوجــود مجموعــة كبيــرة مــن الرجــال والنســاء داخــل املنــزل عندهــا مت‬\n      ‫االســتعانة بالدوريــات األمنيــة واصطحــاب املفتشــة النســائية وبعــد أخــذ‬\n      ‫األذن متــت مداهمــة املنــزل واثنــاء املداهمــة متكــن مجموعــة مــن الرجــال‬\n      ‫والنســاء مــن ارتــكاب الفــرار وذلــك عــن طريــق مخــارج مخصصــة لذلك‬\n      ‫وكذلــك عــن طريــق األســطح واجلــدران ومت القبــض علــى املتهــم الثانــي‬\n      ‫(محــل اإلخباريــة) ويف هــذه األثنــاء حــدث جتمهــر كبيــر جــد ًا خــارج‬\n      ‫املنــزل حيــث قامــوا بإطــاق صرخــات ورشــق رجــال األمــن باحلجــارة ممــا‬\n      ‫اســتدعاء إطــاق النــار طلقــات حتذيريــة يف الهــواء وبعــد الســيطرة علــى‬\n      ‫الوضــع مت القبــض علــى املتهمــة األولــى داخــل املنــزل وبتفتيــش حقيبتهــا‬\n      ‫عثــر بداخلهــا علــى عــدد (‪ )7‬بيضــاء اللــون يشــتبه ان تكــون مــن احلبــوب‬\n\n\n‫‪137‬‬\n\f‫احملظــور وبالبحــث عــن املــرأة التــي قامــت باســتالم املبلــغ املرقــم لــم يعثــر‬\n‫عليهــا ممــا يــدل علــى أنهــا الذت بالفــرار أثنــاء عمليــة املداهمــة وبتفتيــش‬\n‫املنــزل عثــر يف الصالــة بــه علــى (‪ )29‬تســعة وعشــرون حزمــة يشــتبه‬\n‫أن تكــون مــن نبــات القــات احملظــور بلــغ وزنهــا جميع ـ ًا (‪ )6.090‬ســتة‬\n‫كيلــوات وتســعون جرام ـاً‪ ،‬ولــم يعثــر علــى املبلــغ املرقــم ‪ -‬اإلجــراءات‬\n‫املتخــذة ‪ -1‬جــرى مخاطبــة مكافحــة املخــدرات بشــرق الريــاض إلحالــة‬\n‫مــا يتعلــق بإقامــة املتهمــة األولــى يف البــاد بطريقــة غيــر نظاميــة للجهــة‬\n        ‫املختصــة مبوجــب خطــاب الدائــرة رقــم ‪ .....‬بتاريــخ ‪1433/7/1‬هــ‪.‬‬\n‫‪ -2‬جــرى مخاطبــة الفرقــة القابضــة لإلفــادة عــن املتهمــة األولــى أن‬\n‫كان لهــا دور يف عمليــة الترويــج أو كميــة القــات املضبوطــة وحتديــد‬\n‫مــكان ضبطهــا مبوجــب خطــاب الدائــرة رقم‪.....‬بتاريــخ ‪1433/6/22‬هـ‬\n‫وخطــاب الدائــرة رقــم ‪1433/6/28.....‬ه ـ فوردنــا خطابهــم رقــم (‪).....‬‬\n‫بتاريــخ ‪1433/6/25‬ه ـ املتضمــن انــه لــم يتبــن للفرقــة أي دور للمتهمــة‬\n‫بعمليــة الترويــج أو كميــة القــات املضبــوط وانــه مت ضبطهــا مختبئــة‬\n                                    ‫حتــت الســرير بإحــدى غــرف النــوم باملنــزل ‪.‬‬\n‫‪-3‬وردت صحيفتــي ســوابق املتهمــن حيــث عثــر لألولــى علــى ســابقة‬\n                            ‫أعــداد وكــر للدعــارة مقرونــة بحيــازة املخــدرات‪.‬‬\n                                                                   ‫اإلجراءات املتخذة‪:‬‬\n‫‪ -1‬جــرى مخاطبــة مكافحــة املخــدرات بشــرق الريــاض إلحالــة مــا‬\n‫يتعلــق بإقامــة املتهمــة األولــى يف البــاد بطريقــة غيــر نظاميــة للجهــة‬\n    ‫املختصــة مبوجــب خطــاب الدائــرة رقــم ‪.....‬بتاريــخ ‪1433/7/1‬هــ‪.‬‬\n‫‪ -2‬جــرى مخاطبــة الفرقــة القابضــة لإلفــادة عــن املتهمــة األولى أن كان‬\n‫لهــا دور يف عمليــة الترويــج او كميــة القــات املضبوطــة وحتديــد مــكان‬\n\n\n                                                                                          ‫‪138‬‬\n\f      ‫ضبطهــا مبوجــب خطــاب الدائــرة رقــم‪ .....‬بتاريــخ ‪1433/6/22‬ه ـ‬\n      ‫وخطــاب الدائــرة رقــم ‪ .....‬بتاريــخ ‪ 1433/6/28‬ه ـ فوردنــا خطابهــم رقــم‬\n      ‫(‪ ).....‬بتاريــخ ‪1433/6/25‬ه ـ املتضمــن انــه لــم يتبــن للفرقــة أي دور‬\n      ‫للمتهمــة بعمليــة الترويــج أو كميــة القــات املضبــوط وانــه مت ضبطهــا‬\n                           ‫مختبئــة حتــت الســرير بإحــدى غــرف النــوم باملنــزل ‪.‬‬\n      ‫‪-3‬وردت صحيفتــي ســوابق املتهمــن حيــث عثــر لألولــى علــى ســابقة‬\n      ‫أعــداد وكــر للدعــارة مقرونــة بحيــازة املخــدرات‪ ،‬وعثــر للثانــي علــى‬\n      ‫ســبعة ســوابق اثنتــن منهــا ســرقة والثالثــة ســرقة كيابــل والرابعــة‬\n      ‫محاولــة ســكر واخلامســة شــرب املســكرات و اعتــداء و طعــن شــخص‬\n      ‫والسادســة ســرقة مســاكن والســابعة حيــازة قــات واســتعمال القــات‬\n      ‫ومخالفــة نظــام أمــن احلــدود وباســتجواب املتهــم الثانــي اقــر بتعاطيــه‬\n                                                      ‫القــات احملظــور مــن الســابق‪.‬‬\n      ‫وقــد اثبــت التقريــر الكيميائــي الشــرعي املرفق رقــم (‪ ).....‬لعام‪1433‬هـ‬\n      ‫إيجابيــة مســتخلص مــا مت ترويجــه ومــا مت ضبطــه للمــواد الفاعلــة يف‬\n      ‫نبــات القــات وهــو مــن املــواد املدرجــة باجلــدول (‪ )4‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة‪ ،‬واحتــواء احلبــوب املضبوطــة لإلمفيتامــن‬\n      ‫وهــو مــن املــواد املنبهــة املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وقــد أســفرت إجــراءات التحقيــق‬\n      ‫عــن توجيــه االتهــام للثانــي‪ ...../‬بتســليم مــا وزنــه (‪ )110‬مائــة وعشــرة‬\n      ‫جرامــات مــن نبــات القــات احملظــور بقصــد الترويــج واالجتــار وحيــازة‬\n      ‫مــا وزنــه (‪ )6.090‬ســتة كيلــوات وتســعون جرام ـ ًا مــن نبــات القــات‬\n      ‫احملظــور بقصــد الترويــج والتعاطــي وتعاطيــه للقــات احملظــور مــن‬\n\n\n‫‪139‬‬\n\f‫الســابق املعاقــب علــى ذلــك مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n‫لعــام ‪1374‬ه ـ واتهــام املتهمــة االولــى‪..... /‬بحيــازة (‪ )7‬ســبع حبــات مــن‬\n‫حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد التعاطــي املجــرم مبوجــب‬\n‫املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ واتهــام‬\n‫الثانــي بإعــداد منزلــه مكانـ ًا لتعاطــي القــات احملظــور وتســترهما علــى‬\n‫مصــدر مــا ضبــط املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن‬\n                                                                              ‫التالية ‪:‬‬\n‫ا علــى‬  ‫‪ -1‬مــا تضمنــه محضــر القبــض املنــوه عنــه املــدون تفصي ـ ً‬\n‫الصفحــات رقــم (‪ )11.12‬مــن ملــف إجــراءات االســتدالل املرفــق لفــة‬\n                                                                                  ‫(‪.)1‬‬\n                                     ‫‪ -2‬ما تضمنه خطاب الفرقة القابضة ‪.‬‬\n                                 ‫‪ -3‬ما تضمنه التقرير الكيميائي الشرعي‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكوريــن فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n          ‫ونظامـ ًا اطلــب إثبــات مــل اســند إليهمــا واحلكــم عليهمــا باالتــي ‪:‬‬\n‫‪-1‬بعقوبــة تعزيريــة بحــق املتهمــة األولــى وفق ـ ًا للفقــرة ( األولــى ) مــن‬\n‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا‬\n                                                                      ‫أســند إليهــا‪.‬‬\n    ‫‪-2‬بعقوبة تعزيرية بحق املتهم الثاني وفق ًا للقرار الوزاري املشار إليه‪.‬‬\n‫‪-3‬إلــزام املتهــم الثانــي بــرد املبلــغ املرقــم وقــدره (‪ )150‬مائــة وخمســون‬\n‫ري ــال اسـت ـن ــاد ًا لتـعـمـي ــم صـاح ــب الـسـمـ ــو الـملـك ــي النائــب الثانــي‬\n‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ‬\n                                                             ‫‪1428/10/23-22‬هـ‪.‬‬\n\n\n                                                                                          ‫‪140‬‬\n\f      ‫‪-4‬إبعــاد األولــى إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنها‬\n      ‫وعــدم الســماح لهــا بالعــودة إليهــا مــرة أخــرى وفقـ ًا للفقــرة (الثانيــة) مــن‬\n                ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫‪ -5‬بعقوبــة تعزيريــة بحــق الثانــي لقــاء إعــداد منزلــه مكان ـ ًا لتعاطــي‬\n          ‫القــات احملظــور وبحقهمــا لقــاء تســترهما علــى مصــدر مــا ضبــط‪.‬‬\n      ‫‪ -6‬تشــديد العقوبــة علــي املتهــم الثانــي لكثــرة ســوابقه اســتناد ًا لبرقيــة‬\n      ‫صاحــب الســمو امللكــي نائــب وزيــر الداخليــة رقــم (‪)93958/5/5/1‬‬\n                                                               ‫وتاريــخ ‪1429/8/23‬ه ـ ‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليهــا وهــي جتيــد اللغــة العربيــة أجابــت إن‬\n      ‫مــا ذكــره املدعــي العــام مــن القبــض علــي يف منــزل املدعــى عليه صحيح‬\n      ‫وســبب حضــوري ألجــل وضــع احلنــاء لنســاء يف املنــزل وكان معــي شــنطة‬\n      ‫صغيــرة فيهــا مبلــغ مالــي وحبــوب فيتامينــات ألننــي حامــل وليــس معــي‬\n      ‫إمفيتامــن وليــس لــي عالقــة بالقــات املوجــودة يف املنــزل والســابقة‬\n      ‫صحيحــة وأجــاب املدعــى عليــه قائــا إن مــا ذكــره املدعــي مــن القبــض‬\n      ‫علــي يف منزلــي صحيــح وكنــت أتعاطــى القــات املذكــور وعنــد دخــول‬\n      ‫الشــرطة هــرب الذيــن يف املنــزل ورمــوا بالقــات يف الصالــة وهــو الــذي‬\n      ‫مت ضبطــه وقــد اشــتروه مــن املدعــى عليهــا وزوج املدعــى عليــه أكبــر‬\n      ‫املروجــن للقــات وهــو ســجني يف ســجن ‪ ...‬وليــس لــي عالقــة بالقــات‬\n      ‫املوجــود يف الصالــة ولــم أســلم أحــدا قاتــا والســوابق التــي عليــه صحيحــة‬\n      ‫هكــذا أجــاب ولطلــب البينــة جــرى رفــع اجللســة وأجلــت ألقــرب موعــد‬\n      ‫وعليــه جــرى التوقيــع وأغلقــت اجللســة الســاعة ‪ 09 : 45‬وصلــى اهلل علــى‬\n             ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/07/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n\n\n‫‪141‬‬\n\f‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33475424‬وتاريــخ ‪1433/07/20‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331360332‬وتاريــخ ‪ 1433/07/20‬ه ـ ففــي يــوم‬\n‫االثنــن املوافق‪1433/08/12‬ه ـ افتتحــت اجللســة وفيهــا أحضــر املدعــي‬\n‫العــام بينتــه وهــو الشــاهد ‪.....‬حامــل الســجل املدنــي رقــم ‪.....‬وبســؤاله‬\n‫عمــا لديــه أجــاب إننــي أعمــل يف مكافحــة املخــدرات بالريــاض وعمــري‬\n‫ثمــان وعشــرون ســنة وأحمــل املؤهــل الثانوي وال تربطنــي عالقة باملدعى‬\n‫عليهــم وأشــهد أننــي كنــت ضمــن الفرقــة القابضــة علــى املدعــى عليهما‬\n‫وكانــا يف منــزل املدعــى عليــه ‪.....‬بحــي ‪.....‬واملنــزل فيــه رجــال كثيــر‬\n‫ونســاء وقــد متــت عمليــة االســتالم والتســليم حتــت مــرأى زميلــي ‪.....‬‬\n‫ولــم أشــاهدها وإمنــا كنــت ضمــن فرقــة القبــض بعــد عمليــة االســتالم‬\n‫والتســليم وقــد ســمعت املدعــى عليــه ‪.....‬يقــول إن املدعــى عليهــا ‪.....‬هــي‬\n‫التــي ســلمت القــات للمصــدر بينمــا ســمعت زميلــي ‪.....‬يقــول إنــه رأى هــو‬\n‫الــذي ســلم القــات للمصــدر وقــد رأيــت أثنــاء دخولــي املنــزل املذكــور‬\n‫تســع ًا وعشــرين حزمــة قــات وقــد هــرب مــن يف منــزل ولــم يقبــض إال‬\n‫علــى املدعــى عليهمــا هــذا مــا لــدي وبــه أشــهد وقــد عــدل مــن قبــل ‪.....‬‬\n‫وحلــن طلــب باقــي البينــة جــرى رفــع اجللســة وأجلــت ألقــرب موعــد وعليــه‬\n‫جــرى التوقيــع وأغلقــت اجللســة الســاعة احلاديــة عشــرة وعلــى ذلــك جــرى‬\n‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة بالريــاض‬\n‫ففــي يــوم االثنــن ‪ 1433/11/29‬ه ـ افتتحــت اجللســة التاســعة وفيهــا‬\n‫أحضــر املدعــي العــام بينتــه وهــو الشــاهد ‪.....‬حامــل الســجل املدنــي‬\n‫رقــم ‪ .....‬وبســؤاله عمــا لديــه أجــاب إننــي أعمــل يف مكافحــة املخــدرات‬\n\n\n                                                                                     ‫‪142‬‬\n\f      ‫بالريــاض وعمــري ســبع وعشــرون ســنة وأحمــل املؤهــل الثانــوي وال‬\n      ‫تربطنــي عالقــة باملدعــى عليهــم وأشــهد أننــي كنــت مرافق ـ ًا للمصــدر‬\n      ‫الــذي قــام بعمليــة الشــراء مــن املدعــى عليــه املدعــى عليــه الثانــي حيــث‬\n      ‫توقفنــا أمــام أحــد املنــازل بحــي ‪ .....‬وعندمــا دخلنــا املنــزل شــاهدنا‬\n      ‫بداخلــه رجــا ًال و نســاء كثيريــن واجتهــت أنــا واملصــدر للمدعــى عليــه‬\n      ‫‪ .....‬وبجانبــه إحــدى النســاء و أمامهــم كميــة مــن نبــات القــات احملظــور‬\n      ‫وطلــب املصــدر مــن املدعــى عليــه ‪ .....‬شــراء قــات مخــدر مببلــغ (‪)150‬‬\n      ‫مائــة و خمســن ريــا ًال فاســتعدت املــرأة التــي بجانــب املدعــى عليــه ‪.....‬‬\n      ‫بعدهــا قــام املدعــى عليــه بتســليم املصــدر علــى مــرأى منــي حزمــة يشــتبه‬\n      ‫أن تكــون مــن نبــات القــات املخــدر بلــغ وزنهــا (‪ )110‬جــرام و قــام‬\n      ‫املصــدر بتســليم املــرأة املبلــغ احلكومــي املرقــم و بعــد مداهمــة املنــزل‬\n      ‫لــم أمتكــن مــن معرفــة املــرأة التــي قامــت باســتالم املبلــغ و ذلــك بســبب‬\n      ‫وجــود عــدد كبيــر مــن النســاء مــن ذوي البشــرة الســمراء هــذا مــا لــدي‬\n      ‫و بــه أشــهد و عــدل مــن قبــل ‪.....‬يحمــل ســجل مدنــي رقــم ‪.....‬و ‪.....‬حامــل‬\n      ‫الســجل املدنــي رقــم ( ‪ ).....‬و كذلــك فــإن املزكــي ‪.....‬عـ ّـدل الشــاهد‬\n      ‫‪.....‬و إلحضــار املدعــى عليهمــا جــرى رفــع اجللســة وأجلــت ألقــرب موعــد‬\n      ‫وعليــه جــرى التوقيــع وأغلقــت اجللســة الســاعة التاســعة وعلــى ذلــك جــرى‬\n             ‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33475424‬وتاريــخ ‪1433/07/20‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331360332‬وتاريــخ ‪1433/07/20‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافق‪1434/01/07‬ه ـ افتتحــت اجللســة العاشــرة وفيهــا‬\n\n\n‫‪143‬‬\n\f‫حضــر املدعــى عليهمــا وبتــاوة شــهادة الشــاهد ‪.....‬وعرضــه علــى‬\n‫املدعــى عليهمــا أجابــا إن شــهادتهما غيــر صحيحــة والشــاهد ال نعرفــه‬\n‫هــذا وقــد جــرى حتديــد عــدة جلســات إلحضــار البينــة ولــم يحضــر‬\n‫املدعــي العــام إال شــاهدين ومــا هــو مــدون يف أوراق املعاملــة وبســؤال‬\n‫املدعــى عليهمــا عــن ســوابقهما أقــرا بهــا هــذا وقــد جــرى االطــاع علــى‬\n‫أقــوال املدعــى عليــه ‪.....‬لفــة ( ‪ ) 20‬املتضمــن قولــه أنــه طلــب املدعــى‬\n‫عليهــا يف منزلــه لشــراء نبــات القــات ودخــل معــه مجموعــة مــن الرجــال‬\n‫والنســاء ليشــتروا منهــا وأنــه اســتلم منهــا حزمــة قــات وكانــت املدعــى‬\n‫عليهــا تبيــع القــات علــى املجموعــة وأثنــاء ذلــك متــت املداهمــة والقبــض‬\n‫عليــه وعلــى املدعــى عليهــا ‪.....‬وأنــه وجــد يف منزلــه عــدد ‪ 29‬حزمــة قــات‬\n‫وزنهــا ســتة كيلــوات وتســعون جرامـ ًا وأنهــا للمدعــى عليهــا ‪.....‬وبعرضــه‬\n‫عليــه صــادق عليــه كمــا ألفيــت قــول املدعــى عليهــا ص ‪ 1‬لفــة ( ‪21‬‬\n‫) املتضمــن أن ســبب حضورهــا ملنــزل املدعــى عليــه عزميــة دعتهــا إليــه‬\n‫إحــدى صديقاتهــا واســمها ‪.....‬ثــم جــرى ســؤالها مــا ســبب حضــورك‬\n‫ملنــزل املدعــى عليــه ‪.....‬فقالــت ذهبــت أنــا مــع اثنتــن مــن صديقاتــي‬\n‫ألجــل عمــل حنــاء لنســاء يف منــزل املدعــى عليــه ‪.....‬فتــم القبــض علــي‬\n‫وهــرب اآلخــرون وكان املنــزل مليئـ ًا بالرجــال والنســاء فجــرى ســؤالها‬\n‫مــا اســم صديقتــك التــي دعتــك إلــى احلضــور فقالــت ‪.....‬وبعــرض قولهــا‬\n‫املذكــور يف محضــر التحقيــق قالــت الصحيــح مــا ذكــرت يف مجلــس‬\n‫احلكــم ثــم جــرى ســؤالها مــاذا كنــت حتملــن يف شــنطتك فقالــت‬\n‫فلــوس وحبــوب فيتامينــات ألنــي حامــل فجــرى ســؤالها أنــك ذكــرت يف‬\n‫أقوالــك ص ‪ 1‬لفــة ( ‪ ) 21‬أنــه لــم يكــن معــك شــنطة نهائي ـ ًا فقالــت ال‬\n‫كانــت معــي شــنطة صغيــرة هكــذا أجابــت فجــرى ســؤالها هــل لديــك‬\n\n\n                                                                                    ‫‪144‬‬\n\f      ‫ســابقة فقالــت ســابقة واحــدة وهــي أخالقية حوكمت فيها بســجن ســتة‬\n      ‫أشــهر هكــذا أجابــت هــذا و قــد جــرى االطــاع علــى محضــر القبــض‬\n      ‫فألفيتــه كمــا ذكــر الدعــوى كمــا جــرى االطــاع علــى التقريــر‬\n      ‫الكيميائــي ‪.....‬عــام ‪1433‬ه ـ الصــادر مــن مركــز الســموم بالريــاض‬\n      ‫و املتضمــن إيجابيــة إحــدى العينتــن ملــادة االمفيتامــن و الثانيــة ملــادة‬\n      ‫القــات ا‪.‬ه ـ بتصــرف ثــم جــرى ســؤال املدعــى عليــه ‪.....‬هــل لديــك بينــة‬\n      ‫علــى أن املدعــى عليــه هــي صاحبــة القــات فقــال ال فبنــاء علــى مــا ســلف‬\n      ‫مــن الدعــوى و اإلجابــة وإلقــرار املدعــى عليــه ‪.....‬بتعاطيــه القــات و وجــود‬\n      ‫القويــة بتســليم‬\n                    ‫ّ‬      ‫تســع و عشــرين حزمــة قــات يف منزلــه و لقيــام القرينــة‬\n      ‫املدعــى عليــه ‪.....‬القــات ذي الــوزن مائــة و عشــرة جرامــات وهــي مــا جــاء‬\n      ‫يف شــهادة الشــاهد املعــدل ‪.....‬و لقيــام القرينــة علــى حيــازة املدعــى عليهــا‬\n      ‫‪.....‬ســبع حبــات امفيتامــن وهــي إقرارهــا بوجــود حبــات يف شــنطتها و‬\n      ‫وجــود ســابقة مخــدرات و تناقضهــا يف ذكــر الشــنطة مــن عدمــه وســبب‬\n      ‫دعــوة احلضــور واســم الداعيــة و إلقــرار املدعــى عليــه ‪.....‬بوجــود رجــال‬\n      ‫و نســاء يف منزلــه حضــروا ليشــتروا القــات وألن األصــل أن مــا كان‬\n      ‫يف بيــت املــرء مــن حوزتــه و لعــدم وجــود بينــه لــدى املدعــى عليــه علــى‬\n      ‫اتهامــه املدعــى عليهــا بحيــازة القــات و ملــا جــاء يف برقيــة ســمو وزيــر‬\n      ‫الداخليــة رقــم ‪ 13476‬يف ‪1433/02/23‬ه ـ و القــرار الــوزاري رقــم‬\n      ‫‪ 3818‬يف ‪1410/09/28‬ه ـ ورقــم ‪ 2057‬يف ‪1404/05/26‬ه ـ ورقــم‬\n      ‫‪1374/02/11‬ه ـ وملشــروعية التعزيــر بالتهمــة كمــا حبــس النبــي صلــى‬\n      ‫ا يف تهمــة رواه أبــو داوود و الترمــذي و قــال حســن‬      ‫اهلل عليــه و ســلم رجـ ً‬\n      ‫أخالقيــة علــى‬\n                 ‫ّ‬        ‫صحيــح ولوجــود ســوابق علــى املدعــى عليــه ‪.....‬و ســابقة‬\n      ‫املدعــى عليهــا ‪.....‬مقرونــة بحيــازة مخــدرات فقــد ثبــت لدي إدانــة املدعى‬\n\n\n‫‪145‬‬\n\f‫عليــه ‪.....‬بتعاطــي القــات و حيازتــه كميــة منــه وزنهــا ســتة كيلــو جــرام‬\n‫و تســعون جرامـ ًا بقصــد التعاطــي والترويــج وجعلــه منزلــه وكــر ًا لشــراء‬\n‫القــات وتعاطيــه ولــم يثبــت لــدي إدانتــه بتســليم قــات وزنــه مائــة وعشــرة‬\n‫جرامــات وإمنــا قامــت الشــبهة القويــة علــى ذلــك و لــم يثبــت لــدي إدانــة‬\n‫املدعــى عليــه ‪ .....‬بحيــازة ســبع حبــات امفيتامــن وإمنــا قامــت الشــبهة‬\n‫علــى ذلــك وحكمــت عليهــا مبــا يلــي ‪ /1 :‬ســجن املدعــى عليــه ‪.....‬‬\n‫ســنتني وجلــده أمــام النــاس مائتــن وخمســن جلــدة مفرقــة علــى خمــس‬\n‫دفعــات كل دفعــة خمســون جلــدة و بــن كل دفعتــن عشــرة أيــام وذلــك‬\n‫شــامل لعقوبــة اإلدانــة بحيــازة القــات وتعاطيــه وإعــداد املنــزل لتعاطــي‬\n‫القــات وشــرائه والتهمــة بالتســليم املذكــور ‪ /2‬ســجن املدعــى عليهــا‬\n‫‪ .....‬خمســة أشــهر وإبعادهــا عــن البــاد بعــد تنفيــذ احلكــم و الســجن‬\n‫القضيــة‪ /3 .‬صــرف النظــر‬\n                         ‫ّ‬       ‫احملكــوم بــه يبــدأ مــن تاريــخ اإليقــاف بهــذه‬\n‫عــن املطالبــة بــرد املبلــغ والتســتر لعــدم وجــود موجبــه وبعــرض احلكــم‬\n‫علــى املدعــى عليــه واملدعــى عليهــا واملدعــي العــام قــرر املدعــى عليــه‬\n‫القناعــة وقــررت املدعــى عليهــا القناعــة وقــرر املدعــي العــام االعتــراض‬\n‫مكتفي ـ ًا بالئحــة الدعــوى عــن الالئحــة االعتراضيــة و كان النطــق‬\n‫باحلكــم يف ‪1434/01/07‬ه ـ و أغلقــت اجللســة الســاعة العاشــرة‬\n   ‫والنصــف و صلــى اهلل و ســلم علــى نبينــا محمــد و علــى آلــه وصحبــه‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم األربعــاء ‪1434/07/12‬ه ـ افتتحــت اجللســة الثامنــة‬\n‫وفيهــا حضــر املدعــى عليــه وقــد وردتنــا املعاملة من محكمة االســتئناف‬\n‫بقــرار املالحظــة رقــم ‪ 34215624‬يف ‪1434/05/19‬ه ـ واملتضمــن بعــد‬\n‫املقدمــة أنــه « بدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n\n\n                                                                                       ‫‪146‬‬\n\f      ‫باإلجمــاع لوحــظ باألكثريــة مــا يلــي‪ / 1 :‬أثبــت فضيلتــه حيــازة املدعــى‬\n      ‫عليــه ‪ .....‬لكميــة القــات بالقــرار و بالدعــوى و حكــم عليــه بالســجن‬\n      ‫واجللــد و لــم جنــد أن فضيلتــه حكــم عليــه بغرامــة ماليــة و ال بــد مــن ذلك‬\n      ‫حســب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ‪ /2‬مــا حكــم بــه‬\n      ‫فضيلتــه مــن ســجن املدعــى عليــه ‪ .....‬قليــل جــد ًا لكبــر كميــة القــات‬\n      ‫املضبوطــة عليهــا مبنزلــه و إلعــداد منزلــه و كــر ًا للفســاد و لســوابقه‬\n      ‫التــي لــم تردعــه فــا بــد مــن عقوبــة زاجــرة لــه و رادعــة لغيــره فعلــى‬\n      ‫فضيلتــه مالحظــة مــا ذكــر و إجــراء مــا يلــزم نحوهــا و إحلــاق ملخــص‬\n      ‫مــا يجريــه يف الضبــط إلــى القــرار و مــن ثــم إعــادة املعاملــة إلكمــال‬\n      ‫الزمهــا حســب» وجوابــا علــى مــا الحظــه أصحــاب الفضيلــة يف املالحظــة‬\n      ‫األولــى فقــد حكمــت علــى املدعــى عليــه بغرامــة ماليــة قدرهــا (‪)1000‬‬\n      ‫الســابق‬‫ألــف ريــال و علــى املالحظــة الثانيــة فقــد رجعــت عــن حكمــي ّ‬\n      ‫املتعلــق بســجن املدعــى عليــه ‪.....‬و جلــده ليكــون ســجنه ثالثــن شــهر ًا‬\n      ‫يبــدأ مــن تاريــخ اإليقــاف و جلــده ثالثمائــة و خمســن جلــدة مفرقــة عــل‬\n      ‫ســبع دفعــات كل دفعــة خمســون جلــدة أمــام النــاس و بــن كل دفعتــن‬\n      ‫عشــرة أيــام وبعرضــه عليهــا قــرر املدعــى عليــه القناعــة و املدعــي العــام‬\n      ‫االعتــراض مكتفيـ ًا بالئحــة الدعــوى و انتهــت اجللســة الســاعة الثامنــة‬\n      ‫والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪ 1434/07/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪341319911‬‬\n      ‫وتاريــخ ‪1434/8/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n\n\n‫‪147‬‬\n\f‫باحملكمــة الشــيخ ‪ /‬املســجل برقــم ‪ 3412610‬وتاريــخ ‪1434/1/14‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪..... -2 ).....(..... -1‬‬\n‫( صوماليــة اجلنســية) التهامهمــا بقضيــة ترويــج القــات علــى النحــو‬\n‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‬\n‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n‫ـاء‬\n ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n‫علــى قرارنــا رقــم ‪ 34215624‬وتاريــخ ‪1434/5/19‬ه ـ تقــرر الدائــرة‬\n‫باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬و اهلل املوفــق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪148‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":134,"source_page_end":148,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"537798e4eb3d773e964624f665d31b653752023518551497c58a41f64f0bc901","normalized_text_hash":"d612006210c399c412ec0bf6a2f1c74f9024eb21702e41ecbb839a050be090ac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p134-3412610"},{"id":"c18855f6-7799-53ec-8032-82fb2970ec1f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة مادة الكراك -حيازة احلشيش املخدر -ترويج احلشيش املخدر -الشروع يف بيع احلشيش املخدر -عدم ثبوت إدانة -تعزير ألجل الشبهة -التعزير بالسجن واجللد -1قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة ) -2قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث ) -3نهي النبي صلى اهلل عليه وسلم عن كل مسكر ومفتر الئحة الدعوى العامة ضد املدعى عليه بحيازة مادة الكراك","document_number":"34176897","case_number":"33481973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"مخدرات -حيازة مادة الكراك -حيازة احلشيش املخدر -ترويج احلشيش املخدر -الشروع يف بيع احلشيش املخدر -عدم ثبوت إدانة -تعزير ألجل الشبهة -التعزير بالسجن واجللد -1قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة ) -2قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث ) -3نهي النبي صلى اهلل عليه وسلم عن كل مسكر ومفتر الئحة الدعوى العامة ضد املدعى عليه بحيازة مادة الكراك","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34176897 :‬تاريخه ‪1434/4/2:‬هـ‬\n                         ‫رقم الدعوى ‪33481973:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34257032‬تاريخه‪1434/07/02:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة مــادة الكــراك‪ -‬حيــازة احلشــيش املخــدر‪ -‬ترويــج‬\n      ‫احلشــيش املخــدر‪ -‬الشــروع يف بيــع احلشــيش املخــدر‪ -‬عــدم ثبــوت‬\n                 ‫إدانــة‪ -‬تعزيــر ألجــل الشــبهة‪ -‬التعزيــر بالســجن واجللــد‬\n\n\n\n\n                         ‫‪ -1‬قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة )‬\n              ‫‪ -2‬قوله تعالى ( ويحل لهم الطيبات ويحرم عليهم اخلبائث )‬\n                 ‫‪ -3‬نهي النبي صلى اهلل عليه وسلم عن كل مسكر ومفتر‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بحيــازة مــادة الكــراك‬\n      ‫وحيــازة احلشــيش املخــدر بقصــد الترويــج والشــروع يف بيعهــا‪ ،‬وطلــب‬\n      ‫املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالســجن واجللــد‬\n      ‫والغرامــة ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة وإلغــاء اخلدمــة‬\n      ‫عــن الشــريحة وعــدم صرفهــا مــرة أخــرى وإبعــاد املدعــى عليــه خــارج‬\n      ‫البــاد بعــد تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة‪ ،‬مت القبــض علــى‬\n      ‫ـاء علــى إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج‬\n                                                                    ‫املدعــى عليــه بنـ ً‬\n      ‫مــادة الكــراك ويتواجــد علــى هاتــف جوالــه ومت االتفــاق معــه مــن‬\n      ‫قبــل املصــدر الســري علــى شــراء كميــة مــن مــادة الكــراك وشــوهد‬\n\n‫‪149‬‬\n\f‫املدعــى عليــه وهــو قــادم ثــم غيــر مســاره إلــى أن وصــل للمصــدر ثــم‬\n‫مت القبــض عليــه وتتبــع مســاره فوجــد يف املــكان الــذي وضــع يــده يف‬\n‫جيبــه علــى كيــس بــه قطعتــن‪ ،‬صــدر التقريــر الكيميائــي إيجابيــة‬\n‫احدهمــا ملــادة الكوكايــن املخــدر والثانيــة ملــادة احلشــيش املخــدر‪،‬‬\n‫إنــكار املدعــى عليــه‪ ،‬إحضــار الفرقــة القابضــة‪ ،‬توجيــه التهمــة ضــد‬\n‫املدعــى عليه‪،‬تعزيــر املدعــى عليــه بالســجن واجللــد‪ ،‬تصديــق احلكــم‬\n                                                ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .................‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة يف محافظة جدة‪/‬املســاعد برقم ‪33481973‬‬\n‫وتاريخ ‪ 1433/07/22‬هـ املقيدة باحملكمة برقم ‪ 331378007‬وتاريخ‬\n‫‪ 1433/07/21‬ه ـ ففــي يــوم الســبت املوافــق‪ 1433/07/26‬ه ـ افتتحت‬\n‫اجللسة الساعة ‪ 08 : 15‬وفيها حضر املدعي العام سعودي ‪..............‬‬\n‫املكلــف باالدعــاء العــام مبوجــب خطــاب هيئــة التحقيــق واالدعــاء العــام‬\n‫رقــم ‪ 15832‬وتاريــخ ‪1433/3/6‬ه ـ وأدعــى قائــا بصفتــي مدعيــا‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظــة جــدة ادعــي علــى ‪)45( ..............‬‬\n‫عامـ ًا تشــادي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )..............‬وتاريــخ‬\n‫‪1433/6/17‬ه ـ صــادرة مــن مكافحــة املخــدرات مبحافظــة جــدة املهنــة‬\n‫‪ /‬عاطــل موقــوف بســجن محافظــة جــدة مبوجــب أمــر متديــد التوقيــف‬\n‫رقم (هـ م‪ )42298/5/2‬وتاريخ ‪1433/6/22‬هـ استناد ًا للقرار الوزاري‬\n‫رقــم (‪ )1900‬املقبــوض عليــه بتاريــخ ‪1433/6/17‬ه ـ مــن قبــل مكافحــة‬\n\n                                                                                        ‫‪150‬‬\n\f      ‫رجــال الضبــط اجلنائــي مبكافحــة املخــدرات مبحافظــة جــدة بنــاء علــى‬\n      ‫إخباريــة أحــد املصــادر الســرية عــن ترويــج املدعــى عليــه ملــادة الكــراك‬\n      ‫ويتواجــد علــى هاتفــه احملمــول رقــم (‪ )..............‬وباتفــاق املصــدر معــه‬\n      ‫علــى شــراء كميــة مــن الكــراك مببلــغ (‪ )200‬مائتــن ريــال شــوهد‬\n      ‫املدعــى عليــه قادمـ ًا مــن داخــل أحــد األزقــة ومت وضعــه حتــت املراقبــة ثــم‬\n      ‫غيــر مســاره باجتــاه آخــر بــن مركبــات (الدينــا) كانــت متوقفــة داخــل‬\n      ‫احلــي وشــوهد وهــو يضــع يــده بجيبــه ثــم ذهــب للمصــدر ومت القبــض‬\n      ‫عليــه وعثــر معــه علــى الهاتــف احملمــول الــذي مت التنســيق مــن خاللــه‬\n      ‫وبالرجــوع خلــط ســيره وحتديــد ًا يف املــكان الــذي شــوهد يضــع يــده‬\n      ‫يف جيبــه وجــدت قطعتــان األولــى قطعــة بيضــاء اللــون شــبه صلبــة بلــغ‬\n      ‫وزنهــا (‪ )0.4‬أربعــة أعشــار اجلــرام بداخــل كيــس والثانيــة قطعــة بيضــاء‬\n      ‫اللــون شــبه صلبــة بلــغ وزنهــا (‪ )0.3‬ثالثــة أعشــار اجلــرام بداخــل كيــس‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/2219‬ك ش م) لعــام‬\n      ‫‪1433‬ه ـ احتــواء العينــة (أ)مــن الكمييــة املضبوطــة واملرســلة للتحليــل‬\n      ‫علــى مــادة الكوكائــن املخــدر املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ)‬\n      ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحتــواء العينــة‬\n      ‫(ب) علــى مــادة احلشــيش املخــدر واحتواؤهــا علــى املــادة الفعالــة لــه‬\n      ‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وقــد انتهــى التحقيــق الــى توجيــه االتهــام الــى‬\n      ‫املدعــى عليــه بحيــازة (‪ )0.4‬أربعــة أعشــار اجلــرام مــن مــادة الكــراك‬\n      ‫وحيازة(‪)0,3‬ثالثــة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر بقصــد‬\n      ‫الترويــج والشــروع يف بيعهــا اســتناد ًا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لألدلــة والقرائــن‬\n\n\n‫‪151‬‬\n\f‫التاليــة مــا ورد يف شــهادة الشــهود مبحضــر الضبــط املنــوه عنــه واملرفــق‬\n‫لفــة رقــم (‪ )1‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق‬\n‫لفــة (‪ )22‬اإلخباريــة الــواردة عنــه وحملــه وإحضــاره للكميــة املخــدرة‬\n‫باملوقــع ومقابلتــه للمصــدر وضبــط اجلــوال املســتخدم يف التنســيق يف ظــل‬\n‫عــدم وجــود مصــدر دخــل ثابــت لــه كلهــا قرائــن تؤكــد مــا أســند إليــه‬\n‫وباالطــاع علــى ســوابقه عثــر علــى ســابقة (حيــازة مخــدرات) وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا مــن‬\n‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومعاقــب عليــه وفقــا للمــادة (‪)59 ، 38‬‬\n‫مــن ذات النظــام مــع مراعــاة مــا وردة باملــادة(‪ )62‬لــذا أطلــب إثبــات مــا‬\n‫أســند إليــه ومعاقبتــه بالعقوبــات األصليــة والتكميليــة التاليــة بالســجن‬\n‫واجللــد والغرامــة اســتنادا للمــادة(‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة املشــار إليــه مــع تشــديد العقوبــة عليهاســتنادا‬\n‫للفقــرة(‪/2‬ج) مــن ذات املــادة مصــادرة جهــاز الهاتــف احملمــول مــن نــوع‬\n‫(‪ ).....‬ذي الرقــم املصنعــي (‪ )..............‬املســتخدم يف ارتــكاب اجلرميــة‬\n‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه وإلغــاء اخلدمــة عــن الشــريحة وعــدم صرفهــا لســوء‬\n‫اســتخدامها اســتناد ًا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n‫رقــم (‪ )9798‬يف ‪9‬ــ‪1428/2/10‬ه ـ إبعــاده خلــارج اململكــة بعــد االنتهــاء‬\n‫مــن تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا اســتناد ًا للفقــرة (‪)2‬‬\n‫مــن املــادة (‪ )56‬مــن نظــام املخــدرات املشــار إليــه وبعــرض مــاورد بدعــوى‬\n‫املدعــي العــام علــى املدعــى عليــه احلاضــر يف املجلــس الشــرعي أجــاب‬\n\n\n                                                                                          ‫‪152‬‬\n\f      ‫قائــا مــاورد يف دعــوى املدعــي العــام توجيــه االتهــام لــي بحيــازة (‪)0.4‬‬\n      ‫أربعــة أعشــار اجلــرام مــن مــادة الكــراك وحيازة(‪)0,3‬ثالثــة أعشــار‬\n      ‫اجلــرام مــن مــادة احلشــيش املخــدر بقصــد الترويــج والشــروع يف بيعهــا‬\n      ‫فغيــر صحيــح جملــة وتفصيــا هــذا جوابــي علــى الدعــوى عليــه فقــد‬\n      ‫جــرى ســؤال املدعــي العــام هــل لديــه بينــه علــى مــا ذكــر قــال نعــم لــدي‬\n      ‫بينــه علــى مــا ذكــرت ومســتعد بإحضارهــم وعليــه فقــد رفعــت اجللســة‬\n      ‫لتكليــف املدعــي العــام بإحضــار بينتــه وجــرى قفلهــا يف متــام الســاعة‬\n      ‫الثامنــة والنصــف صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/07/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/01/25‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة احلاديــة عشــر والربــع صباحــا وفيهــا حضــر‬\n      ‫املدعــي العــام وأحضــر للشــهادة وأدائهــا كال مــن ‪ ..............‬ســعودي‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ..............‬والــذي يعمــل برتبــه عريــف يف‬\n      ‫إدارة مكافحــة املخــدرات مبحافظــة جــدة ‪ ..............‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ..............‬والــذي يعمــل برتبــه رقيــب يف‬\n      ‫إدارة مكافحــة املخــدرات مبحافظــة جــدة وبســؤالهما عمــا لديهمــا مــن‬\n      ‫شــهادة بعــد إطالعهمــا علــى محضــر القبــض شــهد كل واحــد منهمــا‬\n      ‫علــى انفــراد قائــا نشــهد بــاهلل العظيــم بــأن جميــع مــاورد يف محضــر‬\n      ‫القبــض صحيــح جملــة وتفصيــا واملتضمــن انــه بتاريــخ ‪1433/6/17‬ه ـ‬\n      ‫مت القبــض علــى املدعــى عليــه مــن قبلنــا نحــن وباقــي أفــراد الفرقــة‬\n      ‫القابضــة بنــاء علــى إخباريــة أحــد املصــادر الســرية عــن ترويــج املدعــى‬\n      ‫عليــه ملــادة الكــراك ويتواجــد علــى هاتفــه احملمــول رقــم (‪)..............‬‬\n      ‫وباتفــاق املصــدر معــه علــى مســمع منــا علــى شــراء كميــة مــن الكــراك‬\n\n\n‫‪153‬‬\n\f‫مببلــغ (‪ )200‬مائتــن ريــال مت انتقالنــا والوصــول للموقــع املتفــق عليــه‬\n‫وبــه متركــز املصــدر ومتركــزت عناصــر الفرقــة يف أنحــاء متفرقــة منــه‬\n‫ويف هــذه األثنــاء شــوهد املدعــى عليــه قادم ـ ًا مــن داخــل أحــد األزقــة‬\n‫ومت وضعــه حتــت املراقبــة ثــم غيــر مســاره باجتــاه آخــر بــن مركبــات‬\n‫(‪ )........‬كانــت متوقفــة داخــل احلــي وشــوهد وهــو يضــع يــده بجيبــه ثــم‬\n‫ذهــب للمصــدر ومت القبــض عليــه وعثــر معــه علــى الهاتــف احملمــول‬\n‫الــذي مت التنســيق مــن خاللــه وبالرجــوع خلــط ســيره وحتديــد ًا يف املكان‬\n‫الــذي شــوهد يضــع يــده يف جيبــه وجــدت قطعتــان األولــى قطعــة بيضــاء‬\n‫اللــون شــبه صلبــة بلــغ وزنهــا (‪ )0.4‬أربعــة أعشــار اجلــرام بداخــل كيــس‬\n‫والثانيــة قطعــة بيضــاء اللــون شــبه صلبــة بلــغ وزنهــا (‪ )0.3‬ثالثــة أعشــار‬\n‫اجلــرام بداخــل كيــس هــذا مالدينــا مــن شــهادة واهلل خيــر الشــاهدين‬\n‫هــذا ثــم جــرى رفــع اجللســة لعــرض الشــهود وشــهادتهم علــى املدعــى‬\n‫عليهــم وجــرى قفلهــا يف متــام الســاعة احلاديــة عشــر والنصــف صباحــا‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                 ‫حــرر يف ‪ 1434/01/25‬ه ـ‬\n‫احلمد هلل وحده وبعد ففي يوم السبت املوافق‪1434/02/09‬هـ افتتحت‬\n‫اجللســة الســاعة التاســعة والربــع صباحــا وفيهــا حضــر الطرفــان وبعــرض‬\n‫الشــهود وشــهادتهم علــى املدعــى عليــه احلاضــر يف املجلــس الشــرعي‬\n‫أنكــر مــاورد فيهــا جملــة وتفصيــا وقــال الشــهادة غيــر صحيحــة وأمــا‬\n‫الشــهود فــا أعرفهــم وال أريــد البحــث عــن حالهــم عليــه فقــد جــرى‬\n‫طلــب مزكــن للشــهود وجــرى قفلهــا يف متــام الســاعة التاســعة والنصــف‬\n‫صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                           ‫وســلم حــرر يف ‪ 1434/02/09‬ه ـ‬\n\n\n                                                                                     ‫‪154‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافق‪1434/02/12‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الثامنــة والربــع صباحــا حضــر املدعــي العــام‬\n      ‫وأحضــر للتزكيــة كال مــن ‪ ..............‬ســعودي مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ..............‬والــذي يعمــل برتبــه عريــف يف مكافحــة املخــدرات بجــدة‬\n      ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬والذي‬\n      ‫يعمــل برتبــه جنــدي يف مكافحــة املخــدرات مبحافظــة جــده وبســؤالهما‬\n      ‫عمــا لديهمــا مــن تزكيــة شــهد كل وأحــد منهمــا علــى انفــراد قائــا‬\n      ‫نشــهد بــاهلل العظيــم أن الشــهود املذكوريــن يف هــذه القضيــة معروفــن‬\n      ‫باألمانــة والعدالــه والثقــه نحســبهم كذلــك واهلل حســيبهم هــذا ثــم‬\n      ‫جــرى رفــع اجللســة ليــوم الســبت املوافــق ‪1434/2/16‬ه ـ ألحضــار‬\n      ‫الســجني وجــرى قفلهــا يف متــام الســاعة الثامنــة والنصــف صباحــا وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                               ‫يف ‪ 1434/02/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/03/22‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الثامنــة وخمــس وربعــون دقيقــة صباحــا‬\n      ‫وفيهــا حضــر الطرفــان فبنــاء علــى ماتقــدم مــن الدعــوى واالجابــه‬\n      ‫وشــهادة الشــهود املعدلــن طبقــا لألصــول الشــرعية وحيــث أن الشــريعة‬\n      ‫االســاميه جــاءت بحفــظ الضروريــات اخلمــس الديــن والنفــس والعقــل‬\n      ‫واملــال والعــرض وهــذه آالفــه مذهبــه للديــن ومهلكــه للنفــس ومفســده‬\n      ‫للعقــل مضيعــة للمــال والعــرض ولقولــه تعالــى { وال تلقــوا بأيديكــم‬\n      ‫إلــى التهلكــة } وقولــه تعالــى {ويحــل لهــم الطيبــات ويحــرم عليهــم‬\n      ‫اخلبائــث } ولنهيــه صلــى اهلل عليــه وســلم عــن كل مســكر ومفتــر وملــا‬\n      ‫يف ذلــك الضــرر علــى املدعــى عليــة وعلــى املجتمــع بأســره ومــا تســببه‬\n\n\n‫‪155‬‬\n\f‫مــن انحــال وتدميــر وانتشــار للفســاد والرذيلــه وملــا يف فعــل املدعــى‬\n‫عليــه مــن عصيــان هلل ولرســوله ولولــي األمــر وحيــث إن التعزيــر مشــروع‬\n‫يف كل معصيــة ال حــد فيهــا وال كفــاره وحيــث أن مــا قــدم املدعــي‬\n‫العــام ال يكفــي اليثبــات إدانــة املدعــى عليــه وإمنــا يقــوي الشــبهه يف حقــه‬\n‫مبــا أســند إليــه وحكمــت عليــه لقــاء ذلــك مبــا يلــي أو ًال ســجنه ملــدة‬\n‫خمــس ســنوات حتســب منهــا مــده إيقافــه علــى ذمــة هــذه القضيــة وجلــده‬\n‫أربعمائــة ســوط علــى دفعــات كل دفعــة خمســن ســوط بــن كل دفعــة‬\n‫والتــي تليهــا مــدة ال تقــل عــن خمســة أيــام ثاني ـ ًا إبعــاده عــن البــاد بعــد‬\n‫انتهــاء تنفيــذ محكوميتــه وعــدم الســماح لــه بالعـ ــودة إليهــا ومصــادرة‬\n‫الهاتــف اجلــوال املضبــوط بحوزتــه وإلغــاء شــريحته وعــدم صرفهــا لــه‬\n‫مــرة أخــرى وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر‬\n‫املدعــي العــام عــدم القناعــة وطلــب االســتئناف فأجبتــه لطلبــه وســيجري‬\n‫اتخــاذ الــازم حســب التعليمــات جــرى النطــق باحلكــم يف متــام الســاعة‬\n‫التاســعة صباحــا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم حــرر يف ‪ 1434/03/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/7/16‬ه ـ الســاعة‬\n‫التاســعة فتحــت اجللســة لــدي انــا ‪ ..............‬القاضــي باحملكمــة اجلزائيــة‬\n‫مبحافظــة جــده والقائــم بعمــل القاضــي ‪ ..............‬مبوجــب خطــاب‬\n‫التكليــف رقــم ‪341712792‬يف ‪1434/7/16‬ه ـ وجــرى االطــاع علــى‬\n‫أوراق املعاملــة وكانــت قــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة وبرفقهــا قرارهــا رقــم ‪34257032‬يف ‪1434/7/2‬ه ـ‬\n‫باملصادقــة علــى احلكــم ونــص احلاجــة منــه (وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل‬\n\n\n                                                                                          ‫‪156‬‬\n\f      ‫املوفــق )وموقــع ومختــم مــن أصحــاب الفضيلــة أعضــاء الدائــرة اجلزائيــة‬\n      ‫الســابعة وهــم كال مــن الشــيخ ‪ ..............‬والشــيخ ‪ ..............‬لــي وجهــة‬\n      ‫نظــر والشــيخ ‪ ..............‬فجــرى تدوينــه حفظــا للواقــع وجــرى قفلهــا يف‬\n      ‫متــام الســاعة التاســعة والنصــف وصلــى اهلل علــى نبينــا محمــد والــه‬\n                                                                        ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":149,"source_page_end":157,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"76c40dc3f0d85d46af71cee0c79d5ea8f600b2bf2e9e1d572243b86bcf278628","normalized_text_hash":"124c1c770ae9b6301a34a1cdc9ab8a7a18ccb483e3ec1fa7c5426b005ba06a41","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p149-34176897"},{"id":"846852d3-9e7e-5e7e-9d40-b45b56324ed2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -عدم قبول الرجوع عن اإلقرار -إدانة -تعزير بالسجن واملنع من السفر.","document_number":"33482733","case_number":"33507446","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -عدم قبول الرجوع عن اإلقرار -إدانة -تعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33482733:‬تاريخه‪1433/12/29:‬هـ‬\n                   ‫رقم الدعوى‪33507446:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3448164‬تاريخه‪1434/02/26:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي‪ -‬عــدم قبــول‬\n‫الرجــوع عــن اإلقــرار‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n‫‪ -1‬حقــوق اهلل تعالــى التــي ال تــدرأ بالشــبهة ال يقبــل فيهــا الرجــوع عــن‬\n                                        ‫اإلقــرار بــا خــاف‪( .‬املغنــي ‪.)5/95‬‬\n   ‫‪ -2‬املواد (‪ )41‬و (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة حبــوب اإلمفيتامــن بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة‬\n‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى حبــوب‬\n‫يحتمــل أن تكــون محظــورة‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n‫إيجابيــة العينــة املرســلة ملــادة اإلمفيتامــن‪ ،‬اعتــرف أمــام جهــة التحقيــق‬\n‫بحيازتــه للحبــوب احملظــورة بقصــد التعاطــي‪ ،‬أنكــر أمــام احملكمــة‬\n‫مــا أســنده إليــه املدعــي العــام‪ ،‬مــن املقــرر شــرع ًا أن حقــوق اهلل تعالــى‬\n‫التــي ال تــدرأ بالشــبهة ال يقبــل فيهــا الرجــوع عــن اإلقــرار بــا خــاف‪،‬‬\n‫قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه وقــررت ســجنه‬\n\n                                                                                      ‫‪158‬‬\n\f      ‫ملــدة ســتة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض‬\n      ‫املدعــى عليــه واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمة االســتئناف‬\n                                                         ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل املكلــف برقــم ‪ 33507446‬وتاريــخ ‪ 1433/08/05‬ه ـ‬      ‫ّ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331470739‬وتاريــخ ‪ 1433/08/05‬ه ـ ففــي‬\n      ‫يــوم األربعــاء املوافــق‪ 1433/12/29‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫احلاديــة عشــرة وفيهــا حضــر املدعــي العــام وادعــى علــى احلاضــر معــه‬\n      ‫ســعودي بالســجل رقــم (‪ )........‬بالئحــة دعــوى هــذا نصهــا (بأنــه بتاريــخ‬\n      ‫‪1433/6/29‬ه ـ مت اســتيقاف املدعــى عليــه مــن قبــل نقطــة تفتيــش تابعــة‬\n      ‫للقــوة اخلاصــة بأمــن الطــرق علــى طريــق (‪ ).....‬مركــز ‪ .....‬وبقيادتــه‬\n      ‫ســيارة نــوع (‪ ).....‬وعنــد طلــب أوراقــه الثبوتيــة لوحــظ عليــه االرتبــاك‬\n      ‫والتلعثــم بالــكالم وبعــد تفتيــش املركبــة عثــر علــى (‪ )2.5‬حبتــن‬\n      ‫ونصــف احلبــة مــن احملتمــل أن تكــون مــن احلبــوب احملظــورة وجــدت‬\n      ‫حتــت ديكــور القيــر مــن جهــة الراكــب فتــم القبــض عليــه‪ .‬وقــد أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n      ‫الســموم بالقصيــم رقــم (‪ )812‬لعــام ‪1433‬ه ـ إيجابيــة احلبــوب املضبوطــة‬\n      ‫ملــادة اإلمفيتامــن املنبهــة احملظــورة‪ .‬وباســتجوابه أقــر بصحــة واقعــة‬\n      ‫القبــض وحيازتــه ملــا ضبــط بقصــد التعاطــي وأنــه أخذهــا مــن شــخص‬\n      ‫علــى طريــق القصيــم عنــد إحــدى احملطــات‪ .‬وقــد أســفر التحقيــق معــه‬\n\n‫‪159‬‬\n\f‫عــن اتهامــه بحيــازة (‪ )2.5‬حبتــن ونصــف احلبــة مــن حبــوب اإلمفيتامــن‬\n‫املنبهــة واحملظــورة بقصــد التعاطــي وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ )1‬مــا جــاء مبحضــر االســتجواب واملــدون واملرفــق لفــة رقــم (‪.)14.13‬‬\n‫‪ )2‬مــا تضمنــه محضــر القبــض والتفتيــش املــدون علــى الصفحــة رقــم‬\n‫(‪ )9.8‬بتقريــر األحــوال األمنيــة املوحــد املرفــق لفــة رقــم (‪ ) 3.)1‬مــا جــاء‬\n‫يف التقريــر الكيمائــي الشــرعي املشــار إليــه املرفــق لفــة رقــم (‪.)20‬‬\n‫وبالبحــث يف ســجله اجلنائــي اتضــح عــدم وجــود ســوابق مســجلة عليــه‬\n‫حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا ونظام ـ ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه مبــا‬\n‫يلــي‪ -1 :‬الســجن ‪ -2‬املنــع مــن الســفر وفق ـ ًا للمادتــن (‪ )56-41‬مــن‬\n‫نظام مكافحة املخدرات واملؤثرات العقلية‪،،،.‬وبالل ــه التوفي ــق‪ ).‬أ‪.‬هـ‪.‬‬\n‫هكــذا ادعــى وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب‬\n‫بقولــه‪ :‬غيــر صحيــح جملــة وتفصيــا‪ .‬ثــم ســألت املدعــي العــام هــل لديــك‬\n‫زيــادة بينــة غيــر مــا قدمــت ؟ قــال‪ :‬ال ســوى مــا وجــد بــأوراق املعاملــة‪.‬‬\n‫ثــم جــرى االطــاع فيهــا علــى اعتــراف املدعــى عليــه حتقيقــا لــدى هيئــة‬\n‫التحقيــق واالدعــاء العــام املــدون علــى لفــة رقــم ( ‪ )14،13‬املتضمــن‬\n‫اعتــراف املدعــى عليــه بحيازتــه للمؤثــرات العقليــة بقصــد التعاطــي‬\n‫واالســتعمال الشــخصي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬أنــي‬\n‫اعترفــت حيــث قــال لــي احملقــق ال تخــرج حتــى تعتــرف فاعترفــت ويف‬\n‫احلقيقــة هــي ليســت لــي‪ .‬ثــم ســألت املدعــى عليــه أيــن وجــدت احلبــوب ؟‬\n‫فأجــاب بقولــه‪ :‬وجــدت يف الســيارة التــي كنــت أقودهــا وهــي ليســت لــي‬\n‫وهــي ألحــد أقاربــي أخذتهــا منــه إلحضــار قطعــة غيــار لســيارتي‪ .‬هكذا‬\n‫أجــاب‪ .‬ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة ومــن ضمنهــا‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫التقريــر الكيميائــي الشــرعي رقــم (‪ )812‬لعــام ‪1433‬ه ـ املتضمــن‬\n      ‫إيجابيــة احلبــوب املضبوطــة ملــادة اإلمفيتامــن املنبهــة احملظــورة‪ .‬املــدون‬\n      ‫علــى لفــه رقــم (‪ )20‬ثــم جــرى االطــاع الســجل اجلنائــي الصــادر بحــق‬\n      ‫املدعــى عليــه املتضمــن عــدم وجــود ســوابق مســجلة بحقــه حتــى تاريخــه‬\n      ‫ـاء علــى مــا ســلف مــن الدعــوى‬  ‫كمــا هــو مــدون علــى لفــه رقــم (‪ .)25‬فبنـ ً‬\n      ‫واإلجابــة وإلقــرار املدعــى عليــه حتقيقــا بحيازتــه حلبتــن ونصــف مــن‬\n      ‫احلبــوب احملظــورة وحيــث ذهــب الفقهــاء إلــى أن حقــوق اهلل تعالــى التــي‬\n      ‫ال تــدرأ بالشــبهة ال يقبــل فيهــا الرجــوع عــن اإلقــرار بــا خــاف والتعزيــر‬\n      ‫مــن احلقــوق التــي ال تــدرأ بالشــبهة بــل يثبــت معهــا فــا يقبــل فيــه الرجــوع‬\n      ‫عــن اإلقــرار‪ (.‬ينظــر‪ :‬املغنــي ( ‪ ، )95/5‬حاشــية رد احملتــار ( ‪) )60/4‬‬\n      ‫وحيــث أقــر املدعــى عليــه لــدى هيئــة التحقيــق واالدعــاء العــام بطوعــه‬\n      ‫ـاء علــى مــا تقــدم من التقرير الكيميائي الشــرعي وملا جاء‬           ‫واختيــاره وبنـ ً‬\n      ‫ـدي إدانــة املدعــى عليــه مبــا اســند إليــه وهــو‬\n                                                        ‫يف أوراق املعاملــة فقــد ثبــت لـ ّ‬\n      ‫حيــازة حبتــن ونصــف احلبــه مــن حبــوب اإلمفيتامــن املنبهــة واحملظــورة‬\n      ‫ـاء علــى املــادة رقــم (‪ )56،41‬مــن نظــام مكافحــة‬       ‫لقصــد التعاطــي وبنـ َ‬\n      ‫املخــدرات واملؤثــرات العقليــة قــررت تعزيــره علــى ذلــك مبــا يلي‪ :‬أ)ســجنه‬\n      ‫ـداء مــن تاريــخ توقيفــه بهــذه القضيــة‪ .‬ب) منعــه مــن‬ ‫ملــدة ســتة أشــهر ابتـ ً‬\n      ‫الســفر ملــدة ســنتني خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميــة‬\n      ‫ســجنه‪ .‬هــذا مــا ظهــر لــي وبــه حكمــت‪ .‬وبعرضــه علــى املدعــي العــام‬\n      ‫لــم يقنــع بــه وطلــب متييــزه بــدون الئحــة اعتراضيــة وبعرضــه علــى املدعــى‬\n      ‫عليــه لــم يقنــع بــه وطلــب متييــزه بالئحــة اعتراضيــة فجرى تســليمه نســخة‬\n      ‫مــن القــرار الشــرعي إلبــداء معارضتــه عليــه يف مــدة أقصاهــا ثالثــون‬\n      ‫يومــا مــن هــذا اليــوم األربعــاء املوافــق ‪1433/12/29‬ه ـ وأفهمتــه أنــه إن‬\n\n\n‫‪161‬‬\n\f‫تأخــر عــن ذلــك ســقط حقــه يف االعتــراض وســترفع املعاملــة حملكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة ففهــم ذلــك ‪ ،‬وعليــه جــرى التوقيــع‬\n‫مت قفــل اجللســة يف متــام الســاعة احلاديــة عشــرة والنصــف مــن هــذا اليــوم‬\n‫األربعــاء املوافــق ‪1433/12/29‬ه ـ واهلل املوفــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا‬\n‫اليــوم الثالثــاء ‪1434/2/12‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر‬\n‫وحيــث أن املدعــى عليــه لــم يتقــدم بالئحتــه االعتراضيــة حتــى اآلن لــذا‬\n‫فقــد ســقط حقــه يف االعتــراض وقــررت التهميــش علــى الضبــط والقرار‬\n‫وقــررت بعــث املعاملــة حملكمــة االســتئناف إلجــراء الزمهــا وقفلــت‬\n‫اجللســة الســاعة احلاديــة عشــرة وعشــر دقائــق واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/2/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األربعــاء املوافــق ‪1434/2/20‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الواحــدة وحيــث إن املدعــى عليــه قــد‬\n‫تقــدم بالئحتــه االعتراضيــة واملكونــة مــن ورقــة واحــدة واملقيــدة يف‬\n‫هــذه احملكمــة برقــم ‪ 34214084‬يف ‪1434/1/25‬ه ـ وباالطــاع عليــه‬\n‫لــم أجــد مــا يؤثــر علــى مــا حكمــت بــه ولــم يتــم االنتبــاه إلــى ذلــك إال‬\n‫عنــد تصديــر املعاملــة فعليــه قــد رجعــت عمــا قررتــه مــن ســقوط حــق‬\n‫املدعــى عليــه باالعتــراض وقــررت رفــع كامــل أوراق املعاملــة حملكمــة‬\n‫االســتئناف إلجــراء الزمهــا واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                    ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/20‬هــ‪.‬‬\n‫احلمــد اهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫املختصــة بتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n\n\n                                                                                       ‫‪162‬‬\n\f      ‫مبنطقــة حائــل برقــم ‪ 332124240‬يف تاريــخ ‪1434/02/23‬ه ـ واملقيــد‬\n      ‫لدينــا برقــم ‪ 34459218‬يف تاريــخ ‪1434/02/24‬ه ـ املرفــق بهــا القــرار‬\n      ‫الشــرعي الصــادر مــن صاحــب الفضيلــة الشــيخ‪ ..../‬القاضــي باحملكمة‬\n      ‫اجلزائيــة مبنطقــة حائــل برقــم ‪ 33482733‬يف تاريــخ ‪1433/12/29‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ...../‬ســعودي بالســجل املدنــي‬\n      ‫رقــم ‪ .....‬بشــأن حيــازة مخــدرات وقــد تضمــن القــرار حكــم صاحــب‬\n      ‫الفضيلــة وفقــه اهلل علــى املدعــى عليــه علــى النحــو املفصــل يف القــرار‬\n      ‫املرفــق‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة والالئحــة‬\n      ‫االعتراضية‪،‬جــرت املصادقــة علــى ماحكــم بــه فضيلتــه بالقــرار‬\n      ‫املشــار إليــه‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                     ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪163‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":158,"source_page_end":163,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa1993fbabbf593d1ec40b364cda6e2b9114f882e010534ea8cf7181d989c030","normalized_text_hash":"a12f00a613dcd9edc5aecac16248e310c5652be076d9eab65df4e0fcda3eee47","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p158-33482733"},{"id":"3c1280cb-43a0-51bf-a27d-5d8ae61a513c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -رجوع عن اإلقرار بالتعاطي -درء احلدود بالشبهات -تعزير للتهمة القوية -عدم ثبوت إدانة بالتستر -نزول عن احلد األدنى للعقوبة -التعزير .","document_number":"34260118","case_number":"33513449","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/07","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -رجوع عن اإلقرار بالتعاطي -درء احلدود بالشبهات -تعزير للتهمة القوية -عدم ثبوت إدانة بالتستر -نزول عن احلد األدنى للعقوبة -التعزير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34260118:‬تاريخه‪1433/08/07 :‬هـ‬\n                   ‫رقم الدعوى ‪33513449:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34282927‬تاريخه‪1434/07/30:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه وتســتر علــى‬\n ‫مصــدره‪ -‬رجــوع عــن اإلقــرار بالتعاطــي‪ -‬درء احلــدود بالشــبهات‪ -‬تعزيــر‬\n ‫للتهمــة القويــة‪ -‬عــدم ثبــوت إدانــة بالتســتر‪ -‬نــزول عــن احلــد األدنــى‬\n                                                        ‫للعقوبــة ‪ -‬التعزيــر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬جاء يف املغني (‪« :)95/5‬وال يقبل رجوع املقر عن إقراره‪ ..‬إلخ»‪.‬‬\n ‫‪ -2‬املــادة (‪ )41‬و (‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيازتــه احلشــيش املخــدر بقصد‬\n ‫التعاطــي وتعاطيــه لــه وتســتره علــى مصــدر مــا ضبــط معــه‪ ،‬واحلكــم‬\n ‫عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة‬\n ‫املخــدرات واملؤثــرات العقليــة وعقوبــة تعزيريــة علــى التســتر حيــث إنــه مت‬\n ‫تفتيــش ســيارة املدعــى عليــه بعــد االشــتباه بــه فعثــر فيهــا علــى حشــيش‬\n ‫مخــدر وأثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫ملــادة احلشــيش املخــدر‪ -‬كمــا اعتــرف حتقيق ـ ًا باســتعمال احلشــيش‬\n ‫املخــدر‪ ،‬أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام مــن احليــازة‬\n\n                                                                                         ‫‪164‬‬\n\f      ‫ورجــع عــن اعترافــه باســتعمال احلشــيش املخــدر كمــا أنكــر التســتر‬\n      ‫علــى مصــدر مــا ضبــط معــه‪ ،‬وملــا كان مــن املقــرر شــرع ًا أن الرجــوع‬\n      ‫عــن اإلقــرار شــبهة يــدرأ بهــا احلــد حيــث إن املدعــى عليــه أبــدى التوبــة‬\n      ‫والنــدم وال يوجــد لــه ســوابق والكميــة احملــازة قليلــة فقضــت احملكمــة‬\n      ‫بإدانــة املدعــى عليــه بحيــازة احلشــيش املخــدر بقصــد االســتعمال‪ ،‬كمــا‬\n      ‫قضــت بــدرء حــد املســكر عنــه وعــدم ثبــوت تســتره علــى مصــدر املخــدر‬\n      ‫وقــررت ســجنه ملــدة ثالثــة أشــهر ومنعــه مــن الســفر خــارج اململكــة‬\n      ‫ملــدة ســنتني وجلــده ســبعني جلــدة علــى دفعتــن متســاويتني لقــاء إقــراره‬\n      ‫حتقيق ـ ًا باســتعمال احلشــيش املخدر‪،‬وقنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض املدعــي العــام عليــه وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                         ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر‬\n      ‫برقــم ‪ 33513449‬وتاريــخ ‪1433/08/07‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 331494414‬وتاريــخ ‪1433/08/07‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n      ‫‪1434/07/04‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 :00‬وفيهــا قــدم املدعــي‬\n      ‫العــام ‪ ........‬الئحــة دعــوى عامــه ضد‪........‬ســعودي اجلنســية مبوجــب‬\n      ‫ا فيهــا حيــث انه باالطــاع على محضر‬       ‫الســجل املدنــي رقــم (‪ )........‬قائـ ً‬\n      ‫القبــض املعــد بتاريــخ ‪1433/6/14‬ه ـ مــن قبــل دوريــات أمــن الطــرق‬\n      ‫بطريــق الدمــام الريــاض الســريع تبــن انــه مت القبــض علــى املدعــى عليــه‬\n\n‫‪165‬‬\n\f‫بعــد اســتيقافهم ظهــرت عليــه عالمــات االرتبــاك الشــديد‪ ،‬وبتفتيــش‬\n‫ســيارته ضبطــت قطعــة تــزن (‪ )4‬أربعــة جرامــات يشــتبه ان تكــون مــن‬\n‫احلشــيش املخــدر ‪ ،‬وســيجارة تــزن (‪ )0,6‬جاهــزة لالســتخدام يشــتبه ان‬\n‫تكــون مــن احلشــيش املخــدر وقــد اثبــت القريــر الكيمــاوي الشــرعي‬\n‫رقــم (‪ )........‬ايجابيــة القطعــة املضبوطــة ملــادة احلشــيش املخــدر املــدرج‬\n‫يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة ‪ ،‬وايجابيــة الســيجارة امللفوفــة يدويــا غيــر مدخنــة وبــدون فلتــر‬\n‫ملــادة احلشــيش املخــدر املــدرج يف اجلــدول (‪ )1‬فئــة (أ) مــن ذات النظــام‬\n‫وباســتجواب املدعــى عليــه‪ /‬اعتــرف بشــراء مــا مت ضبطــه بحوزتــه‬\n‫مببلــغ (‪ )100‬ريــال مــن شــخص ال يعرفــه لقصــد االســتعمال الشــخصي‬\n‫وانتهــى التحقيــق إلــى توجيــه االتهــام ل‪........‬بحيــازة قطعــة تــزن (‪)4‬‬\n‫جرامــات مــن احلشــيش املخــدر وســيجارة ملفوفــة يدويــا تــزن (‪)0,6‬‬\n‫ســتة أعشــار اجلــرام مــن احلشــيش املخــدر لقصــد االســتعمال الشــخصي‬\n‫وتعاطيــه لنوعــه وتســتره علــى مصــدر املخــدرات وذلــك لألدلــة والقرائــن‬\n‫التالية‪-1:‬اعترافــه مبــا أشــير إليــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن‬\n‫دفتــر االســتدالل املرفــق لفــة رقــم (‪ ، )5‬والصفحــة رقــم (‪ )1‬مــن دفتــر‬\n‫التحقيــق املرفقــة لفــة رمــق (‪ -2 )12‬محضــر القبــض املرفــق لفــة رقــم‬\n‫(‪ -3 )26‬التقريــر الكيمــاوي الشــرعي املرفــق لفــة رقــم (‪ )26‬وبالبحــث‬\n‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائية مســجلة وحيث‬\n‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب اآلتــي‪ :‬أو ًال إثبــات إدانتــه مبــا‬\n‫أســند إليــه وفق ـ ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واحلكــم عليــه مبــا يلــي‪ -1:‬العقوبــة الــواردة يف الفقــرة رقــم‬\n\n\n                                                                                         ‫‪166‬‬\n\f      ‫(‪ )1‬مــن املــادة (‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر خــارج اململكــة‬\n      ‫بعــد تنفيــذ محكوميتــه اســتنادا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن ذات‬\n      ‫النظــام ثانيـ ًا احلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره لتســتره‬\n      ‫علــى مصــدر املخــدرات هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى‬\n      ‫أجــاب بقولــه مــا جــاء يف الدعــوى مــن حيازتــي قطعــة حشــيش مخــدر‬\n      ‫وســيجارة ملفوفــة حتتــوي علــى احلشــيش املخــدر بقصــد االســتعمال هــذا‬\n      ‫صحيــح ومــا جــاء يف الدعــوى مــن تســتري علــى مصــدر احلشــيش املخــدر‬\n      ‫واســتعمالي احلشــيش املخــدر فهــذا غيــر صحيــح وقــد مت القبــض علــي‬\n      ‫يف تاريــخ ‪1433/6/14‬ه ـ مــن قبــل أمــن الطــرق علــى طريــق الريــاض‬\n      ‫الدمــام عندمــا كنــت أقــود ســيارتي نــوع بــي أم وقــد وجــد رجــال األمــن‬\n      ‫داخــل ســيارتي قطعــة حشــيش مخــدر تــزن أربعــة جرامات (‪ )4‬وســيجارة‬\n      ‫ملفوفــة حتتــوي علــى احلشــيش املخــدر تــزن ســتة مــن العشــرة مــن اجلــرام‬\n      ‫(‪ )0.6‬وهمــا تعــودان لــي بقصــد االســتعمال وقــد اشــتريتهما مــن شــخص‬\n      ‫باكســتاني داخــل محطــة قبــل نقطــة التفتيــش التــي قبــض علــي فيهــا‬\n      ‫بعشــر دقائــق تقريبـ ًا وقــد أفــدت رجــال األمــن بذلــك عنــد القبــض علــي‬\n      ‫وعرضــت عليهــم أن أذهــب معهــم إلــى نفــس احملطــة حتــى أرشــدهم‬\n      ‫علــى ذلــك الشــخص لكنهــم رفضــوا ولــم يســبق لــي أن اســتعملت‬\n      ‫احلشــيش املخــدر وأنــا نــادم علــى فعلــي تائــب إلــى اهلل تعالــى هكــذا‬\n      ‫أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال بينتــي مــا ذكــرت‬\n      ‫فجــرى الرجــوع إلــى الصفحــة رقم(‪)2‬مــن ملــف التحقيــق املرفــق لفــه‬\n      ‫رقــم(‪ )5‬وتضمنــت ضبــط إفــادة املدعــى عليــه ويف ســؤال لــه منــذ متــى‬\n      ‫تســتعمل احلشــيش املخــدر فأجــاب بقولــه منــذ ســتة أشــهر تقريب ـ ًا ويف‬\n      ‫ســؤال آخــر متــى آخــر مــرة اســتعملت احلشــيش املخــدر فأجــاب بقولــه‬\n\n\n‫‪167‬‬\n\f‫منــذ شــهر تقريب ـ ًا ويف ســؤال ثالــث مــن أيــن حتصــل علــى احلشــيش‬\n‫املخــدر فأجــاب بقولــه مــن أشــخاص أجانــب مــن اجلنســية الباكســتانية‬\n‫علــى طريــق الدمــام وبعــرض هــذه اإلفــادات علــى املدعــى عليــه قــال‬\n‫أمــا اســتعمالي احلشــيش املخــدر فغيــر صحيــح وقــد أخبــرت احملقــق يف‬\n‫مكافحــة املخــدرات بأنــي ال اســتعمل احلشــيش املخــدر فأخبرنــي بعــدم‬\n‫خروجــي مــن الســجن حتــى اعتــرف بذلــك فوافقــت علــى االقــرار مبــا‬\n‫يريــده وأقريــت باســتخدام احلشــيش املخــدر منــذ ســتة أشــهر وأن آخــر‬\n‫مــرة اســتخدمت فيهــا احلشــيش املخــدر كانــت قبــل شــهر وكان ذلــك‬\n‫بطوعــي واختيــاري لكــن بعــد أن أخبرنــي احملقــق بأنــي لــن أخــرج مــن‬\n‫التوقيــف حتــى اعتــرف بذلــك وإال فــإن احلقيقــة هــي أنــي لــم اســتعمل‬\n‫احلشــيش املخــدر يف الســابق نهائي ـ ًا وأمــا بخصــوص مصــدر احلشــيش‬\n‫املخــدر فقــد أخبرتهــم بــأن احلشــيش املخــدر اشــتريته مــن شــخص‬\n‫باكســتاني داخــل محطــة علــى طريــق الريــاض الدمــام قبــل نقطــة‬\n‫التفتيــش بعشــر دقائــق تقريبـ ًا وعرضــت عليهــم أن أذهــب معهــم لنفــس‬\n‫احملطــة كــي أرشــدهم علــى البائــع لكنهــم رفضــوا هكــذا قــرر بعــد‬\n‫ذلــك جــرى الرجــوع إلــى الصفحــة رقــم (‪)1‬مــن ملــف التحقيــق املرفــق‬\n‫لفــه (‪)13‬وتضمنــت ضبــط إفــادة املدعــى عليــه مــن قبــل احملقــق يف‬\n‫هيئــة التحقيــق واالدعــاء العــام وقــد أنكــر املدعــى عليــه اســتعماله مــن‬\n‫الكميــة املضبوطــة ويف ســؤال لــه مــا هــي املعلومــات املتوفــرة لديــك عــن‬\n‫مصــدر احلشــيش فأجــاب املدعــى عليــه بقولــه ال تتوفــر لــدي معلومــات‬\n‫وأول مــرة اشــتري منــه كمــا أفــاد بأنــه باكســتاني اجلنســية وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قــال نعــم لــم يســبق لــي أن اســتعملت احلشــيش‬\n‫املخــدر وأمــا الشــخص الــذي اشــتري منــه فهــو باكســتاني اجلنســية وأما‬\n\n\n                                                                                   ‫‪168‬‬\n\f      ‫جوابــي بأنــه ال تتوفــر لــدي معلومــات بعــد أن ســألني احملقــق عــن مصــدر‬\n      ‫احلشــيش فأنــا أقصــد بأنــه ال يوجــد لــدي معلومــات عمــن يقومــون ببيــع‬\n      ‫احلشــيش املخــدر وأنــا ال زلــت مســتعد للداللــة علــى احملطــة التــي قابلــت‬\n      ‫فيهــا الباكســتاني واشــتريت منــه احلشــيش املخــدر والداللــة علــى‬\n      ‫الشــخص نفســه يف حــال تواجــده هكــذا قــرر بعــد ذلــك جــرى الرجــوع‬\n      ‫إلــى الصفحــة األولــى مــن ملــف التحقيــق املرفــق لفــه رقــم (‪ )5‬وتضمنــت‬\n      ‫محضــر التحريــز وجــاء فيــه وزن املضبوطــات وهــو كمــا ذكــر املدعــي‬\n      ‫العــام يف دعــواه كمــا جــرى الرجــوع إلــى اللفــة رقــم (‪ )27‬وتضمنــت‬\n      ‫التقريــر الكيمــاوي الشــرعي وهــو كمــا ذكــر املدعــي العــام يف دعــواه‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬    ‫فبنـ ً‬\n      ‫بحيازتــه قطعــة احلشــيش املخــدر وســيجارة احلشــيش املخــدر بقصــد‬\n      ‫االســتعمال وحيــث أنكــر املدعــى عليــه اســتعمال احلشــيش املخــدر وملــا‬\n      ‫جــاء يف افادتــه حتقيق ـ ًا باســتعمال احلشــيش املخــدر وحيــث قــرر بأنــه‬\n      ‫أفــاد بتلــك اإلفــادة بطوعــه واختيــاره وحيــث إن رجــوع املدعــى عليــه عــن‬\n      ‫هــذا االقــرار شــبهة يــدرأ بهــا احلــد قــال ابــن قدامــه رحمــه اهلل تعالــى يف‬\n      ‫املغنــي (‪(()95/5‬وال يقبــل رجــوع املقــر عــن اقــراره إال فيمــا كان حــد ًا‬\n      ‫هلل تعالــى يــدرأ بالشــبهات ويحتــاط إلســقاطه))وحيث أنكــر املدعــى‬\n      ‫عليــه تســتره علــى مصــدر احلشــيش املخــدر املضبــوط بحوزتــه وال يوجــد‬\n      ‫يف إفادتــه حتقيقـ ًا مــا يثبــت رفضــه عــن اإلفصــاح عــن مصــدر احلشــيش‬\n      ‫املخــدر بــل إنــه قــد ذكــر جنســية البائــع واملــكان الــذي اشــترى فيــه‬\n      ‫املضبوطــات وأبــدى اســتعداده للداللــة علــى املــكان واإلرشــاد علــى‬\n      ‫البائــع يف حــال تواجــده يف نفــس املــكان وحيــث أبــدى املدعــى عليــه‬\n      ‫ندمــه وتوبتــه وال ســوابق لــه والكميــة املضبوطــة بحوزتــه قليلــة وملــا جــاء‬\n\n\n‫‪169‬‬\n\f‫يف املــواد احلاديــة واألربعــن والسادســة واخلمســن والســتني مــن نظــام‬\n‫مكافحــة املخــدرات لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي حيــازة‬\n‫املدعــى عليــه قطعــة حشــيش مخــدر تــزن (‪)4‬أربــع جرامــات وســيجارة‬\n‫حتتــوي علــى احلشــيش املخــدر تزن(‪)0.6‬ســتة مــن العشــرة مــن اجلــرام‬\n‫بقصــد االســتعمال وقــررت تعزيــره لقــاء ذلــك بســجنه مــدة ثالثــة أشــهر‬\n‫اعتبــار ًا مــن تاريــخ إيقافــه ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني‬\n‫بعــد تنفيــذ عقوبــة الســجن عليــه ثاني ـ ًا درء حــد املســكر عــن املدعــى‬\n‫عليــه وتعزيــره بجلــده ســبعني جلــده علــى دفعتــن متســاويتني بينهمــا مــدة‬\n‫ال تقــل عــن عشــرة أيــام لقــاء اقــراره حتقيقـ ًا باســتعمال احلشــيش املخــدر‬\n‫ثالث ـ ًا عــدم ثبــوت دعــوى املدعــي العــام مــن تســتر املدعــى عليــه علــى‬\n‫مصــدر املخــدرات وبعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي‬\n‫العــام مكتفي ـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة‬\n                         ‫احلاديــة عشــر وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 331494414‬وتاريــخ ‪1434/07/09‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34/1684164‬وتاريــخ ‪1434/7/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ .....‬املســجل برقــم ‪34260118‬‬\n‫وتاريــخ ‪1434/07/04‬ه ـ اخلــاص بدعــوى ‪ /‬املدعــي العام ضد ‪ /‬املدعى‬\n‫عليــه يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/07/29‬ه ـ‬\n                                                                                        ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":164,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"37fd0c864d15f9817443ca6aa6768e46dde7da31d8152b22ef647325326adc96","normalized_text_hash":"e7f83f58fc2c48662c7ffb7ec1d328e8e7d6bb7b7bbaf539a9dbe3f4e01f6e59","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p164-34260118"},{"id":"b9afc9c5-a16c-53df-939b-9134dcf7b852","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -تستر على مصدره -حد املسكر -هروب من رجال األمن -إقرار -إدانة -عقوبة بحدها األعلى -التعزير باجللد والسجن واملنع من السفر -تغليط العقوبة لوجود سوابق.","document_number":"33399240","case_number":"33535027","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/19","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -تستر على مصدره -حد املسكر -هروب من رجال األمن -إقرار -إدانة -عقوبة بحدها األعلى -التعزير باجللد والسجن واملنع من السفر -تغليط العقوبة لوجود سوابق.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33399240:‬تاريخه‪1434/08/19:‬هـ‬\n                         ‫رقم الدعوى‪33535027:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3420097‬تاريخه‪1434/01/24:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬تســتر علــى‬\n      ‫مصــدره ‪ -‬حــد املســكر ‪ -‬هــروب مــن رجــال األمــن‪ -‬إقــرار‪ -‬إدانــة‪ -‬عقوبــة‬\n      ‫بحدهــا األعلــى ‪ -‬التعزيــر باجللــد والســجن واملنــع مــن الســفر‪ -‬تغليط‬\n                                                          ‫العقوبــة لوجــود ســوابق‪.‬‬\n\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي وهربــه مــن الفرقــة القابضــة وتســتره علــى مصــدر مــا‬\n      ‫ضبــط معــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبق ـ ًا‬\n      ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبعقوبــة تعزيريــة بحقــه‬\n      ‫لقــاء باقــي التهــم وتشــديد العقوبــة عليــه لكثــرة ســوابقه وحيــث إنــه‬\n      ‫قــد مت اســتيقاف الســيارة التــي يقودهــا بالقــوة بعــد هربــه مــن دوريــات‬\n      ‫األمــن فقــام بالهــروب علــى قدميــه حتــى مت ضبطــه‪ ،‬وبتفتيــش الســيارة‬\n      ‫عثــر فيهــا علــى قطعــة يشــتبه أن تكــون مــن احلشــيش املخــدر وأثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش‬\n\n‫‪171‬‬\n\f‫املخــدر‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‬\n‫كمــا أقــر بتعاطــي احلشــيش املخــدر‪ ،‬فقضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مــا نســب إليــه وقــررت ســجنه ملــدة ســنتني ومنعــه مــن‬\n‫الســفر خــارج اململكــة ملــدة ســنتني وجلــده ثمانــن جلــدة دفعــة واحــدة‬\n‫حــد املســكر علن ـ ًا وجلــده مائــة وعشــرين جلــدة مفرقــة لباقــي التهــم‪،‬‬\n‫عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪ ،‬وقــررت محكمــة‬\n                          ‫االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33535027‬وتاريــخ ‪1433/08/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم وتاريــخ ‪1433/08/19‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n‫‪1433/08/27‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 :30‬وفيهــا حضــر املدعي‬\n‫العــام وقــدم الئحــة دعــوى عامه نصهــا كالتالي أدعي على ‪ : .....‬اجلنس‪:‬‬\n‫ذكــر اجلنســية‪ :‬ســعودي الديانــة‪ :‬مســلم اللغــة‪ :‬العربيــة تاريــخ امليــاد‪:‬‬\n‫‪1399/12/01‬ه ـ مــكان امليــاد‪ ........ :‬العمــر وقــت اجلرميــة‪ 34 :‬نــوع‬\n‫الهوية‪ :‬السجل املدني رقــم الهويــة‪ :‬تاريــخ اإلصــدار‪1408/05/19 :‬ه ـ‬\n‫جهــة اإلصــدار‪ :‬أحــوال جــازان املهنــة‪ :‬احلالــة االجتماعيــة‪ :‬أعــزب مــكان‬\n‫اإلقامــة‪ :‬الريــاض ‪ -‬حــي ‪ ........‬الشــارع‪........ :‬رقــم املنــزل‪ ........:‬هاتــف‬\n‫املنــزل‪ ........ :‬الهاتــف احملمــول‪ ........ :‬جهــة اإليقــاف‪ :‬شــعبة ســجن امللــز‬\n‫تاريخ القبض‪1433/7/29 :‬هـ حالة املتهم‪ :‬موقوف تاريــخ اإلفــراج‪:‬‬\n‫ال يوجــد االتهــام‪ :‬حيــازة مــواد مخــدرة بقصــد التعاطــي أو االســتعمال‬\n\n                                                                                        ‫‪172‬‬\n\f      ‫الســوابق‪ :‬رقــم احلكــم‪ 8/227 :‬تاريخــه‪1426/06/17 :‬ه ـ مصــدره‪:‬‬\n      ‫م الريــاض اجلرميــة‪ :‬حيــازة واســتعمال مخــدرات ‪ -‬ترويــج املخــدرات‪.‬‬\n      ‫العقوبــة‪75 :‬جلــده ‪ +‬ســجن ‪ 5‬أشــهر ‪ +‬غرامــه ألــف ريــال ومنعــه مــن‬\n      ‫السفر سنتني رقم احلكم‪ 6/28 :‬تاريخه ‪1430/01/15 :‬هـ مص ــدره‪:‬‬\n      ‫احملكمــة اجلزئيــة مبكــة اجلرميــة‪ :‬حيــازة واســتعمال مخــدرات‪ .‬العقوبــة‪:‬‬\n      ‫جلــده ‪ 80‬جلــدة وســجنه ملــدة ‪ 5‬اشــهر مــن توقيفــه ومنعــه مــن الســفر‬\n      ‫ملــدة ســنتني رقــم احلكــم‪/391 :‬د‪/‬ج‪ 9/‬تاريخــه‪1430/06/15 :‬ه ـ‬\n      ‫مصــدره‪ :‬الدائــرة اجلزائيــة التاســعة مبكــة اجلرميــة‪ :‬تزويــر وثائــق‬\n      ‫رســمية‪ .‬العقوبــة‪ :‬ســجنه ســنة مــن توقيفــه وتغرميــه ‪ 1000‬ريــال‪.‬‬\n      ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده حيث أنه بتاريخ‬\n      ‫‪1433/7/29‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق دوريــات‬\n      ‫األمــن مبدينــة الريــاض أثنــاء قيامهــا بعملهــا بحــي ‪........‬حيــث شــاهدت‬\n      ‫ســيارة مــن نــوع ( ‪ )....‬حتمــل لوحــة رقــم (‪ )....‬بهــا صدمــة يف مقدمــة‬\n      ‫الســيارة وعنــد محاولــة اســتيقافه قــام بالهــرب وســار بالســيارة بســرعة‬\n      ‫جنونيــة فجــرى متابعتــه حتــى مت اســتيقاف الســيارة بالقــوة فقــام بالهــرب‬\n      ‫علــى قدميــه حتــى مت ضبطــه والســيطرة عليــه وبتفتيــش الســيارة عثــر يف‬\n      ‫املقعــد األمامــي األميــن علــى قطعــة تــزن (‪ )9,5‬تســعة جرامــات وخمســة‬\n      ‫أعشــار اجلــرام يشــتبه بهــا أن تكــون مــن احلشــيش املخــدر‪ .‬وبســماع‬\n      ‫أقوالــه أقــر بحيازتــه ملــا ضبــط بقصــد التعاطــي ولــم يــدل مبعلومــات عــن‬\n      ‫مصــدر مــا ضبــط‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n      ‫املرفــق رقــم ‪........‬لعــام ‪1433‬ه ـ إيجابيــة عينــة القطعــة املضبوطــة ملــادة‬\n      ‫احلشــيش وهــو مــن املــواد احملظــورة املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ)‬\n\n\n‫‪173‬‬\n\f‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وقــد اســفرت‬\n‫اجــراءات التحقيــق عــن توجيــه االتهــام الــى ‪ ........‬بحيــازة قطعــة مــن‬\n‫احلشــيش املخــدر تــزن (‪ )9,5‬تســعة جرامــات وخمســة أعشــار اجلــرام‬\n‫بقصــد التعاطــي املجــرم علــى ذلــك مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وهربــه مــن الفرقــة القابضة وتســتره على‬\n‫مصــدر مــا ضبــط املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪-1 :‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنوه عنه‬\n‫ا علــى الصفحــة رقــم ( ‪ ) 2‬مــن ملــف إجــراءات االســتدالل‬        ‫املــدون تفصيـ ً‬\n‫املرفــق لفــة رقــم ( ‪ -2 .) 5‬مــا تضمنــه محضــر القبــض املنــوه عنــه املرفــق‬\n‫لفــة رقــم ( ‪ -3 .) 1‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه‬\n‫عنــه املرفــق لفــة رقــم ( ‪ .) 11‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n‫إليــه ‪ ،‬واحلكــم عليــه باآلتــي‪ -1 :‬بعقوبــة تعزيريــة بحقــه وفق ـ ًا للفقــرة‬\n‫(األولــى) مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة لقــاء مــا ُأســند إليــه ‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة‬\n‫بعــد انتهــاء تنفيــذ عقوبــة ســجنه وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪)56‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ -3 .‬بعقوبــة تعزيريــة‬\n‫بحقــه لقــاء هربــه مــن الفرقــة القابضــة و تســتره علــى مصــدر مــا ضبــط‪.‬‬\n‫‪4‬ـ تشــديد العقوبــة عليــه لقــاء كثــرة ســوابقه اســتناد ًا لبرقيــة صاحــب‬\n‫الســمو امللكــي نائــب وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ‬\n‫‪1429/8/23‬ه ـ هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه عمــا جــاء يف‬\n‫دعــوى املدعــي العــام أجــاب بقولــه‪ :‬مــا ذكــره املدعــي العــام صحيــح‬\n\n\n                                                                                        ‫‪174‬‬\n\f      ‫فقــد عثــر بالســيارة نــوع ‪ ....‬التــي كنــت أقودهــا علــى قطعــة حشــيش‬\n      ‫تــزن تســعة جرامــات وخمســة أعشــار اجلــرام عائــده لــي بقصــد التعاطــي‬\n      ‫وقــد تعاطيــت احلشــيش قبــل يومــن مــن القبــض علــي وعنــد طلــب الفرقــة‬\n      ‫القابضــة منــه الوقــوف لــم اقــف ومت اســتيقاف الســيارة التــي أقودهــا‬\n      ‫ثــم هربــت علــى قدمــي وقبــض علــي ويوجــد علــي ثــاث ســوابق منهــا‬\n      ‫ســابقتي اســتعمال حشــيش ونــادم وتائــب وســوف أتــزوج قريبــا هكــذا‬\n      ‫أجــاب فســالته عــن مصــدر مــا ضبــط معــه وقــال إننــي اشــتريتها مــن‬\n      ‫شــخص يف حــي العــود غيــر ســعودي ال اعــرف اســمه وباالطــاع علــى‬\n      ‫املعاملــة وجــدت باللفــة (‪ )11‬صــورة تقريــر صــوره مصدقــه طبــق األصــل‬\n      ‫للتقريــر الكيميائــي رقــم ‪/44/2/8026‬ك يف ‪1433/8/5‬ه ـ مضمونــه‬\n      ‫بالتحليــل الكيميائــي ثبــت لدينــا مــا يلــي‪ :‬املرســل عبــاره عــن قطعــه‬\n      ‫ســمراء تــزن نصــف اجلــرام ثبــت إيجابيهــا ملــادة احلشــيش‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه املدعــي‬\n      ‫العــام يف دعــواه وملــا تضمنــه التقريــر الكيميائــي املنــوه عنــه أعــاه وملــا‬\n      ‫جــاء يف الئحــة الدعــوى واعتــراف املدعــى عليــه بوجــود ثــاث ســوابق‬\n      ‫بحقــه منهــا اثنتــان يف حيــازة واســتعمال مخــدرات وحيــث لــم تردعــه‬\n      ‫العقوبــات الســابقة لــذا حكمــت علــى املدعــى عليــه مبــا يلــي‪ :‬ثبــت لــدي‬\n      ‫ادانــة املدعــى عليــه بحيــازة قطعــة حشــيش تــزن (‪ )9.5‬تســعة جرامــات‬\n      ‫وخمســة اعشــار اجلــرام بقصــد التعاطــي ويعــزر لذلــك بســجنه ســنتني‬\n      ‫اعتبــارا مــن تاريــخ توقيفــه وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن‬\n      ‫نظــام مكافحــة املخــدرات ومنعــه مــن الســفر الــى خــارج اململكــة‬\n      ‫ملــدة ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة ســجنه اعــاه وفقــا للفقــرة‬\n      ‫االولــى مــن املــادة (‪ )56‬مــن ذات النظــام كمــا ثبــت لــدي ادانتــه بتعاطــي‬\n\n\n‫‪175‬‬\n\f‫احلشــيش ويحــد بجلــده ثمانــن جلــده دفعــة واحــده حــد املســكر علنــا‬\n‫وثبــت لــدي ادانتــه بهروبــه مــن الفرقــة القابضــة وتســتره علــى مصــدر‬\n‫مــا ضبــط بحوزتــه ويعــزر بجلــده مائــه وعشــرين جلــده مفرقــه علــى‬\n‫ثــاث دفعــات متســاوية بــن الدفعــة واالخــرى عشــرة ايــام تنفــذ الدفعــة‬\n‫االولــى مــن هــذا اجللــد بعــد عشــرة ايــام مــن تنفيــذ حــد املســكر وبتــاوة‬\n‫احلكــم لــم يقنــع بــه املدعــى عليــه وســوف يتــم طلبــه يــوم االربعــاء املوافــق‬\n‫‪1433/9/6‬ه ـ لتســليمه نســخة احلكــم مــن اجــل تقــدمي الئحــة اعتــراض‬\n‫عليــه وقــرر املدعــي العــام اعتراضــه وانــه يكتفــي بالئحــة الدعــوى عــن‬\n‫الئحــة االعتــراض وعليــه حصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫حــرر يف ‪1433/8/27‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مرفقــا بهــا قــرار احملكمــة ومضمونــه املصادقــة علــى احلكــم‬\n‫باالكثريــة ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه اجمعــن ‪.‬‬\n\n\n\n\n                                                                                          ‫‪176‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":171,"source_page_end":176,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f9318a75fb1b6a2c8d580f246c606ec0f71e02f29143e279e5c3301b08b9504d","normalized_text_hash":"fa50952678c43c20879c7c49f895c5b54b0b0ec3a4c195606cce43cc5c25e391","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p171-33399240"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
